  lcslid       CHAR(32),
  tsswjg_dm    CHAR(11),
  djxh         NUMBER(20),
  ssq          VARCHAR2(60),
  sbpc         VARCHAR2(75),
  sbxh         VARCHAR2(50),
  glh          VARCHAR2(30),
  sz           CHAR(1),
  cktmspzlx_dm CHAR(2),
  jhpzh        VARCHAR2(75),
  kprq         DATE,
  cksp_dm      VARCHAR2(20),
  sbhgspmc     VARCHAR2(500),
  hgjldwmc     VARCHAR2(75),
  sl           NUMBER(16,4),
  jsje         NUMBER(18,2),
  zssl         NUMBER(16,6),
  tsl          NUMBER(16,6),
  tse          NUMBER(18,6),
