prompt
prompt Creating view V_ATFX_QLCCX_SCQY
prompt ===============================
prompt
create or replace force view v_atfx_qlccx_scqy as
(select ck.uuid,ck.djxh,ck.ckbgdh,substr(ck.ckbgdh,1,18) as bgd18,ck.dlckhwzmhm,ck.ckhth,
       ck.hgckhwbgdsbrq,ck.ckny,ck.ckrq_1,
       '('||ck.hzdwdq_dm||')'||hyd.hghyd_mc as hghyd,
       '('||ck.sbdwdm||')'||ck.sbdwmc as sbdw,
       '('||ck.hggqka_dm||')'||ljka.hgmc as hgljka,
       '('||ck.jgfs_dm||')'||jg.tdmc as jgfs,
       '('||ck.hgcjfs_dm||')'||cj.dname as cjfs,
       '('||ck.ysfs_dm||')'||ys.dname as ysfs,
       ck.ysgjmc,ck.hch,
       '('||ck.zyg_dm||')'||zyg.hgzygjc as hgzyg,
       ck.jzxh,ck.bjmmjbz,
       '('||ck.mygdqsz_dm||')'||myg.gb_name as hgmyg,
       '('||ck.zzmdgdqsz_dm||')'||mdg.gb_name as zzmdg,
       ck.tydh,ck.jwshr,
       nvl(hyd.hghyd_mc,ck.hzdwdq_dm)||'（货源地）-'||
       nvl(bgka.hgmc,substr(ck.ckbgdh,1,4))||'（报关口岸）-'||
       nvl(ljka.hgmc,ck.hggqka_dm)||'（离境口岸）-'||
       nvl(ys.dname,ck.ysfs_dm)||'-'||
       nvl(mdg.gb_name,ck.zzmdgdqsz_dm)||'（目的国）' as hwlxt,
       ck.cksp_dm,ck.gfhhgspmc,ck.ggxh,
       '('||ck.dyjldw_dm||')'||dw1.hgjldwmc as dyjldw,
       '('||ck.dejldw_dm||')'||dw2.hgjldwmc as dejldw,
       '('||ck.sbjldw_dm||')'||dw3.hgjldwmc as sbjldw,
       ck.cksl,ck.decksl,ck.sbsl_1,
       ck.jzqks as bgd21zl,
       case when nvl(ck.jzqks,0)<=0
            then null
            else round(ck.rmblaj/ck.jzqks,6)
       end as bgd21zldj,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then ck.cksl
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then ck.decksl
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then ck.sbsl_1
            else null
       end as bgd21sl,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then round(ck.rmblaj/ck.cksl,6)
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then round(ck.rmblaj/ck.decksl,6)
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then round(ck.rmblaj/ck.sbsl_1,6)
            else null
       end as bgd21sldj,
       '('||ck.cjhghbsz_dm||')'||cjbz.hbzl_mc as cjhgbz,
       ck.cjzj,
       '('||ck.yfhghbsz_dm||')'||yfbz.hbzl_mc as yfhgbz,
       '('||ck.yfjsfs_dm||')'||decode(ck.yfjsfs_dm,'1','费率','2','单价','3','总价',null) as yfjsfs,
       ck.yfhl,
       '('||ck.bfhghbsz_dm||')'||bfbz.hbzl_mc as bfhgbz,
       '('||ck.bfjsfs_dm||')'||decode(ck.bfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.bfhl,
       '('||ck.zfhghbsz_dm||')'||zfbz.hbzl_mc as zfhgbz,
       '('||ck.zfjsfs_dm||')'||decode(ck.zfjsfs_dm,'1','费率','2','单价','3','总价',null) as zfjsfs,
       ck.zfhl,
       ck.mylaj,ck.rmblaj,ck.js_1,ck.mz_2,ck.jz,
       mdt.ssq||mdt.sbxh as cytssbjl,
       '自行申报' as tssblx,
       mdt.rmblaj as sbrmbxse,
       mdt.jsfpl,
       mdt.zssl,mdt.tsl,mdt.mdtsbdmzhdkse,mdt.mdtse
  from tl_tssh.atfx_ck_ys_ckdzxx ck
  left join tl_tssh.atfx_ts_ys_mdtssbb mdt
    on mdt.djxh=ck.djxh and (mdt.ckbgdh=ck.ckbgdh or mdt.dlckhwzmhm=ck.dlckhwzmhm)
  left join tl_admin.dm_hghyd hyd
    on hyd.hghyd_dm=ck.hzdwdq_dm
  left join tl_admin.dm_hgcode bgka
    on bgka.hgcode=substr(ck.ckbgdh,1,4)
  left join tl_admin.dm_hgcode ljka
    on ljka.hgcode=ck.hggqka_dm
  left join tl_admin.dm_tdcode jg
    on jg.tdcode=ck.jgfs_dm
  left join tl_admin.sys_dict cj
    on cj.dtype='cjfs' and cj.dcode=ck.hgcjfs_dm
  left join tl_admin.sys_dict ys
    on ys.dtype='ysfs' and ys.dcode=ck.ysfs_dm
  left join tl_admin.dm_hgzyg zyg
    on zyg.hgzyg_dm=ck.zyg_dm
  left join tl_admin.dm_gbcode myg
    on myg.gb_code=ck.mygdqsz_dm
  left join tl_admin.dm_gbcode mdg
    on mdg.gb_code=ck.zzmdgdqsz_dm
  left join tl_admin.dm_hbzl_hg cjbz
    on cjbz.hbzl_hg=ck.cjhghbsz_dm
  left join tl_admin.dm_hbzl_hg yfbz
    on yfbz.hbzl_hg=ck.yfhghbsz_dm
  left join tl_admin.dm_hbzl_hg bfbz
    on bfbz.hbzl_hg=ck.bfhghbsz_dm
  left join tl_admin.dm_hbzl_hg zfbz
    on zfbz.hbzl_hg=ck.zfhghbsz_dm
  left join tl_bjts.ckts_dm_hgjldw dw1
    on dw1.hgjldw_dm=ck.dyjldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw2
    on dw2.hgjldw_dm=ck.dejldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw3
    on dw3.hgjldw_dm=ck.sbjldw_dm
 where ck.ydjxh is null
 union all
select ck.uuid,ck.djxh,ck.ckbgdh,substr(ck.ckbgdh,1,18) as bgd18,ck.dlckhwzmhm,ck.ckhth,
       ck.hgckhwbgdsbrq,ck.ckny,ck.ckrq_1,
       '('||ck.hzdwdq_dm||')'||hyd.hghyd_mc as hghyd,
       '('||ck.sbdwdm||')'||ck.sbdwmc as sbdw,
       '('||ck.hggqka_dm||')'||ljka.hgmc as hgljka,
       '('||ck.jgfs_dm||')'||jg.tdmc as jgfs,
       '('||ck.hgcjfs_dm||')'||cj.dname as cjfs,
       '('||ck.ysfs_dm||')'||ys.dname as ysfs,
       ck.ysgjmc,ck.hch,
       '('||ck.zyg_dm||')'||zyg.hgzygjc as hgzyg,
       ck.jzxh,ck.bjmmjbz,
       '('||ck.mygdqsz_dm||')'||myg.gb_name as hgmyg,
       '('||ck.zzmdgdqsz_dm||')'||mdg.gb_name as zzmdg,
       ck.tydh,ck.jwshr,
       nvl(hyd.hghyd_mc,ck.hzdwdq_dm)||'（货源地）-'||
       nvl(bgka.hgmc,substr(ck.ckbgdh,1,4))||'（报关口岸）-'||
       nvl(ljka.hgmc,ck.hggqka_dm)||'（离境口岸）-'||
       nvl(ys.dname,ck.ysfs_dm)||'-'||
       nvl(mdg.gb_name,ck.zzmdgdqsz_dm)||'（目的国）' as hwlxt,
       ck.cksp_dm,ck.gfhhgspmc,ck.ggxh,
       '('||ck.dyjldw_dm||')'||dw1.hgjldwmc as dyjldw,
       '('||ck.dejldw_dm||')'||dw2.hgjldwmc as dejldw,
       '('||ck.sbjldw_dm||')'||dw3.hgjldwmc as sbjldw,
       ck.cksl,ck.decksl,ck.sbsl_1,
       ck.jzqks as bgd21zl,
       case when nvl(ck.jzqks,0)<=0
            then null
            else round(ck.rmblaj/ck.jzqks,6)
       end as bgd21zldj,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then ck.cksl
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then ck.decksl
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then ck.sbsl_1
            else null
       end as bgd21sl,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then round(ck.rmblaj/ck.cksl,6)
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then round(ck.rmblaj/ck.decksl,6)
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then round(ck.rmblaj/ck.sbsl_1,6)
            else null
       end as bgd21sldj,
       '('||ck.cjhghbsz_dm||')'||cjbz.hbzl_mc as cjhgbz,
       ck.cjzj,
       '('||ck.yfhghbsz_dm||')'||yfbz.hbzl_mc as yfhgbz,
       '('||ck.yfjsfs_dm||')'||decode(ck.yfjsfs_dm,'1','费率','2','单价','3','总价',null) as yfjsfs,
       ck.yfhl,
       '('||ck.bfhghbsz_dm||')'||bfbz.hbzl_mc as bfhgbz,
       '('||ck.bfjsfs_dm||')'||decode(ck.bfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.bfhl,
       '('||ck.zfhghbsz_dm||')'||zfbz.hbzl_mc as zfhgbz,
       '('||ck.zfjsfs_dm||')'||decode(ck.zfjsfs_dm,'1','费率','2','单价','3','总价',null) as zfjsfs,
       ck.zfhl,
       ck.mylaj,ck.rmblaj,ck.js_1,ck.mz_2,ck.jz,
       wtdb.ssq||wtdb.sbpc||wtdb.sbxh as cytssbjl,
       '委托代办' as tssblx,
       wtdb.jsje as sbrmbxse,
       null as jsfpl,
       wtdb.zssl,wtdb.tsl,null as mdtsbdmzhdkse,wtdb.tse as mdtse
  from tl_tssh.atfx_ck_ys_ckdzxx ck
  left join tl_tssh.atfx_ts_ys_wtdbtssbb wtdb
    on wtdb.djxh=ck.djxh and wtdb.ckbgdh=ck.ckbgdh
  left join tl_admin.dm_hghyd hyd
    on hyd.hghyd_dm=ck.hzdwdq_dm
  left join tl_admin.dm_hgcode bgka
    on bgka.hgcode=substr(ck.ckbgdh,1,4)
  left join tl_admin.dm_hgcode ljka
    on ljka.hgcode=ck.hggqka_dm
  left join tl_admin.dm_tdcode jg
    on jg.tdcode=ck.jgfs_dm
  left join tl_admin.sys_dict cj
    on cj.dtype='cjfs' and cj.dcode=ck.hgcjfs_dm
  left join tl_admin.sys_dict ys
    on ys.dtype='ysfs' and ys.dcode=ck.ysfs_dm
  left join tl_admin.dm_hgzyg zyg
    on zyg.hgzyg_dm=ck.zyg_dm
  left join tl_admin.dm_gbcode myg
    on myg.gb_code=ck.mygdqsz_dm
  left join tl_admin.dm_gbcode mdg
    on mdg.gb_code=ck.zzmdgdqsz_dm
  left join tl_admin.dm_hbzl_hg cjbz
    on cjbz.hbzl_hg=ck.cjhghbsz_dm
  left join tl_admin.dm_hbzl_hg yfbz
    on yfbz.hbzl_hg=ck.yfhghbsz_dm
  left join tl_admin.dm_hbzl_hg bfbz
    on bfbz.hbzl_hg=ck.bfhghbsz_dm
  left join tl_admin.dm_hbzl_hg zfbz
    on zfbz.hbzl_hg=ck.zfhghbsz_dm
  left join tl_bjts.ckts_dm_hgjldw dw1
    on dw1.hgjldw_dm=ck.dyjldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw2
    on dw2.hgjldw_dm=ck.dejldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw3
    on dw3.hgjldw_dm=ck.sbjldw_dm
 where ck.ydjxh is not null);

prompt
prompt Creating view V_ATFX_QLCCX_WMQY
prompt ===============================
prompt
create or replace force view v_atfx_qlccx_wmqy as
select ck.uuid,ck.djxh,ck.ckbgdh,substr(ck.ckbgdh,1,18) as bgd18,ck.dlckhwzmhm,ck.ckhth,
       ck.hgckhwbgdsbrq,ck.ckny,ck.ckrq_1,
       '('||ck.hzdwdq_dm||')'||hyd.hghyd_mc as hghyd,
       '('||ck.sbdwdm||')'||ck.sbdwmc as sbdw,
       '('||ck.hggqka_dm||')'||ljka.hgmc as hgljka,
       '('||ck.jgfs_dm||')'||jg.tdmc as jgfs,
       '('||ck.hgcjfs_dm||')'||cj.dname as cjfs,
       '('||ck.ysfs_dm||')'||ys.dname as ysfs,
       ck.ysgjmc,ck.hch,
       '('||ck.zyg_dm||')'||zyg.hgzygjc as hgzyg,
       ck.jzxh,ck.bjmmjbz,
       '('||ck.mygdqsz_dm||')'||myg.gb_name as hgmyg,
       '('||ck.zzmdgdqsz_dm||')'||mdg.gb_name as zzmdg,
       ck.tydh,ck.jwshr,
       nvl(xz.mc,nvl(hyd.hghyd_mc,ck.hzdwdq_dm))||'（货源地）-'||
       nvl(bgka.hgmc,substr(ck.ckbgdh,1,4))||'（报关口岸）-'||
       nvl(ljka.hgmc,ck.hggqka_dm)||'（离境口岸）-'||
       nvl(ys.dname,ck.ysfs_dm)||'-'||
       nvl(mdg.gb_name,ck.zzmdgdqsz_dm)||'（目的国）' as hwlxt,
       ck.cksp_dm,ck.gfhhgspmc,ck.ggxh,
       '('||ck.dyjldw_dm||')'||dw1.hgjldwmc as dyjldw,
       '('||ck.dejldw_dm||')'||dw2.hgjldwmc as dejldw,
       '('||ck.sbjldw_dm||')'||dw3.hgjldwmc as sbjldw,
       ck.cksl,ck.decksl,ck.sbsl_1,
       ck.jzqks as bgd21zl,
       case when nvl(ck.jzqks,0)<=0
            then null
            else round(ck.rmblaj/ck.jzqks,6)
       end as bgd21zldj,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then ck.cksl
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then ck.decksl
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then ck.sbsl_1
            else null
       end as bgd21sl,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then round(ck.rmblaj/ck.cksl,6)
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then round(ck.rmblaj/ck.decksl,6)
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then round(ck.rmblaj/ck.sbsl_1,6)
            else null
       end as bgd21sldj,
       '('||ck.cjhghbsz_dm||')'||cjbz.hbzl_mc as cjhgbz,
       ck.cjzj,
       '('||ck.yfhghbsz_dm||')'||yfbz.hbzl_mc as yfhgbz,
       '('||ck.yfjsfs_dm||')'||decode(ck.yfjsfs_dm,'1','费率','2','单价','3','总价',null) as yfjsfs,
       ck.yfhl,
       '('||ck.bfhghbsz_dm||')'||bfbz.hbzl_mc as bfhgbz,
       '('||ck.bfjsfs_dm||')'||decode(ck.bfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.bfhl,
       '('||ck.zfhghbsz_dm||')'||zfbz.hbzl_mc as zfhgbz,
       '('||ck.zfjsfs_dm||')'||decode(ck.zfjsfs_dm,'1','费率','2','单价','3','总价',null) as zfjsfs,
       ck.zfhl,
       ck.mylaj,ck.rmblaj,ck.js_1,ck.mz_2,ck.jz,
       mts.ssq||mts.sbpc||mts.sbxh as cytssbjl,
       '自营业务' as tssblx,
       mts.glh,
       mts.hgjldwmc as mtssb_jldw,
       mts.cksl as mtssb_cksl,
       jh.sl as mtssb_jhsl,
       jh.jhpzh,
       (select listagg(fp.xh||'-'||fp.hwhyslwfwmc||'-'||fp.jldw||'-'||fp.fpspsl,',') within group (order by fp.xh)
          from tl_tssh.atfx_fp_ys_jhfpxx fp
         where fp.djxh=ck.djxh
           and fp.fphm=jh.jhpzh
           and fp.hwhyslwfwmc like '%'||substr(ck.gfhhgspmc,1,least(25,length(ck.gfhhgspmc)))||'%' and rownum<=5) as fpxx,
       --fp.fpspsl,fp.jldw,
       gys.gyssbh,gys.gysmc,
       '('||substr(gys.gys_qxswjg_dm,1,5)||')'||xz.mc as gysszd,
       gys.gys_djrq,
       jh.kprq,
       trunc(jh.kprq)-trunc(ck.ckrq_1) as kpzhts,
       jh.jsje,jh.tsl,jh.tse,
       mts.rmblaj as bgd21sr,
       mts.ckjhje as bgd21cb,
       mts.rmblaj-mts.ckjhje as bgd21lr,
       round(100*(mts.rmblaj-mts.ckjhje)/mts.rmblaj,2) as bgd21lrl
  from tl_tssh.atfx_ck_ys_ckdzxx ck
 inner join tl_tssh.atfx_ts_ys_ckmxsbb mts
    on mts.djxh=ck.djxh and (mts.ckbgdh=ck.ckbgdh or mts.dlzmh=ck.dlckhwzmhm)
   and mts.cksl>0 --剔除红字冲减数据
   and not exists (select 1 from tl_tssh.atfx_ts_ys_ckmxsbb hzcj
       where hzcj.djxh=mts.djxh and hzcj.glh=mts.glh and hzcj.cksl<0) -- 剔除被冲减关联号
  left join tl_tssh.atfx_ts_ys_jhmxsbb jh
    on jh.djxh=ck.djxh and jh.lcslid=mts.lcslid
   and jh.glh=mts.glh and jh.cksp_dm=mts.cksp_dm
  left join tl_tssh.atfx_fp_jg_gysjcxx gys
    on gys.djxh=ck.djxh and gys.gyssbh=jh.ghfnsrsbh_1
  left join tl_admin.dm_xzqh xz
    on xz.dm=case when gys.gys_qxswjg_dm like '133%'
                  then substr(gys.gys_qxswjg_dm,2,4)
                  else substr(gys.gys_qxswjg_dm,2,2) end
  left join tl_admin.dm_hghyd hyd
    on hyd.hghyd_dm=ck.hzdwdq_dm
  left join tl_admin.dm_hgcode bgka
    on bgka.hgcode=substr(ck.ckbgdh,1,4)
  left join tl_admin.dm_hgcode ljka
    on ljka.hgcode=ck.hggqka_dm
  left join tl_admin.dm_tdcode jg
    on jg.tdcode=ck.jgfs_dm
  left join tl_admin.sys_dict cj
    on cj.dtype='cjfs' and cj.dcode=ck.hgcjfs_dm
  left join tl_admin.sys_dict ys
    on ys.dtype='ysfs' and ys.dcode=ck.ysfs_dm
  left join tl_admin.dm_hgzyg zyg
    on zyg.hgzyg_dm=ck.zyg_dm
  left join tl_admin.dm_gbcode myg
    on myg.gb_code=ck.mygdqsz_dm
  left join tl_admin.dm_gbcode mdg
    on mdg.gb_code=ck.zzmdgdqsz_dm
  left join tl_admin.dm_hbzl_hg cjbz
    on cjbz.hbzl_hg=ck.cjhghbsz_dm
  left join tl_admin.dm_hbzl_hg yfbz
    on yfbz.hbzl_hg=ck.yfhghbsz_dm
  left join tl_admin.dm_hbzl_hg bfbz
    on bfbz.hbzl_hg=ck.bfhghbsz_dm
  left join tl_admin.dm_hbzl_hg zfbz
    on zfbz.hbzl_hg=ck.zfhghbsz_dm
  left join tl_bjts.ckts_dm_hgjldw dw1
    on dw1.hgjldw_dm=ck.dyjldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw2
    on dw2.hgjldw_dm=ck.dejldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw3
    on dw3.hgjldw_dm=ck.sbjldw_dm
 union all
select ck.uuid,ck.djxh,ck.ckbgdh,substr(ck.ckbgdh,1,18) as bgd18,ck.dlckhwzmhm,ck.ckhth,
       ck.hgckhwbgdsbrq,ck.ckny,ck.ckrq_1,
       '('||ck.hzdwdq_dm||')'||hyd.hghyd_mc as hghyd,
       '('||ck.sbdwdm||')'||ck.sbdwmc as sbdw,
       '('||ck.hggqka_dm||')'||ljka.hgmc as hgljka,
       '('||ck.jgfs_dm||')'||jg.tdmc as jgfs,
       '('||ck.hgcjfs_dm||')'||cj.dname as cjfs,
       '('||ck.ysfs_dm||')'||ys.dname as ysfs,
       ck.ysgjmc,ck.hch,
       '('||ck.zyg_dm||')'||zyg.hgzygjc as hgzyg,
       ck.jzxh,ck.bjmmjbz,
       '('||ck.mygdqsz_dm||')'||myg.gb_name as hgmyg,
       '('||ck.zzmdgdqsz_dm||')'||mdg.gb_name as zzmdg,
       ck.tydh,ck.jwshr,
       nvl(xz.mc,nvl(hyd.hghyd_mc,ck.hzdwdq_dm))||'（货源地）-'||
       nvl(bgka.hgmc,substr(ck.ckbgdh,1,4))||'（报关口岸）-'||
       nvl(ljka.hgmc,ck.hggqka_dm)||'（离境口岸）-'||
       nvl(ys.dname,ck.ysfs_dm)||'-'||
       nvl(mdg.gb_name,ck.zzmdgdqsz_dm)||'（目的国）' as hwlxt,
       ck.cksp_dm,ck.gfhhgspmc,ck.ggxh,
       '('||ck.dyjldw_dm||')'||dw1.hgjldwmc as dyjldw,
       '('||ck.dejldw_dm||')'||dw2.hgjldwmc as dejldw,
       '('||ck.sbjldw_dm||')'||dw3.hgjldwmc as sbjldw,
       ck.cksl,ck.decksl,ck.sbsl_1,
       ck.jzqks as bgd21zl,
       case when nvl(ck.jzqks,0)<=0
            then null
            else round(ck.rmblaj/ck.jzqks,6)
       end as bgd21zldj,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then ck.cksl
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then ck.decksl
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then ck.sbsl_1
            else null
       end as bgd21sl,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then round(ck.rmblaj/ck.cksl,6)
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then round(ck.rmblaj/ck.decksl,6)
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then round(ck.rmblaj/ck.sbsl_1,6)
            else null
       end as bgd21sldj,
       '('||ck.cjhghbsz_dm||')'||cjbz.hbzl_mc as cjhgbz,
       ck.cjzj,
       '('||ck.yfhghbsz_dm||')'||yfbz.hbzl_mc as yfhgbz,
       '('||ck.yfjsfs_dm||')'||decode(ck.yfjsfs_dm,'1','费率','2','单价','3','总价',null) as yfjsfs,
       ck.yfhl,
       '('||ck.bfhghbsz_dm||')'||bfbz.hbzl_mc as bfhgbz,
       '('||ck.bfjsfs_dm||')'||decode(ck.bfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.bfhl,
       '('||ck.zfhghbsz_dm||')'||zfbz.hbzl_mc as zfhgbz,
       '('||ck.zfjsfs_dm||')'||decode(ck.zfjsfs_dm,'1','费率','2','单价','3','总价',null) as zfjsfs,
       ck.zfhl,
       ck.mylaj,ck.rmblaj,ck.js_1,ck.mz_2,ck.jz,
       dbts.ssq||dbts.sbpc||dbts.sbxh as cytssbjl,
       '代办退税' as tssblx,
       null as glh,
       dbts.hgjldwmc as mtssb_jldw,dbts.cksl as mtssb_cksl,dbts.cksl as mtssb_jhsl,dbts.dbtswspzhm as jhpzh,
       (select listagg(fp.xh||'-'||fp.hwhyslwfwmc||'-'||fp.jldw||'-'||fp.fpspsl,',') within group (order by fp.xh)
          from tl_tssh.atfx_fp_ys_jhfpxx fp
         where fp.djxh=ck.djxh
           and fp.fphm=dbts.dbtswspzhm
           and fp.hwhyslwfwmc like '%'||substr(ck.gfhhgspmc,1,least(25,length(ck.gfhhgspmc)))||'%' and rownum<=5) as fpxx,
       --fp.fpspsl,fp.jldw,
       gys.gyssbh,gys.gysmc,
       '('||substr(gys.gys_qxswjg_dm,1,5)||')'||xz.mc as gysszd,
       gys.gys_djrq,
       dbts.kprq,
       trunc(dbts.kprq)-trunc(ck.ckrq_1) as kpzhts,
       dbts.jsje,dbts.tsl,dbts.tse,
       round(ck.rmblaj * dbts.mylaj/ck.mylaj,2) as bgd21sr,
       dbts.jsje as bgd21cb,
       round(ck.rmblaj * dbts.mylaj/ck.mylaj,2)-dbts.jsje as bgd21lr,
       round(100*(round(ck.rmblaj * dbts.mylaj/ck.mylaj,2)-dbts.jsje)/round(ck.rmblaj * dbts.mylaj/ck.mylaj,2),2) as bgd21lrl
  from tl_tssh.atfx_ck_ys_ckdzxx ck
 inner join tl_tssh.atfx_ts_ys_dbtssbb dbts
    on dbts.djxh=ck.djxh and dbts.ckbgdh=ck.ckbgdh
  left join tl_tssh.atfx_fp_jg_gysjcxx gys
    on gys.djxh=ck.djxh and gys.gyssbh=dbts.wtdbtsscqynsrsbh
  left join tl_admin.dm_xzqh xz
    on xz.dm=case when gys.gys_qxswjg_dm like '133%'
                  then substr(gys.gys_qxswjg_dm,2,4)
                  else substr(gys.gys_qxswjg_dm,2,2) end
  left join tl_admin.dm_hghyd hyd
    on hyd.hghyd_dm=ck.hzdwdq_dm
  left join tl_admin.dm_hgcode bgka
    on bgka.hgcode=substr(ck.ckbgdh,1,4)
  left join tl_admin.dm_hgcode ljka
    on ljka.hgcode=ck.hggqka_dm
  left join tl_admin.dm_tdcode jg
    on jg.tdcode=ck.jgfs_dm
  left join tl_admin.sys_dict cj
    on cj.dtype='cjfs' and cj.dcode=ck.hgcjfs_dm
  left join tl_admin.sys_dict ys
    on ys.dtype='ysfs' and ys.dcode=ck.ysfs_dm
  left join tl_admin.dm_hgzyg zyg
    on zyg.hgzyg_dm=ck.zyg_dm
  left join tl_admin.dm_gbcode myg
    on myg.gb_code=ck.mygdqsz_dm
  left join tl_admin.dm_gbcode mdg
    on mdg.gb_code=ck.zzmdgdqsz_dm
  left join tl_admin.dm_hbzl_hg cjbz
    on cjbz.hbzl_hg=ck.cjhghbsz_dm
  left join tl_admin.dm_hbzl_hg yfbz
    on yfbz.hbzl_hg=ck.yfhghbsz_dm
  left join tl_admin.dm_hbzl_hg bfbz
    on bfbz.hbzl_hg=ck.bfhghbsz_dm
  left join tl_admin.dm_hbzl_hg zfbz
    on zfbz.hbzl_hg=ck.zfhghbsz_dm
  left join tl_bjts.ckts_dm_hgjldw dw1
    on dw1.hgjldw_dm=ck.dyjldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw2
    on dw2.hgjldw_dm=ck.dejldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw3
    on dw3.hgjldw_dm=ck.sbjldw_dm
 union all
select ck.uuid,ck.djxh,ck.ckbgdh,substr(ck.ckbgdh,1,18) as bgd18,ck.dlckhwzmhm,ck.ckhth,
       ck.hgckhwbgdsbrq,ck.ckny,ck.ckrq_1,
       '('||ck.hzdwdq_dm||')'||hyd.hghyd_mc as hghyd,
       '('||ck.sbdwdm||')'||ck.sbdwmc as sbdw,
       '('||ck.hggqka_dm||')'||ljka.hgmc as hgljka,
       '('||ck.jgfs_dm||')'||jg.tdmc as jgfs,
       '('||ck.hgcjfs_dm||')'||cj.dname as cjfs,
       '('||ck.ysfs_dm||')'||ys.dname as ysfs,
       ck.ysgjmc,ck.hch,
       '('||ck.zyg_dm||')'||zyg.hgzygjc as hgzyg,
       ck.jzxh,ck.bjmmjbz,
       '('||ck.mygdqsz_dm||')'||myg.gb_name as hgmyg,
       '('||ck.zzmdgdqsz_dm||')'||mdg.gb_name as zzmdg,
       ck.tydh,ck.jwshr,
       nvl(hyd.hghyd_mc,ck.hzdwdq_dm)||'（货源地）-'||
       nvl(bgka.hgmc,substr(ck.ckbgdh,1,4))||'（报关口岸）-'||
       nvl(ljka.hgmc,ck.hggqka_dm)||'（离境口岸）-'||
       nvl(ys.dname,ck.ysfs_dm)||'-'||
       nvl(mdg.gb_name,ck.zzmdgdqsz_dm)||'（目的国）' as hwlxt,
       ck.cksp_dm,ck.gfhhgspmc,ck.ggxh,
       '('||ck.dyjldw_dm||')'||dw1.hgjldwmc as dyjldw,
       '('||ck.dejldw_dm||')'||dw2.hgjldwmc as dejldw,
       '('||ck.sbjldw_dm||')'||dw3.hgjldwmc as sbjldw,
       ck.cksl,ck.decksl,ck.sbsl_1,
       ck.jzqks as bgd21zl,
       case when nvl(ck.jzqks,0)<=0
            then null
            else round(ck.rmblaj/ck.jzqks,6)
       end as bgd21zldj,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then ck.cksl
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then ck.decksl
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then ck.sbsl_1
            else null
       end as bgd21sl,
       case when ck.dyjldw_dm is not null and ck.dyjldw_dm not in ('09','39','49','59') and ck.cksl>0
            then round(ck.rmblaj/ck.cksl,6)
            when ck.dejldw_dm is not null and ck.dejldw_dm not in ('09','39','49','59') and ck.decksl>0
            then round(ck.rmblaj/ck.decksl,6)
            when ck.sbjldw_dm is not null and ck.sbjldw_dm not in ('035','036','047','070','071','072','073','074','075','076','077','078','079','080','081','083','084') and ck.sbsl_1>0
            then round(ck.rmblaj/ck.sbsl_1,6)
            else null
       end as bgd21sldj,
       '('||ck.cjhghbsz_dm||')'||cjbz.hbzl_mc as cjhgbz,
       ck.cjzj,
       '('||ck.yfhghbsz_dm||')'||yfbz.hbzl_mc as yfhgbz,
       '('||ck.yfjsfs_dm||')'||decode(ck.yfjsfs_dm,'1','费率','2','单价','3','总价',null) as yfjsfs,
       ck.yfhl,
       '('||ck.bfhghbsz_dm||')'||bfbz.hbzl_mc as bfhgbz,
       '('||ck.bfjsfs_dm||')'||decode(ck.bfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.bfhl,
       '('||ck.zfhghbsz_dm||')'||zfbz.hbzl_mc as zfhgbz,
       '('||ck.zfjsfs_dm||')'||decode(ck.zfjsfs_dm,'1','费率','2','单价','3','总价',null) as bfjsfs,
       ck.zfhl,
       ck.mylaj,ck.rmblaj,ck.js_1,ck.mz_2,ck.jz,
       null as cytssbjl,
       '未申报' as tssblx,
       null as glh,
       null as mtssb_jldw,null as mtssb_cksl,null as mtssb_jhsl,null as jhpzh,
       null as fpxx,
       null as gyssbh,null as gysmc,
       null as gysszd,
       null as gys_djrq,
       null as kprq,
       null as kpzhts,
       null as jsje,null as tsl,null as tse,
       null as bgd21sr,
       null as bgd21cb,
       null as bgd21lr,
       null as bgd21lrl
  from tl_tssh.atfx_ck_ys_ckdzxx ck
  left join tl_admin.dm_hghyd hyd
    on hyd.hghyd_dm=ck.hzdwdq_dm
  left join tl_admin.dm_hgcode bgka
    on bgka.hgcode=substr(ck.ckbgdh,1,4)
  left join tl_admin.dm_hgcode ljka
    on ljka.hgcode=ck.hggqka_dm
  left join tl_admin.dm_tdcode jg
    on jg.tdcode=ck.jgfs_dm
  left join tl_admin.sys_dict cj
    on cj.dtype='cjfs' and cj.dcode=ck.hgcjfs_dm
  left join tl_admin.sys_dict ys
    on ys.dtype='ysfs' and ys.dcode=ck.ysfs_dm
  left join tl_admin.dm_hgzyg zyg
    on zyg.hgzyg_dm=ck.zyg_dm
  left join tl_admin.dm_gbcode myg
    on myg.gb_code=ck.mygdqsz_dm
  left join tl_admin.dm_gbcode mdg
    on mdg.gb_code=ck.zzmdgdqsz_dm
  left join tl_admin.dm_hbzl_hg cjbz
    on cjbz.hbzl_hg=ck.cjhghbsz_dm
  left join tl_admin.dm_hbzl_hg yfbz
    on yfbz.hbzl_hg=ck.yfhghbsz_dm
  left join tl_admin.dm_hbzl_hg bfbz
    on bfbz.hbzl_hg=ck.bfhghbsz_dm
  left join tl_admin.dm_hbzl_hg zfbz
    on zfbz.hbzl_hg=ck.zfhghbsz_dm
  left join tl_bjts.ckts_dm_hgjldw dw1
    on dw1.hgjldw_dm=ck.dyjldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw2
    on dw2.hgjldw_dm=ck.dejldw_dm
  left join tl_bjts.ckts_dm_hgjldw dw3
    on dw3.hgjldw_dm=ck.sbjldw_dm
 where not exists (select 1 from tl_tssh.atfx_ts_ys_ckmxsbb mts
                    where mts.djxh=ck.djxh and (mts.ckbgdh=ck.ckbgdh or mts.dlzmh=ck.dlckhwzmhm)
                    union all
                   select 1 from tl_tssh.atfx_ts_ys_dbtssbb dbts
                    where dbts.djxh=ck.djxh and dbts.ckbgdh=ck.ckbgdh)
;

prompt
prompt Creating view V_CKTS_WBSJ_HG_BGD
prompt ================================
prompt
create or replace force view v_ckts_wbsj_hg_bgd as
select nvl(a.shxyno,a.nsrdjno) as nsrsbh,a.nsrmc,a.qyhgdm,a.swjgdm,
    a.flglcd,a.qylx,a.jsmode,a.zx_flag,a.nsrzt_js,a.hydm,a.djzclx_js,a.ckgm_dm,
    b.CKNY,b.HGGQKA_DM,b.CKBGDH,substr(b.CKBGDH,1,18) as bgdh18,CKRQ_1,
    b.CKSP_DM,b.CKSPMC,b.HGSPMC,b.GGXH,b.HGJLDWMC,
    b.DYJLDW_DM,b.CKSL,b.RMBLAJ,b.MYLAJ,
    ROUND(b.MYLAJ/decode(b.cksl,0,1,b.CKSL),2) as MYDJ,
    b.MYGDQSZ_DM,b.ZZMDGDQSZ_DM,b.ZYG_DM,b.JGFS_DM,
    b.YSFS_DM,
    b.BAH,b.JYDWMC,b.SBDWDM,b.SBDWMC,
    b.HZDWDM,b.HZDWMC,b.HZDWDQ_DM
    from glxt_bb_shxt_djxx a,ckts_wbsj_hg_bgd b
    where a.cpcode=b.djxh;

prompt
prompt Creating view V_GLXT_BB_SHXT_DJXX
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW V_GLXT_BB_SHXT_DJXX AS
SELECT T.SWJGDM, S.SWJG_JC, T.QYHGDM, NVL(T.SHXYNO,T.NSRDJNO) AS NSRSBH, T.NSRMC, T.ADDRESS_ZC, T.ADDRESS_JY, T.FRDB_MC, T.BSY, T.BSY_TEL,
       TRUNC(T.YBNSR_DATE) AS YBNSR_DATE, TRUNC(T.SQ_DATE) AS SQ_DATE, T.JSMODE, T.FLGLCD, T.BKNAME,
       T.CK_BGDFS,
       CASE WHEN T.CK_BGDFS>100000000 THEN 'S'||TRUNC(T.CK_BGDFS/100000000,1)
            WHEN T.CK_BGDFS>10000000 THEN 'A'||FLOOR(T.CK_BGDFS/10000000)
            WHEN T.CK_BGDFS>1000000 THEN 'B'||FLOOR(T.CK_BGDFS/1000000)
            WHEN T.CK_BGDFS>100000 THEN 'C'||FLOOR(T.CK_BGDFS/100000)
            WHEN T.CK_BGDFS>10000 THEN 'D'||FLOOR(T.CK_BGDFS/10000)
            ELSE 'E' END AS CKMYLAJ_DJ,
       CASE WHEN T.CKGM>100000000 THEN 'S'||TRUNC(T.CKGM/100000000,1)
            WHEN T.CKGM>10000000 THEN 'A'||FLOOR(T.CKGM/10000000)
            WHEN T.CKGM>1000000 THEN 'B'||FLOOR(T.CKGM/1000000)
            WHEN T.CKGM>100000 THEN 'C'||FLOOR(T.CKGM/100000)
            WHEN T.CKGM>10000 THEN 'D'||FLOOR(T.CKGM/10000)
            ELSE 'E' END AS SBMYLAJ_DJ,
       CASE WHEN T.SB_TMSE>100000000 THEN 'S'||TRUNC(T.SB_TMSE/100000000,1)
            WHEN T.SB_TMSE>10000000 THEN 'A'||FLOOR(T.SB_TMSE/10000000)
            WHEN T.SB_TMSE>1000000 THEN 'B'||FLOOR(T.SB_TMSE/1000000)
            WHEN T.SB_TMSE>100000 THEN 'C'||FLOOR(T.SB_TMSE/100000)
            WHEN T.SB_TMSE>10000 THEN 'D'||FLOOR(T.SB_TMSE/10000)
            ELSE 'E' END AS TMSE_DJ
  FROM GLXT_BB_SHXT_DJXX T
 INNER JOIN TL_ADMIN.DM_SWJG S ON S.SWJG_DM=T.SWJGDM
 WHERE T.ZX_FLAG='N'
 ORDER BY T.SWJGDM,T.CKGM DESC;

prompt
prompt Creating view V_JCFX_DATA_TSSBMX
prompt ================================
prompt
create or replace force view v_jcfx_data_tssbmx as
select nvl(a.shxyno,a.nsrdjno) as nsrsbh,a.nsrmc,a.qyhgdm,a.swjgdm,a.flglcd,a.qylx,a.jsmode,a.zx_flag,a.nsrzt_js,a.hydm,a.djzclx_js,
    b.ny,b.glh,b.ckbgdh,substr(b.CKBGDH,1,18) as bgdh18,b.ckrq,b.cksl,b.cksp_dm,b.mylaj,b.rmblaj,b.jsje,
    ROUND(b.jsje/decode(b.cksl,0,1,b.CKSL),2) as JSDJ,
    b.tsl,b.tmse,
    b.sbywlx,b.hggqka_dm,b.hydxzqh_dm,b.hzdwdq_dm,b.jgfs_dm,b.mygdqsz_dm,
    b.sbrq,b.ghfnsrsbh
    from glxt_bb_shxt_djxx a,jcfx_data_tssbmx b
    where a.cpcode=b.djxh;

prompt
prompt Creating view V_JKGL_GY_FXSM_HGCK
prompt =================================
prompt
create or replace force view v_jkgl_gy_fxsm_hgck as
select dj.swjgdm,dj.nsrmc,dj.swjgdm as TSSWJG_DM_1,
 to_char(a.SMRQ,'yyyymm') as FXNY,a.fxgz,a.smrq,a.tgbz,
 b."UUID",b."DJXH",b."CKNY",b."YHGGQKA_DM",b."HGGQKA_DM",b."CKBGDH",b."BSM",b."HZDWDQ_DM",b."HXDH",b."CKRQ_1",b."YCKSP_DM",b."CKSP_DM",b."CKSPMC",b."HGJLDWMC",b."MYGDQSZ_DM",b."YJGFS_DM",b."JGFS_DM",b."YDYJLDW_DM",b."DYJLDW_DM",b."YDEJLDW_DM",b."DEJLDW_DM",b."CKSL",b."DECKSL",b."RMBLAJ",b."MYLAJ",b."CJHGHBSZ_DM",b."CJZJ",b."JYDWMC",b."YSFS_DM",b."TYDH",b."ZMXZ_DM",b."JHFS_DM",b."XKZH",b."ZYG_DM",b."HGCJFS_DM",b."YFJSFS_DM",b."YFHGHBSZ_DM",b."YFHL",b."BFJSFS_DM",b."BFHGHBSZ_DM",b."BFHL",b."ZFJSFS_DM",b."ZFHGHBSZ_DM",b."ZFHL",b."BAH",b."SBDWDM",b."SBDWMC",b."HZDWMC",b."GGXH",b."ZZMDGDQSZ_DM",b."SBJLDW_DM",b."SBSL_1",b."SBDJ",b."TSL",b."CYTSSBJL",b."YSGJMC",b."BYTSBZ",b."HCH",b."HZDWDM",b."HGBZZL_DM",b."JS_1",b."MZ_2",b."JZ",b."LXBZ",b."TSSBSL",b."TSSBRMBLAJ",b."TSSBMYLAJ",b."TYSL",b."TYRMBLAJ",b."TYMYLAJ",b."DLSBSL",b."DLSBRMBLAJ",b."DLSBMYLAJ",b."HGSPMC",b."GFHHGSPMC",b."HGQY_DM",b."SJGXSJ",b."RKRQ",b."SJZXTYBH",b."QYGBZ",b."KJDLCKHWZMBZ",b."KJCKHWTYYBSWTSZMBZ",b."LRR_DM",b."LRRQ",b."XGR_DM",b."XGRQ",b."SJGSDQ",b."SJTB_SJ",b."HGCKHWBGDSBRQ",b."QYGZCJGBZ",b."QYGWDDBZ",b."QYGCXCKBZ",b."QYRQ_2",b."CKHTH",b."GDBZ_1"
,ROUND(b.MYLAJ/decode(b.cksl,0,1,b.CKSL),2) as MYDJ
    from GLXT_BB_SHXT_DJXX dj,JKGL_GY_FXSM_HGCK a,CKTS_WBSJ_HG_BGD b
    where dj.cpcode=a.djxh and a.djxh=b.djxh and a.ckbgdh=b.ckbgdh;

