prompt
CREATE OR REPLACE FORCE VIEW V_YSB_WBA AS
SELECT T.SWJGDM, NVL(T.SHXYNO,T.NSRDJNO) AS NSRSBH, T.NSRMC
  FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
 WHERE NVL(T.ZX_FLAG,'N')='N'
   AND EXISTS (
       SELECT 1
         FROM TL_TSSH.GLXT_BB_SHXT_LCXX S
        WHERE S.DJXH=T.DJXH_JS
          AND S.SB_DATE>=DATE'2025-01-01'
          AND S.SB_TS_AMT+S.SB_MD_AMT>0)
   AND NOT EXISTS (
       SELECT 1
         FROM TL_ADMIN.EDOC_APPLY R
        WHERE (R.NSRSBH=T.NSRDJNO OR R.NSRSBH=T.SHXYNO)
          AND R.RESULT='2');

