prompt Creating function F_JKGL_JKM_PD
prompt ===============================
prompt
create or replace function F_JKGL_JKM_PD(p_djxh varchar2, p_yxq date) return integer is
/*
 * 单户企业健康码结果计算（仅评定，不更新）
 */
  v_swjg   varchar2(11);
  v_tsjsfs char(1);
  
  --定义变量
  --指标分转健康码分的折算比例
  zsblv1 number(18,2);
  zsblv2 number(18,2);
  zsblv3 number(18,2);
  zsblv4 number(18,2);
  zsblv5 number(18,2);
  zsblv6 number(18,2);

  --六个分类的红线
  lineRed1 int;
  lineRed2 int;
  lineRed3 int;
  lineRed4 int;
  lineRed5 int;
  lineRed6 int;
  --六个分类的黄线
  lineYellow1 int;
  lineYellow2 int;
  lineYellow3 int;
  lineYellow4 int;
  lineYellow5 int;
  lineYellow6 int;

  lineRed_Zh integer;          --综合红线
  lineYellow_Zh integer;       --综合黄线

  --实际指标赋分
  zb_SCORE1 int;
  zb_SCORE2 int;
  zb_SCORE3 int;
  zb_SCORE4 int;
  zb_SCORE5 int;
  zb_SCORE6 int;

  --折算后的分数
  jk_SCORE1 int;
  jk_SCORE2 int;
  jk_SCORE3 int;
  jk_SCORE4 int;
  jk_SCORE5 int;
  jk_SCORE6 int;
  jk_SCORE_ZH integer;          ---折算后健康码综合赋分

  --健康码结果  1绿  2黄 3红
  V_level char(1);
begin
  V_level:='0';

  BEGIN

    select swjgdm,decode(jsmode,'1','1','2') into v_swjg,v_tsjsfs from glxt_bb_shxt_djxx d where d.cpcode=p_djxh;
    --从健康码配置表，计算折算比率
    /*
    select
      sum(decode (ywfl_dm,'10',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'20',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'30',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'40',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'50',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'60',case when ZB_TOTAL=0 then 0 else JKM_TOTAL/ZB_TOTAL end,0)),
      sum(decode (ywfl_dm,'10',line_red,0)),
      sum(decode (ywfl_dm,'20',line_red,0)),
      sum(decode (ywfl_dm,'30',line_red,0)),
      sum(decode (ywfl_dm,'40',line_red,0)),
      sum(decode (ywfl_dm,'50',line_red,0)),
      sum(decode (ywfl_dm,'60',line_red,0)),
      sum(decode (ywfl_dm,'ZH',line_red,0)),
      sum(decode (ywfl_dm,'10',line_yellow,0)),
      sum(decode (ywfl_dm,'20',line_yellow,0)),
      sum(decode (ywfl_dm,'30',line_yellow,0)),
      sum(decode (ywfl_dm,'40',line_yellow,0)),
      sum(decode (ywfl_dm,'50',line_yellow,0)),
      sum(decode (ywfl_dm,'60',line_yellow,0)),
      sum(decode (ywfl_dm,'ZH',line_yellow,0))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from tl_tssh.jkgl_pz_jkm t
    where t.tsjsfs=v_tsjsfs ;
    */
    with TT as (
    select zb.ywfl_dm, sum(score) as zbScore
    from
      tl_tssh.jkgl_pz_zb zb left join 
      (
      select t.zb_id,max(nvl(s.score,t.score)) as score
      from 
      tl_tssh.jkgl_pz_zb_ycff t
      left join tl_tssh.jkgl_pz_zb_ycff_swjg s 
           on s.swjg_dm =v_swjg  
           and s.zb_id=t.zb_id and s.xh=t.xh and s.yxbz='Y' 
      where t.yxbz='Y'
      group by t.zb_id
      ) pt on pt.zb_id=zb.zb_id
    where 
      zb.yxbz='Y' and 
      zb.apply_qy=v_tsjsfs
      group by zb.ywfl_dm 
    )
    select
     sum(decode (jkm.ywfl_dm,'10',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'20',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'30',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'40',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'50',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'60',case when nvl(TT.zbScore,0)=0 then 0 else JKM_TOTAL/nvl(TT.zbScore,0) end,0)),
      sum(decode (jkm.ywfl_dm,'10',line_red,0)),
      sum(decode (jkm.ywfl_dm,'20',line_red,0)),
      sum(decode (jkm.ywfl_dm,'30',line_red,0)),
      sum(decode (jkm.ywfl_dm,'40',line_red,0)),
      sum(decode (jkm.ywfl_dm,'50',line_red,0)),
      sum(decode (jkm.ywfl_dm,'60',line_red,0)),
      sum(decode (jkm.ywfl_dm,'ZH',line_red,0)),
      sum(decode (jkm.ywfl_dm,'10',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'20',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'30',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'40',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'50',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'60',line_yellow,0)),
      sum(decode (jkm.ywfl_dm,'ZH',line_yellow,0))
    into zsblv1,zsblv2,zsblv3,zsblv4,zsblv5,zsblv6,
         lineRed1,lineRed2,lineRed3,lineRed4,lineRed5,lineRed6,lineRed_Zh,
         lineYellow1,lineYellow2,lineYellow3,lineYellow4,lineYellow5,lineYellow6,lineYellow_Zh
    from tl_tssh.jkgl_pz_jkm jkm
    left join TT on TT.ywfl_dm=jkm.ywfl_dm
    where jkm.tsjsfs=v_tsjsfs ;
    
    
    
    -- 获取该纳税人的指标赋分
    select
        nvl(sum(decode (ywfl_dm,'10',score,0)),0),
        nvl(sum(decode (ywfl_dm,'20',score,0)),0),
        nvl(sum(decode (ywfl_dm,'30',score,0)),0),
        nvl(sum(decode (ywfl_dm,'40',score,0)),0),
        nvl(sum(decode (ywfl_dm,'50',score,0)),0),
        nvl(sum(decode (ywfl_dm,'60',score,0)),0)
    into zb_SCORE1,zb_SCORE2,zb_SCORE3,zb_SCORE4,zb_SCORE5,zb_SCORE6
    from (
    select s.ywfl_dm, 
      --   sum(t.score) as score
        sum(case when (p_yxq is null OR p_yxq>=trunc(sysdate)) and nvl(t.hcjg,'2')='1' then 0 else t.score end) as score
        from
 --       tl_tssh.jkgl_data_qyjkm_jgb k 
 --       inner join tl_tssh.jkgl_data_zb_jgb t on t.djxh=k.djxh
        tl_tssh.jkgl_data_zb_jgb t
        inner join tl_tssh.jkgl_pz_zb s on t.zb_id=s.zb_id and s.yxbz='Y'
        where t.djxh=p_djxh
        group by s.ywfl_dm
    );

    --计算健康码折算赋分
    jk_SCORE1 := zb_SCORE1 * zsblv1;
    jk_SCORE2 := zb_SCORE2 * zsblv2;
    jk_SCORE3 := zb_SCORE3 * zsblv3;
    jk_SCORE4 := zb_SCORE4 * zsblv4;
    jk_SCORE5 := zb_SCORE5 * zsblv5;
    jk_SCORE6 := zb_SCORE6 * zsblv6;
    jk_SCORE_ZH := jk_SCORE1+jk_SCORE2+jk_SCORE3+jk_SCORE4+jk_SCORE5+jk_SCORE6;
   
    if (lineRed_Zh<>0 and jk_SCORE_ZH >= lineRed_Zh)
      OR (lineRed1<>0 and jk_SCORE1 >= lineRed1)
      OR (lineRed2<>0 and jk_SCORE2 >= lineRed2)
      OR (lineRed3<>0 and jk_SCORE3 >= lineRed3)
      OR (lineRed4<>0 and jk_SCORE4 >= lineRed4)
      OR (lineRed5<>0 and jk_SCORE5 >= lineRed5)
      OR (lineRed6<>0 and jk_SCORE6 >= lineRed6)
    then
      V_level := '3';
    else
      if (lineYellow_Zh<>0 and jk_SCORE_ZH >= lineYellow_Zh)
        OR (lineYellow1<>0 and jk_SCORE1 >= lineYellow1)
        OR (lineYellow2<>0 and jk_SCORE2 >= lineYellow2)
        OR (lineYellow3<>0 and jk_SCORE3 >= lineYellow3)
        OR (lineYellow4<>0 and jk_SCORE4 >= lineYellow4)
        OR (lineYellow5<>0 and jk_SCORE5 >= lineYellow5)
        OR (lineYellow6<>0 and jk_SCORE6 >= lineYellow6)
      then
        V_level := '2';
      else
        V_level:='1';
      end if;
    end if;

  EXCEPTION
    WHEN OTHERS THEN
      dbms_output.put_line('【健康码】等级评定：'||sqlerrm);
      ROLLBACK;
      RAISE_APPLICATION_ERROR(-20001,'【健康码】等级评定：'||P_djxh);
  END;
  
  return (V_level);
end F_JKGL_JKM_PD;
/

prompt
prompt Creating function F_MY_STDAVG_TMPTB
prompt ===================================
prompt
create or replace function F_MY_STDAVG_TMPTB(p_datasql varchar2) return number is
--计算一组数据的标准值
--区别于算数平均值，是一组数中剔除和标准差偏离较大的坏点后，再取平均值
-- 输入数据组的脚本示例如下，对象必须别名为obj
-- 示例：select zb_total as obj from jkgl_pz_jkm
-- 示例：select to_number(zb_val) as obj from tl_tssh.jkgl_data_zb_jgb where zb_val is not null and zb_val<>0
-- select zb_val as obj from jkgl_data_tj_zb t where zb_id='W50202' and t.bgqid in (select bgqid from jkgl_data_bgq b,glxt_bb_shxt_djxx d where b.djxh=d.djxh_js and d.jsmode='2' and b.bgq_q=date'2019-01-01')
  v_tmpSql varchar2(2000);
  v_stddev number(18,2);
  v_avg number(18,2);
  v_deeps integer;--嵌套计算深度
  v_id integer;
  v_tablecnt integer;
begin
  --创建临时表
  v_tmpSql:='select count(1) from user_tables where table_name=''TMP_STDDEV''';
  EXECUTE IMMEDIATE v_tmpSql into v_tablecnt;
  if v_tablecnt>0 then
    v_tmpSql:='drop table TMP_STDDEV';
    EXECUTE IMMEDIATE v_tmpSql;
  end if;

  v_tmpSql:='CREATE GLOBAL TEMPORARY TABLE TMP_STDDEV (id INTEGER,val NUMBER(18,2),ybbz CHAR(1)) ON COMMIT DELETE ROWS';
  EXECUTE IMMEDIATE v_tmpSql;

--  v_tmpSql:='select nvl(max(id),0) from tmp_stddev';
--  EXECUTE IMMEDIATE v_tmpSql into v_id ;
--  v_id := v_id + 1;
  v_id:=1;
  v_deeps:=0;


  --首先，将数组写入临时表
  v_tmpSql := 'insert into tmp_stddev(id,val,ybbz) '
           || ' select ' || v_id || ',obj,''1'' from (' || p_datasql || ')' ;
  EXECUTE IMMEDIATE v_tmpSql;

  IF SQL%ROWCOUNT = 0 THEN
    v_avg:=null;
  ELSE
    LOOP Exit When(v_deeps>3);
      v_deeps:=v_deeps+1;
      --计算标准差
      v_tmpSql :='select stddev(val) from tmp_stddev where id=' || v_id || ' and ybbz=''1''';
      EXECUTE IMMEDIATE v_tmpSql into v_stddev;
      --计算平均值
      v_tmpSql :='select avg(val) from tmp_stddev where id=' || v_id || ' and ybbz=''1''';
      EXECUTE IMMEDIATE v_tmpSql into v_avg ;

      if nvl(v_stddev,0) = 0 OR nvl(v_avg,0)=0 then
        Exit;
      end if;

      --和平均值的偏差 和标准差相比，偏差在一倍以上的剔除掉。
      v_tmpSql :='update tmp_stddev t set ybbz=''0'' where id=' || v_id || ' and '
                 || ' abs(t.val - ' || v_avg ||')/' || v_stddev ||' > 2 and ybbz=''1''' ;
      EXECUTE IMMEDIATE v_tmpSql;
      if (sql%rowcount = 0) then
        Exit;
      end if;
    END LOOP;

    v_tmpSql :='select avg(val) from tmp_stddev where id=' || v_id || ' and ybbz=''1''';
    EXECUTE IMMEDIATE v_tmpSql into v_avg ;
  END IF;
  
--  delete from tmp_stddev where id=v_id;
  v_tmpSql:='DROP TABLE TMP_STDDEV';
  EXECUTE IMMEDIATE v_tmpSql;

  return(v_avg);
end F_MY_STDAVG_TMPTB;
/

prompt
prompt Creating function F_WLGL_EXTRACT_DATE
prompt =====================================
prompt
CREATE OR REPLACE FUNCTION f_wlgl_extract_date
-- ============================================
-- 函数：提取并标准化起运日
-- ============================================
(
  p_text IN VARCHAR2,
  p_date IN DATE
)
RETURN DATE
IS
  v_date_ck     VARCHAR2(100);
  v_text_nock   VARCHAR2(2000);
  v_pattern     VARCHAR2(200);
  v_date_str    VARCHAR2(30);
  v_result      DATE;
BEGIN
  IF p_text IS NULL THEN
    RETURN NULL;
  END IF;

  -- 为防止出口日期干扰，将出口日期相关信息先置换掉
  v_pattern := '(出口日期)[:：[:space:]]*(\d{8}|\d{4}[-/\.,]\d{1,2}[-/\.,]\d{1,2}|\d{4}年\d{1,2}月\d{1,2}日)';
  v_date_ck := REGEXP_SUBSTR(p_text, v_pattern, 1, 1, 'i');
  v_text_nock := REGEXP_REPLACE(p_text, v_date_ck, '');

  -- 1、有日期格式(Mon-dd-yyyy OR YYYY-Mon-DD)
  v_pattern := '((Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Mon|Nov|Dec)[-/\.,]\d{1,2}[-/\.,]\d{4}|'
            || '\d{4}[-/\.,](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Mon|Nov|Dec)[-/\.,]\d{1,2})';
  v_date_str := UPPER(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'));
  IF v_date_str IS NULL THEN
    -- 2、有日期格式(Y.M.D OR Y年M月D日(号) OR M月D日(号))
    v_pattern := '(\d{2,4}[-/\.]\d{1,2}[-/\.]\d{1,2}|\d{2,4}年\d{1,2}月\d{1,2}(日|号)|\d{1,2}月\d{1,2}(日|号))';
    v_date_str := REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'号','日');
  END IF;
  IF v_date_str IS NULL THEN
    -- 3、纯8位数字YYYYMMDD，为了准确分割，要求提取的8位数据前后均为非数字，然后将前后的非数字替换掉
    v_pattern := '[^0-9]\d{8}([^0-9]|$)';
    v_date_str := REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9]+','');
  END IF;
  IF v_date_str IS NULL THEN
    -- 4、带前缀日期标识的6位YYMMDD、4位MMDD，为了准确分割，要求提取的数据后面为非数字
    v_pattern := '(起运|启运|出运|起始|起送|始运|发车|发货|装货|送货|拉货|装运|装柜|装箱)(日|日期|时间)[:：[:space:]]*(\d{6}|\d{4})([^0-9]|$)';
    v_date_str := REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9]+','');
  END IF;
  IF v_date_str IS NULL THEN
    -- 5、带前缀日期标识的 MM.DD，为了准确分割，要求提取的数据后面为非数字
    v_pattern := '(起运|启运|出运|起始|起送|始运|发车|发货|装货|送货|拉货|装运|装柜|装箱)(日|日期|时间)[:：[:space:]]*\d{1,2}[-/\.]\d{1,2}([^0-9]|$)';
    v_date_str := REGEXP_REPLACE(REGEXP_SUBSTR(v_text_nock, v_pattern, 1, 1, 'i'),'[^0-9/\.-]+','');
  END IF;

  -- 统一标准化为 YYYY-MM-DD
  -- 情况1.1: APR.13.2026
  IF REGEXP_LIKE(v_date_str, '^(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|MON|NOV|DEC)[-/\.,]\d{1,2}[-/\.,]\d{4}$') THEN
    SELECT TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\.,]', '-'), 'MON-DD-YYYY')
      INTO v_result
      FROM DUAL;
  -- 情况1.2: 2026.APR.13
  ELSIF REGEXP_LIKE(v_date_str, '^\d{4}[-/\.,](JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|MON|NOV|DEC)[-/\.,]\d{1,2}$') THEN
    SELECT TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\.]', '-'), 'YYYY-MON-DD')
      INTO v_result
      FROM DUAL;
  -- 情况2.1: 2023-01-15 / 2023/01/15 / 2023.01.15
  ELSIF REGEXP_LIKE(v_date_str, '^\d{4}[-/\.]\d{1,2}[-/\.]\d{1,2}$') THEN
    SELECT TO_DATE(REGEXP_REPLACE(v_date_str, '[-/\.]', '-'), 'YYYY-MM-DD')
      INTO v_result
      FROM DUAL;
  -- 情况2.2: 23-01-15 / 23/01/15 / 23.01.15
  ELSIF REGEXP_LIKE(v_date_str, '^\d{2}[-/\.]\d{1,2}[-/\.]\d{1,2}$') THEN
    SELECT TO_DATE(REGEXP_REPLACE('20'||v_date_str, '[-/\.]', '-'), 'YYYY-MM-DD')
      INTO v_result
      FROM DUAL;
  -- 情况2.3: 2023年1月15日
  ELSIF REGEXP_LIKE(v_date_str, '^\d{4}年\d{1,2}月\d{1,2}日$') THEN
    SELECT TO_DATE(v_date_str, 'YYYY"年"MM"月"DD"日"')
      INTO v_result
      FROM DUAL;
  -- 情况2.4: 23年1月15日
  ELSIF REGEXP_LIKE(v_date_str, '^\d{2}年\d{1,2}月\d{1,2}日$') THEN
    SELECT TO_DATE('20'||v_date_str, 'YYYY"年"MM"月"DD"日"')
      INTO v_result
      FROM DUAL;
  -- 情况2.5: 1月15日
  ELSIF REGEXP_LIKE(v_date_str, '^\d{1,2}月\d{1,2}日$') THEN
    SELECT TO_DATE(TO_CHAR(p_date,'YYYY')||'年'||v_date_str, 'YYYY"年"MM"月"DD"日"')
      INTO v_result
      FROM DUAL;
  -- 情况3: 纯8位数字 20230115
  ELSIF REGEXP_LIKE(v_date_str, '^\d{8}$') THEN
    SELECT TO_DATE(v_date_str, 'YYYYMMDD')
      INTO v_result
      FROM DUAL;
  -- 情况4.1: 纯6位数字 230115
  ELSIF REGEXP_LIKE(v_date_str, '^\d{6}$') THEN
    SELECT TO_DATE('20'||v_date_str, 'YYYYMMDD')
      INTO v_result
      FROM DUAL;
  -- 情况4.2: 纯4位数字 0115
  ELSIF REGEXP_LIKE(v_date_str, '^\d{4}$') THEN
    SELECT TO_DATE(TO_CHAR(p_date,'YYYY')||v_date_str, 'YYYYMMDD')
      INTO v_result
      FROM DUAL;
  -- 情况5: 01-15 / 01/15 / 01.15
  ELSIF REGEXP_LIKE(v_date_str, '^\d{1,2}[-/\.]\d{1,2}$') THEN
    SELECT TO_DATE(TO_CHAR(p_date,'YYYY')||'-'||REGEXP_REPLACE(v_date_str, '[-/\.]', '-'), 'YYYY-MM-DD')
      INTO v_result
      FROM DUAL;
  END IF;
  
  RETURN v_result;

EXCEPTION WHEN OTHERS THEN
  RETURN NULL; -- 日期解析失败返回空
END f_wlgl_extract_date;
/

