prompt Creating procedure PRO_DEAL_JCFX_DATA_TSSBMX
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_DATA_TSSBMX
AS
  V_BEGINDATE      DATE;
  V_RMBLAJ         NUMBER(18,2);
  V_GHFNSRSBH      VARCHAR2(30);
  V_HYDXZQH_DM     VARCHAR2(10);
  LN_ROWS          NUMBER(10);
  LC_SBYY          VARCHAR2(2000);
BEGIN
  EXECUTE IMMEDIATE 'ALTER TABLE JCFX_DATA_TSSBMX ENABLE ROW MOVEMENT';
  
  SELECT TRUNC(MAX(T.SJGXSJ))-1
    INTO V_BEGINDATE
    FROM JCFX_DATA_TSSBMX T;

  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_MDT_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND NVL(S.BYBLBZ,'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MDT_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：' || LN_ROWS);
  COMMIT;
  
  --免抵退税
  BEGIN
    MERGE INTO JCFX_DATA_TSSBMX A
         USING (SELECT S.UUID,S.TSSWJG_DM,S.DJXH,NVL(TRIM(S.DLCKHWZMHM),S.CKBGDH) AS CKBGDH,TO_CHAR(S.SBRQ,'YYYYMM') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'1' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.RMBLAJ,S.TSL,S.MDTSE
                  FROM CKTS_SB_MDT_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND NVL(S.BYBLBZ,'N')='N'
                   AND NVL(TRIM(S.DLCKHWZMHM),S.CKBGDH) IS NOT NULL) B
            ON (A.UUID=B.UUID)
          WHEN MATCHED THEN
            UPDATE SET A.TSSWJG_DM=B.TSSWJG_DM, A.DJXH=B.DJXH, A.CKBGDH=B.CKBGDH, A.NY=B.NY, A.SBRQ=B.SBRQ, A.CKRQ=B.CKRQ_1, A.CKSP_DM=B.CKSP_DM, 
                       A.HGGQKA_DM=B.HGCODE, A.MYGDQSZ_DM=B.GBCODE, A.JGFS_DM=B.TDCODE, A.HZDWDQ_DM=B.HZDWDQDM, A.SJGXSJ=SYSDATE, A.SBYWLX=B.SBYWLX, A.LCSLID=B.LCSLID_SB, 
                       A.MYLAJ=B.MYLAJ, A.RMBLAJ=B.RMBLAJ, A.JSJE=B.RMBLAJ, A.TSL=B.TSL, A.TMSE=B.MDTSE, A.CKSL=B.CKSL
          WHEN NOT MATCHED THEN
            INSERT (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,RMBLAJ,JSJE,TSL,TMSE,CKSL)
            VALUES (B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,SYSDATE,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.RMBLAJ,B.RMBLAJ,B.TSL,B.MDTSE,B.CKSL);
    COMMIT;
    --不需要补充GHFNSRSBH,HYDXZQH_DM 
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;
  END;
  
  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_MTS_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND NVL(S.BYBLBZ,'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MTS_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：' || LN_ROWS);
  COMMIT;
  
  --免退税
  BEGIN
    MERGE INTO JCFX_DATA_TSSBMX A
         USING (SELECT S.UUID,S.TSSWJG_DM,S.DJXH,NVL(TRIM(S.DLCKHWZMHM),S.CKBGDH) AS CKBGDH,TO_CHAR(S.SBRQ,'YYYYMM') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'2' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.GLH,S.JSJE,S.TSL,S.TSE
                  FROM CKTS_SB_MTS_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND NVL(S.BYBLBZ,'N')='N') B
            ON (A.UUID=B.UUID)
          WHEN MATCHED THEN
            UPDATE SET A.TSSWJG_DM=B.TSSWJG_DM, A.DJXH=B.DJXH, A.CKBGDH=B.CKBGDH, A.NY=B.NY, A.SBRQ=B.SBRQ, A.CKRQ=B.CKRQ_1, A.CKSP_DM=B.CKSP_DM, 
                       A.HGGQKA_DM=B.HGCODE, A.MYGDQSZ_DM=B.GBCODE, A.JGFS_DM=B.TDCODE, A.HZDWDQ_DM=B.HZDWDQDM, A.SJGXSJ=SYSDATE, A.SBYWLX=B.SBYWLX, A.LCSLID=B.LCSLID_SB, 
                       A.MYLAJ=B.MYLAJ, A.GLH=B.GLH, A.JSJE=B.JSJE, A.TSL=B.TSL, A.TMSE=B.TSE, A.CKSL=B.CKSL
          WHEN NOT MATCHED THEN
            INSERT (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,GLH,JSJE,TSL,TMSE,CKSL)
            VALUES (B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,SYSDATE,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.GLH,B.JSJE,B.TSL,B.TSE,B.CKSL);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;
  END;
    
  BEGIN
    --补充RMBLAJ,GHFNSRSBH,HYDXZQH_DM
    FOR CUR_TSSB IN (SELECT T.UUID,T.DJXH,T.CKBGDH,T.CKSP_DM,GLH,MYLAJ,TO_CHAR(T.CKRQ,'YYYYMM') AS CKNY FROM JCFX_DATA_TSSBMX T WHERE T.SJGXSJ>=TRUNC(SYSDATE,'DD') AND T.SBYWLX='2')
    LOOP
      BEGIN
        --防止部分申报
        SELECT CUR_TSSB.MYLAJ * S.RMBLAJ / S.MYLAJ 
          INTO V_RMBLAJ
          FROM CKTS_WBSJ_HG_BGD S
         WHERE S.DJXH=CUR_TSSB.DJXH AND S.CKBGDH=CUR_TSSB.CKBGDH;
      EXCEPTION
        WHEN OTHERS THEN
          V_RMBLAJ := NULL;
      END;
      
      IF V_RMBLAJ IS NULL THEN
        SELECT CUR_TSSB.MYLAJ * S.HL_RMB / 100
          INTO V_RMBLAJ
          FROM TL_BJTS.GS_HBZL_HLV S 
         WHERE S.CODE='USD' AND S.HL_YM=CUR_TSSB.CKNY AND ROWNUM=1;
      END IF;
      
      BEGIN
        --主要供货商
        SELECT GHFNSRSBH_1, CASE WHEN SUBSTR(GHFNSRSBH_1,1,2)='91' THEN SUBSTR(GHFNSRSBH_1,3,4) ELSE SUBSTR(GHFNSRSBH_1,1,4) END
          INTO V_GHFNSRSBH, V_HYDXZQH_DM
          FROM (SELECT S.GHFNSRSBH_1, SUM(S.TSE) AS TSE
                  FROM CKTS_SB_MTS_JHMX S
                 WHERE S.DJXH=CUR_TSSB.DJXH AND S.GLH=CUR_TSSB.GLH AND S.CKSP_DM=CUR_TSSB.CKSP_DM
                 GROUP BY S.GHFNSRSBH_1
                 ORDER BY SUM(S.TSE) DESC) TT
         WHERE ROWNUM=1;
      EXCEPTION
        WHEN OTHERS THEN
          V_GHFNSRSBH :=NULL;
          V_HYDXZQH_DM :=NULL;
      END;
      
      UPDATE JCFX_DATA_TSSBMX S
         SET S.RMBLAJ = V_RMBLAJ, GHFNSRSBH = V_GHFNSRSBH, HYDXZQH_DM = V_HYDXZQH_DM
       WHERE S.UUID=CUR_TSSB.UUID;
      COMMIT;
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('JCFX_DATA_TSSBMX补充RMBLAJ,GHFNSRSBH,HYDXZQH_DM失败！', LC_SBYY);
      COMMIT;
  END;
  
  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_SB_WZF_CKMX S
   WHERE S.SJTB_SJ>=V_BEGINDATE
     AND NVL(S.BYBLBZ,'N')='N';

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_WZF_CKMX-->JCFX_DATA_TSSBMX开始运行，记录总数：' || LN_ROWS);
  COMMIT;
  
  --代办退税
  BEGIN
    MERGE INTO JCFX_DATA_TSSBMX A
         USING (SELECT S.UUID,S.TSSWJG_DM,S.DJXH,S.CKBGDH,TO_CHAR(S.SBRQ,'YYYYMM') AS NY,S.SBRQ,S.CKRQ_1,S.CKSP_DM,
                       S.HGCODE,S.GBCODE,S.TDCODE,S.HZDWDQDM,'3' AS SBYWLX,S.LCSLID_SB,
                       S.CKSL,S.MYLAJ,S.JSJE,S.TSL,S.TSE,S.WTDBTSSCQYNSRSBH,
                       CASE WHEN SUBSTR(S.WTDBTSSCQYNSRSBH,1,2)='91' THEN SUBSTR(S.WTDBTSSCQYNSRSBH,3,4) ELSE SUBSTR(S.WTDBTSSCQYNSRSBH,1,4) END AS HYDXZQH_DM
                  FROM CKTS_SB_WZF_CKMX S
                 WHERE S.SJTB_SJ>=V_BEGINDATE
                   AND NVL(S.BYBLBZ,'N')='N') B
            ON (A.UUID=B.UUID)
          WHEN MATCHED THEN
            UPDATE SET A.TSSWJG_DM=B.TSSWJG_DM, A.DJXH=B.DJXH, A.CKBGDH=B.CKBGDH, A.NY=B.NY, A.SBRQ=B.SBRQ, A.CKRQ=B.CKRQ_1, A.CKSP_DM=B.CKSP_DM, 
                       A.HGGQKA_DM=B.HGCODE, A.MYGDQSZ_DM=B.GBCODE, A.JGFS_DM=B.TDCODE, A.HZDWDQ_DM=B.HZDWDQDM, A.SJGXSJ=SYSDATE, A.SBYWLX=B.SBYWLX, A.LCSLID=B.LCSLID_SB, 
                       A.MYLAJ=B.MYLAJ,A.JSJE=B.JSJE,A.TSL=B.TSL,A.TMSE=B.TSE,A.CKSL=B.CKSL,A.GHFNSRSBH=B.WTDBTSSCQYNSRSBH,A.HYDXZQH_DM=B.HYDXZQH_DM
          WHEN NOT MATCHED THEN
            INSERT (UUID,TSSWJG_DM,DJXH,CKBGDH,NY,SBRQ,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,SJGXSJ,SBYWLX,LCSLID,MYLAJ,JSJE,TSL,TMSE,CKSL,GHFNSRSBH,HYDXZQH_DM)
            VALUES (B.UUID,B.TSSWJG_DM,B.DJXH,B.CKBGDH,B.NY,B.SBRQ,B.CKRQ_1,B.CKSP_DM,B.HGCODE,B.GBCODE,B.TDCODE,B.HZDWDQDM,SYSDATE,B.SBYWLX,B.LCSLID_SB,B.MYLAJ,B.JSJE,B.TSL,B.TSE,B.CKSL,B.WTDBTSSCQYNSRSBH,B.HYDXZQH_DM);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_WZF_CKMX-->JCFX_DATA_TSSBMX失败！', LC_SBYY);
      COMMIT;
  END;
    
  BEGIN
    --补充RMBLAJ
    FOR CUR_TSSB IN (SELECT T.UUID,T.DJXH,T.CKBGDH,MYLAJ,T.NY FROM JCFX_DATA_TSSBMX T WHERE T.SJGXSJ>=TRUNC(SYSDATE,'DD') AND T.SBYWLX='3')
    LOOP
      BEGIN
        SELECT S.RMBLAJ * CUR_TSSB.MYLAJ / S.MYLAJ  --防止部分申报
          INTO V_RMBLAJ
          FROM CKTS_WBSJ_HG_BGD S
         WHERE S.DJXH=CUR_TSSB.DJXH AND S.CKBGDH=CUR_TSSB.CKBGDH;
      EXCEPTION
        WHEN OTHERS THEN
          V_RMBLAJ := NULL;
      END;
      
      IF V_RMBLAJ IS NULL THEN
        SELECT CUR_TSSB.MYLAJ * S.HL_RMB / 100
          INTO V_RMBLAJ
          FROM TL_BJTS.GS_HBZL_HLV S 
         WHERE S.CODE='USD' AND S.HL_YM=CUR_TSSB.NY AND ROWNUM=1;
      END IF;
      
      UPDATE JCFX_DATA_TSSBMX S
         SET S.RMBLAJ = V_RMBLAJ
       WHERE S.UUID=CUR_TSSB.UUID;
      COMMIT;
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('JCFX_DATA_TSSBMX补充RMBLAJ失败！', LC_SBYY);
      COMMIT;
  END;

  EXECUTE IMMEDIATE 'ALTER TABLE JCFX_DATA_TSSBMX DISABLE ROW MOVEMENT';
  
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('JCFX_DATA_TSSBMX 开始运行，清除作废流程和不予办理数据...');
  COMMIT;
  
  BEGIN
    --根据明细变更情况，删除不予办理数据
    FOR CUR_BYBL IN (SELECT T.UUID FROM CKTS_SB_MDT_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y')
    LOOP
      DELETE FROM JCFX_DATA_TSSBMX S WHERE S.UUID=CUR_BYBL.UUID;
    END LOOP;
    COMMIT;
    
    FOR CUR_BYBL IN (SELECT T.UUID FROM CKTS_SB_MTS_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y')
    LOOP
      DELETE FROM JCFX_DATA_TSSBMX S WHERE S.UUID=CUR_BYBL.UUID;
    END LOOP;
    COMMIT;
    
    FOR CUR_BYBL IN (SELECT T.UUID FROM CKTS_SB_WZF_CKMX T WHERE T.XGRQ>=V_BEGINDATE AND T.BYBLBZ='Y')
    LOOP
      DELETE FROM JCFX_DATA_TSSBMX S WHERE S.UUID=CUR_BYBL.UUID;
    END LOOP;
    COMMIT;
    
    --根据流程信息作废情况，删除作废数据
    FOR CUR_ZFLC IN (SELECT T.LCSLID_SB FROM CKTS_LC_SBXX T WHERE T.ZFRQ>=V_BEGINDATE)
    LOOP
      DELETE FROM JCFX_DATA_TSSBMX S WHERE S.LCSLID=CUR_ZFLC.LCSLID_SB;
    END LOOP;
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX T
     WHERE T.SJGXSJ>=ADD_MONTHS(TRUNC(SYSDATE),-1) AND T.SBYWLX='1'
       AND NOT EXISTS (SELECT 1 FROM TL_TSSH.CKTS_SB_MDT_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX T
     WHERE T.SJGXSJ>=ADD_MONTHS(TRUNC(SYSDATE),-1) AND T.SBYWLX='2'
       AND NOT EXISTS (SELECT 1 FROM TL_TSSH.CKTS_SB_MTS_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

    DELETE FROM JCFX_DATA_TSSBMX T
     WHERE T.SJGXSJ>=ADD_MONTHS(TRUNC(SYSDATE),-1) AND T.SBYWLX='3'
       AND NOT EXISTS (SELECT 1 FROM TL_TSSH.CKTS_SB_WZF_CKMX S WHERE S.UUID=T.UUID);
    COMMIT;

  END;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('JCFX_DATA_TSSBMX 处理结束！');
  COMMIT;
  
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_JCFX_NSR_BADJ
prompt =========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_NSR_BADJ
AS
  LD_DEALDATA      DATE;          --用于基础数据处理的提前量
BEGIN
  BEGIN
    MERGE INTO JCFX_NSR_BADJ A
         USING (SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,T.NSRMC,T.QYHGDM,T.QYLX,T.FLGLCD,T.DJZCLX_JS,T.HYDM,T.NSRZT_JS,T.NSRLX_JS,T.SQ_DATE,NVL(T.ZX_FLAG,'N') AS ZX_FLAG,T.ZX_DATE,T.SWJGDM,T.ZGSWSKFJ_DM,T.JDXZ_DM
                  FROM GLXT_BB_SHXT_DJXX T) B
            ON (A.DJXH=B.DJXH_JS)
          WHEN MATCHED THEN
            UPDATE SET A.NSRSBH=B.NSRDJNO, A.SHXYDM=B.SHXYNO, A.NSRMC=B.NSRMC, A.QYHGDM=B.QYHGDM, 
                       A.CKQYLX=B.QYLX, A.FLGLCD=B.FLGLCD, A.DJZCLX=B.DJZCLX_JS, A.HY=B.HYDM, A.NSRZT=B.NSRZT_JS, A.NSRLB=B.NSRLX_JS, 
                       A.SQ_DATE=B.SQ_DATE, A.BACHBZ=B.ZX_FLAG, A.BACHSJ=B.ZX_DATE, A.SWJGDM=B.SWJGDM, A.KSSWJG_DM=B.ZGSWSKFJ_DM, A.JDXZ_DM=B.JDXZ_DM
          WHEN NOT MATCHED THEN
            INSERT (DJXH,NSRSBH,SHXYDM,NSRMC,QYHGDM,CKQYLX,FLGLCD,DJZCLX,HY,NSRZT,NSRLB,SQ_DATE,BACHBZ,BACHSJ,SWJGDM,KSSWJG_DM,JDXZ_DM)
            VALUES (B.DJXH_JS,B.NSRDJNO,B.SHXYNO,B.NSRMC,B.QYHGDM,B.QYLX,B.FLGLCD,B.DJZCLX_JS,B.HYDM,B.NSRZT_JS,B.NSRLX_JS,B.SQ_DATE,B.ZX_FLAG,B.ZX_DATE,B.SWJGDM,B.ZGSWSKFJ_DM,B.JDXZ_DM);
    COMMIT;
    
    --QYFZ,NSRDZDAH
  END;
  
  SELECT MAX(JLXZSJ)-7 INTO LD_DEALDATA FROM JCFX_NSR_BADJ_TOHZ;
  
  BEGIN
    --后续增量数据1：新备案出口企业
    INSERT INTO JCFX_NSR_BADJ_TOHZ(DJXH,NSRSBH,SHXYDM,JLXZSJ,BACHSJ,SWJGDM)
         SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,TRUNC(LEAST(SYSDATE,T.SQ_DATE)),T.ZX_DATE,T.SWJGDM
           FROM GLXT_BB_SHXT_DJXX T
          WHERE T.SQ_DATE>=LD_DEALDATA
            AND NOT EXISTS (SELECT 1 FROM JCFX_NSR_BADJ_TOHZ S WHERE S.DJXH=T.DJXH_JS);
    COMMIT;

    --后续增量数据2：老备案企业，2019年1月1日以来首次申报出口退免税
    INSERT INTO JCFX_NSR_BADJ_TOHZ(DJXH,NSRSBH,SHXYDM,JLXZSJ,BACHSJ,SWJGDM)
         SELECT T.DJXH_JS,T.NSRDJNO,T.SHXYNO,TRUNC(SYSDATE),T.ZX_DATE,T.SWJGDM
           FROM GLXT_BB_SHXT_DJXX T
          WHERE EXISTS (SELECT 1 FROM CKTS_LC_SBXX S WHERE S.DJXH=T.DJXH_JS AND S.SBRQ>=LD_DEALDATA)
            AND NOT EXISTS (SELECT 1 FROM JCFX_NSR_BADJ_TOHZ S WHERE S.DJXH=T.DJXH_JS);
    COMMIT;

  --后续注销企业
    UPDATE JCFX_NSR_BADJ_TOHZ T
       SET T.BACHSJ=(SELECT S.ZX_DATE FROM GLXT_BB_SHXT_DJXX S WHERE S.DJXH_JS=T.DJXH)
     WHERE EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX S WHERE S.DJXH_JS=T.DJXH AND S.ZX_DATE>=LD_DEALDATA);
    COMMIT;
  END;
  
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_JCFX_NSR_BLV
prompt ========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_NSR_BLV
AS
  LN_CKBGDFS       NUMBER(10);
  LN_CKMYLAJ       NUMBER(18,2);
  LN_SBMYLAJ       NUMBER(18,2);
  LN_SBTMSE         NUMBER(18,2);
  LN_SBMDE         NUMBER(18,2);
  LC_CKGM          VARCHAR(1);
  LN_MDBLV         NUMBER(10,6);
  LC_MDBLV         VARCHAR(1);
BEGIN
  FOR CUR_NSR IN (SELECT T.DJXH_JS FROM TL_TSSH.GLXT_BB_SHXT_DJXX T)
  LOOP
    SELECT COUNT(DISTINCT SUBSTR(S.CKBGDH,1,18)), NVL(SUM(S.MYLAJ),0)
      INTO LN_CKBGDFS, LN_CKMYLAJ
      FROM TL_TSSH.CKTS_WBSJ_HG_BGD S
     WHERE S.DJXH=CUR_NSR.DJXH_JS
       AND S.CKRQ_1>=ADD_MONTHS(TRUNC(SYSDATE, 'YY'),-12)
       AND S.CKRQ_1< TRUNC(SYSDATE, 'YY');
    
    SELECT NVL(SUM(S.USD_AMT),0), NVL(SUM(S.SB_TS_AMT),0)+ NVL(SUM(S.SB_MD_AMT),0), NVL(SUM(S.SB_MD_AMT),0)
      INTO LN_SBMYLAJ, LN_SBTMSE, LN_SBMDE
      FROM TL_TSSH.GLXT_BB_SHXT_LCXX S 
     WHERE S.DJXH=CUR_NSR.DJXH_JS 
       AND NVL(S.SL_DATE,S.SB_DATE)>=ADD_MONTHS(TRUNC(SYSDATE, 'YY'),-12)
       AND NVL(S.SL_DATE,S.SB_DATE)< TRUNC(SYSDATE, 'YY');
     
    LC_CKGM := CASE WHEN LN_SBMYLAJ>=100000000 THEN 'A' 
                    WHEN LN_SBMYLAJ>=50000000 THEN 'B' 
                    WHEN LN_SBMYLAJ>=10000000 THEN 'C' 
                    WHEN LN_SBMYLAJ>=1000000 THEN 'D' 
                    ELSE 'E' END;
    
    IF LN_SBMDE<=0 THEN
      LN_MDBLV := 0;
    ELSIF LN_SBTMSE<0 THEN
      LN_MDBLV := 100;
    ELSE
      LN_MDBLV := 100 * LN_SBMDE / LN_SBTMSE;
    END IF;
    LC_MDBLV := CASE WHEN LN_MDBLV>=40 THEN 'A' 
                     WHEN LN_MDBLV>=30 THEN 'B' 
                     WHEN LN_MDBLV>=20 THEN 'C' 
                     WHEN LN_MDBLV>=10 THEN 'D' 
                     ELSE 'E' END;
    
    UPDATE TL_TSSH.GLXT_BB_SHXT_DJXX A
       SET A.CK_BGDFS = LN_CKBGDFS,
           A.CK_MYLAJ = LN_CKMYLAJ,
           A.CKGM     = LN_SBMYLAJ,
           A.SB_TMSE  = LN_SBTMSE,
           A.SB_MDE   = LN_SBMDE,
           A.MDBLV    = LN_MDBLV,
           A.CKGM_DM  = LC_CKGM,
           A.MDBLV_DM = LC_MDBLV
     WHERE A.DJXH_JS=CUR_NSR.DJXH_JS;
    COMMIT;
  END LOOP;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_COMPUTE_C01001
prompt ==========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_COMPUTE_C01001
/*
 * 新办企业出口异常模型
 * 需要从金三同步CKTS_BA_BABGQK_JGB表中变更退税机关记录
 * 20250610，修改扫描时间间隔条件，原先为不存在6个月内的自动扫描结果，改为人工扫描全部执行，自动扫描不存在6个月以内的数据
 */
(
  P_SWJGDM  IN VARCHAR2, --可空，空默认全省，前台手工刷新需传入
  P_DJXH    IN VARCHAR2, --可空，空默认税务机关下所有有申报企业，前台当个企业刷新需传入
  P_SMLX    IN VARCHAR2 --可空，空默认自动扫描，前台人工扫描输入1
)
AS
  V_MONTHS_YJJG   NUMBER(18,2);    --预警参数：预警间隔周期
  V_MYLAJ_LX3M    NUMBER(18,2);    --预警参数：连续3个月内美元出口额
  V_MONTHS_ZDCK   NUMBER(18,2);    --预警参数：中断出口后复出口的企业中断期
  V_MONTHS_SCSB   NUMBER(18,2);    --预警参数：新办类企业首次申报以后有效期
  V_PARAMS        VARCHAR(4000);
  V_SWJGDM        VARCHAR(11);
  V_MYLAJ         NUMBER(18,2);    --统计结果：连续3个月内美元出口额
BEGIN
  -- 取本次风险扫描的参数
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO V_MONTHS_YJJG
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_YJJG';
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO V_MYLAJ_LX3M
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MYLAJ_LX3M';
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO V_MONTHS_ZDCK
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_ZDCK';
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO V_MONTHS_SCSB
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_SCSB';
  V_PARAMS:='[d]预警间隔周期='||V_MONTHS_YJJG||
            '|连续3个月内美元出口额阈值=' || V_MYLAJ_LX3M||
            '|中断后复出口间隔周期=' || V_MONTHS_ZDCK||
            '|首次申报后检查有效期=' || V_MONTHS_SCSB;
  
  --取本次风险扫描的税务机关范围
  IF NVL(P_SWJGDM,'13300000000')='13300000000' THEN
    V_SWJGDM:='133%';
  ELSIF SUBSTR(P_SWJGDM,6)='000000' THEN
    V_SWJGDM:=SUBSTR(P_SWJGDM,1,5)||'%';
  ELSE
    V_SWJGDM:=SUBSTR(P_SWJGDM,1,7)||'%';
  END IF;
  
  IF P_SMLX=1 THEN
    UPDATE FXGL_DATA_ZXZB T
       SET T.HSJGLX='1', T.HSRQ=SYSDATE, T.HSRY='SYSTEM', T.HSCLQK='税务人员调整预警参数，重新刷新本次风险指标。'
     WHERE T.ZBID='C01001'
       AND T.TSSWJG_DM LIKE V_SWJGDM
       AND (P_DJXH IS NULL OR T.DJXH=P_DJXH)
       AND TRUNC(T.SMRQ,'MM')=TRUNC(SYSDATE,'MM')
       AND T.HSJGLX='0';
    COMMIT;
  END IF;
  
  --首次申报不足V_MONTHS_SCSB个月的出口企业
  FOR CUR_CKQY IN (SELECT T.DJXH,TRUNC(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM --税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) --是否单个企业扫描
                      AND NVL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_SCSB) --检查24个月内的申报流程
                      AND NOT EXISTS (SELECT 1 --不存在更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND NVL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ)
                      AND (  (NVL(P_SMLX,'0')='1')
                          OR (NVL(P_SMLX,'0')='0'
                         AND NOT EXISTS (SELECT 1 --预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_YJJG)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH)
  LOOP
    --统计连续三个月美元出口额，不包含当月数据
    SELECT NVL(SUM(MYLAJ),0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=CUR_CKQY.DJXH
       AND CKRQ_1>=ADD_MONTHS(TRUNC(SYSDATE,'MM'),-3)
       AND CKRQ_1<TRUNC(SYSDATE,'MM')
       AND ZMTBZ='T';
    --如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_FXGL_DATA_ZXZB.NEXTVAL,TT.SWJGDM,TT.DJXH_JS,NVL(TT.SHXYNO,TT.NSRDJNO),TT.NSRMC,NVL(P_SMLX,'0'),SYSDATE,'C01001',
                  V_PARAMS,'[d]出口企业首次申报日期=' || TO_CHAR(CUR_CKQY.SCSBRQ,'YYYYMMDD')||'|最近三个月美元出口额=' ||V_MYLAJ
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=CUR_CKQY.DJXH;
      COMMIT;
    END IF;
  END LOOP;
  
  --中断后复出口不足V_MONTHS_SCSB个月的出口企业
  FOR CUR_CKQY IN (SELECT T.DJXH,TRUNC(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM --税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) --是否单个企业扫描
                      AND NVL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_SCSB) --检查24个月内的申报流程
                      AND NOT EXISTS (SELECT 1 --不存在中断周期后更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND NVL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ
                                         AND A.QDSJ >= ADD_MONTHS(T.QDSJ, (-1) * V_MONTHS_ZDCK))
                      AND EXISTS (SELECT 1 --存在中断周期前更早的申报流程
                                    FROM CKTS_LC_SBXX B
                                   WHERE B.DJXH = T.DJXH
                                     AND NVL(B.ZFBZ, 'N') = 'N'
                                     AND B.QDSJ < ADD_MONTHS(T.QDSJ, (-1) * V_MONTHS_ZDCK))
                      AND (  (NVL(P_SMLX,'0')='1')
                          OR (NVL(P_SMLX,'0')='0'
                         AND NOT EXISTS (SELECT 1 --预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_YJJG)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH)
  LOOP
    --统计连续三个月美元出口额，不包含当月数据
    SELECT NVL(SUM(MYLAJ),0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=CUR_CKQY.DJXH
       AND CKRQ_1>=ADD_MONTHS(TRUNC(SYSDATE,'MM'),-3)
       AND CKRQ_1<TRUNC(SYSDATE,'MM')
       AND ZMTBZ='T';
    --如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_FXGL_DATA_ZXZB.NEXTVAL,TT.SWJGDM,TT.DJXH_JS,NVL(TT.SHXYNO,TT.NSRDJNO),TT.NSRMC,NVL(P_SMLX,'0'),SYSDATE,'C01001',
                  V_PARAMS,'[d]中断后复出口申报日期=' || TO_CHAR(CUR_CKQY.SCSBRQ,'YYYYMMDD')||'|最近三个月美元出口额=' ||V_MYLAJ
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=CUR_CKQY.DJXH;
      COMMIT;
    END IF;
  END LOOP;
  
  --迁移后不足V_MONTHS_SCSB个月的外贸企业
  FOR CUR_CKQY IN (SELECT T.DJXH,TRUNC(MIN(T.QDSJ)) AS SCSBRQ
                     FROM CKTS_LC_SBXX T
                    INNER JOIN (SELECT DJXH,MAX(LRRQ) AS QYRQ --最近24个月内最后一次迁移
                                  FROM CKTS_BA_BABGQK_JGB
                                 WHERE BABGZD_DM='TSSWJG_DM_1'
                                   AND LRRQ>=ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_SCSB)
                                 GROUP BY DJXH) R ON R.DJXH=T.DJXH
                    WHERE T.TSSWJG_DM LIKE V_SWJGDM --税务机关范围扫描
                      AND (P_DJXH IS NULL OR T.DJXH=P_DJXH) --是否单个企业扫描
                      AND NVL(T.ZFBZ, 'N') = 'N'
                      AND T.QDSJ >= R.QYRQ --检查迁移以后的申报流程
                      AND T.SBYWB_DM='A0301001'
                      AND NOT EXISTS (SELECT 1 --不存在迁移以后更早的申报流程
                                        FROM CKTS_LC_SBXX A
                                       WHERE A.DJXH = T.DJXH
                                         AND NVL(A.ZFBZ, 'N') = 'N'
                                         AND A.QDSJ < T.QDSJ
                                         AND A.QDSJ >= R.QYRQ)
                      AND EXISTS (SELECT 1 --存在迁移以前更早的申报流程
                                    FROM CKTS_LC_SBXX B
                                   WHERE B.DJXH = T.DJXH
                                     AND NVL(B.ZFBZ, 'N') = 'N'
                                     AND B.QDSJ < R.QYRQ)
                      AND (  (NVL(P_SMLX,'0')='1')
                          OR (NVL(P_SMLX,'0')='0'
                         AND NOT EXISTS (SELECT 1 --预警间隔期不自动扫描同一企业信息
                                           FROM FXGL_DATA_ZXZB B
                                          WHERE B.DJXH=T.DJXH
                                            AND B.ZBID='C01001'
                                            AND B.HSRQ>ADD_MONTHS(SYSDATE, (-1) * V_MONTHS_YJJG)
                                            AND B.HSRY!='SYSTEM')))
                    GROUP BY T.DJXH)
  LOOP
    --统计连续三个月美元出口额，不包含当月数据
    SELECT NVL(SUM(MYLAJ),0)
      INTO V_MYLAJ
      FROM CKTS_WBSJ_HG_BGD
     WHERE DJXH=CUR_CKQY.DJXH
       AND CKRQ_1>=ADD_MONTHS(TRUNC(SYSDATE,'MM'),-3)
       AND CKRQ_1<TRUNC(SYSDATE,'MM')
       AND ZMTBZ='T';
    --如果连续3个月美元出口额大于参数值，添加风险数据
    IF V_MYLAJ>=V_MYLAJ_LX3M THEN
      INSERT INTO FXGL_DATA_ZXZB(ID,TSSWJG_DM,DJXH,NSRSBH,NSRMC,SMLX,SMRQ,ZBID,ZBCS,SMJG)
           SELECT SEQ_FXGL_DATA_ZXZB.NEXTVAL,TT.SWJGDM,TT.DJXH_JS,NVL(TT.SHXYNO,TT.NSRDJNO),TT.NSRMC,NVL(P_SMLX,'0'),SYSDATE,'C01001',
                  V_PARAMS,'[d]外贸迁移后首次申报日期=' || TO_CHAR(CUR_CKQY.SCSBRQ,'YYYYMMDD')||'|最近三个月美元出口额=' ||V_MYLAJ
             FROM GLXT_BB_SHXT_DJXX TT
            WHERE TT.DJXH_JS=CUR_CKQY.DJXH;
      COMMIT;
    END IF;
  END LOOP;
  
  RETURN;
END;
/

