prompt Creating procedure PRO_FXGL_FXSPCK_DZXX
prompt =======================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_FXSPCK_DZXX
/*
 * 风险商品出口电子信息提取
 * 20250331，根据省局李裕军局长意见，对市场采购业务不做风险商品出口短信提醒
 */
AS
  LD_BEGINDATE      DATE;
BEGIN
  SELECT MAX(T.SJTB_SJ)-3 INTO LD_BEGINDATE FROM CKTS_WBSJ_HG_BGD T;

  FOR CUR_FXGZ IN (SELECT GZ_MC,GZ_FXMS,GZ_FW_SWJG,GZ_SPDM,GZ_SPMC,GZ_GGXH,GZ_CKKA,GZ_CKGB,GZ_HYD,GZ_DJQ,GZ_DJZ,GZ_ZJQ,GZ_ZJZ,GZ_YXQZ,GZ_DXTXBZ
                     FROM FXGL_SZ_SPFXCK
                    WHERE GZ_FW_DATA IN ('1','3') --规则适用业务范围：1出口电子信息+3同时适用
                      AND QYBJ='Y' --规则启用标记：Y
                      AND NVL(GZ_YXQZ,DATE'2100-12-31')>SYSDATE --规则有效期止：NULL或大于当前日期
  ) LOOP
    BEGIN
      --规则中所有设置为空，无效规则挑过
      IF CUR_FXGZ.GZ_SPDM IS NULL AND CUR_FXGZ.GZ_SPMC IS NULL AND CUR_FXGZ.GZ_GGXH IS NULL
         AND CUR_FXGZ.GZ_CKKA IS NULL AND CUR_FXGZ.GZ_CKGB IS NULL AND CUR_FXGZ.GZ_HYD IS NULL
         AND CUR_FXGZ.GZ_DJQ IS NULL AND CUR_FXGZ.GZ_DJZ IS NULL AND CUR_FXGZ.GZ_ZJQ IS NULL AND CUR_FXGZ.GZ_ZJZ IS NULL THEN
        CONTINUE;
      END IF;
      
      -- 根据风险规则扫描出口电子信息
      FOR CUR_FXSJ IN (SELECT T.DJXH,T.CKBGDH,T.MYLAJ,T.CKNY,T.CKSP_DM,T.CKRQ_1,SUBSTR(T.CKBGDH,1,18) AS CKBGD18,T.HGSPMC,
                              S.NSRDZDAH,S.SWJG_DM,NVL(S.SHXYNO,S.NSRDJNO) AS NSRSBH,S.NSRMC
                         FROM TL_TSSH.CKTS_WBSJ_HG_BGD T
                        INNER JOIN TL_BJTS.GS_DJ_CKTMSDAB S ON S.CPCODE=T.DJXH
                        WHERE T.JGFS_DM<>'1039'
                          AND T.SJTB_SJ>=LD_BEGINDATE
                          AND (T.TSSWJG_DM_1 LIKE CUR_FXGZ.GZ_FW_SWJG||'%')
                          AND (CUR_FXGZ.GZ_SPDM IS NULL OR 
                              (SUBSTR(CUR_FXGZ.GZ_SPDM,1,1)='!' AND NOT REGEXP_LIKE(T.CKSP_DM,SUBSTR(CUR_FXGZ.GZ_SPDM,2))) OR
                              (SUBSTR(CUR_FXGZ.GZ_SPDM,1,1)<>'!' AND REGEXP_LIKE(T.CKSP_DM,CUR_FXGZ.GZ_SPDM)))
                          AND (CUR_FXGZ.GZ_SPMC IS NULL OR REGEXP_LIKE(T.HGSPMC,CUR_FXGZ.GZ_SPMC))
                          AND (CUR_FXGZ.GZ_GGXH IS NULL OR REGEXP_LIKE(T.GGXH,CUR_FXGZ.GZ_GGXH))
                          AND (CUR_FXGZ.GZ_CKKA IS NULL OR REGEXP_LIKE(T.HGGQKA_DM,CUR_FXGZ.GZ_CKKA))
                          AND (CUR_FXGZ.GZ_CKGB IS NULL OR REGEXP_LIKE(T.MYGDQSZ_DM,CUR_FXGZ.GZ_CKGB))
                          AND (CUR_FXGZ.GZ_HYD IS NULL OR 
                              (SUBSTR(CUR_FXGZ.GZ_HYD,1,1)='!' AND NOT REGEXP_LIKE(T.HZDWDQ_DM,SUBSTR(CUR_FXGZ.GZ_HYD,2))) OR
                              (SUBSTR(CUR_FXGZ.GZ_HYD,1,1)<>'!' AND REGEXP_LIKE(T.HZDWDQ_DM,CUR_FXGZ.GZ_HYD)))
                          AND (CUR_FXGZ.GZ_DJQ IS NULL OR DECODE(T.CKSL,0,0,T.MYLAJ/T.CKSL)>CUR_FXGZ.GZ_DJQ)
                          AND (CUR_FXGZ.GZ_DJZ IS NULL OR DECODE(T.CKSL,0,0,T.MYLAJ/T.CKSL)<CUR_FXGZ.GZ_DJZ)
                          AND (CUR_FXGZ.GZ_ZJQ IS NULL OR T.MYLAJ>CUR_FXGZ.GZ_ZJQ)
                          AND (CUR_FXGZ.GZ_ZJZ IS NULL OR T.MYLAJ<CUR_FXGZ.GZ_ZJZ)
      ) LOOP
        BEGIN
          -- TL_ADMIN.YJ_DATA_YJXX，态势感知风险管理，所有风险数据往这张表写数据
          INSERT INTO TL_ADMIN.YJ_DATA_YJXX(
                      TBPC,ID,SBID,NSRDZDAH,CJ_DATE,YJCODE,ZBCODE,YJ_OBJECT,YJ_COUNT,YJ_AMT,YJ_RECORD,YJ_MSG,SBYM,SWFLAG,QYFLAG,BMDFLAG)
               SELECT 0,SEQ_YJ_DATA_YJXX.NEXTVAL,0,CUR_FXSJ.NSRDZDAH,SYSDATE,'140','14001',CUR_FXSJ.CKSP_DM,1,CUR_FXSJ.MYLAJ,CUR_FXSJ.CKBGDH,
                      '风险商品出口(规则：'||NVL(CUR_FXGZ.GZ_MC,CUR_FXGZ.GZ_FXMS)||')，报关单号('||CUR_FXSJ.CKBGDH||
                      ')，商品代码('||CUR_FXSJ.CKSP_DM||')，商品名称('||CUR_FXSJ.CKSP_DM||')，出口美元金额'||CUR_FXSJ.MYLAJ||')',
                      CUR_FXSJ.CKNY,1,0,0
                 FROM DUAL
                WHERE NOT EXISTS (SELECT 1
                                    FROM TL_ADMIN.YJ_DATA_YJXX A
                                   WHERE A.SBID=0 AND A.NSRDZDAH=CUR_FXSJ.NSRDZDAH
                                     AND A.YJCODE='140' AND A.ZBCODE='14001'
                                     AND A.YJ_RECORD=CUR_FXSJ.CKBGDH)
                  AND NOT EXISTS (SELECT 1
                                      FROM TL_ADMIN.YJ_CS_BMD B
                                      LEFT JOIN TL_ADMIN.YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=CUR_FXSJ.NSRDZDAH
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=CUR_FXGZ.GZ_MC));
          -- TL_TSSH.JKGL_GY_FXSM_HGCK，原三三智检风险出口数据，待迁移
          INSERT INTO JKGL_GY_FXSM_HGCK(DJXH,CKBGDH,SMRQ,FXGZ)
               SELECT CUR_FXSJ.DJXH,CUR_FXSJ.CKBGDH,SYSDATE,CUR_FXGZ.GZ_MC
                 FROM DUAL
                WHERE NOT EXISTS (SELECT 1
                                    FROM JKGL_GY_FXSM_HGCK A
                                   WHERE A.DJXH=CUR_FXSJ.DJXH
                                     AND A.CKBGDH=CUR_FXSJ.CKBGDH)
                  AND NOT EXISTS (SELECT 1
                                      FROM TL_ADMIN.YJ_CS_BMD B
                                      LEFT JOIN TL_ADMIN.YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=CUR_FXSJ.NSRDZDAH
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=CUR_FXGZ.GZ_MC));
          -- TL_TSSH.MSG_PUSH_DATA，风险出口数据的短信提醒
          -- 从原PRO_JKGL_FXCKSP存储过程迁移到这来，原biztype为“风险出口”，现改为“风险出口电子信息”
          IF CUR_FXGZ.GZ_DXTXBZ='Y' THEN
            -- 20240819，插入风险出口的短信提醒信息，
            -- 风险出口短信提醒按18位报关单号汇总
            INSERT INTO MSG_PUSH_DATA(ID,SWJG_DM,NSRSBH,NSRMC,BIZTYPE,BIZKEY,QDSJ,JZSJ,YWBZ,SJTBSJ,IDLY)
                 SELECT SEQ_MSG_PUSH_DATA.NEXTVAL,CUR_FXSJ.SWJG_DM,CUR_FXSJ.NSRSBH,CUR_FXSJ.NSRMC,'风险出口电子信息',
                        CUR_FXSJ.CKBGD18,CUR_FXSJ.CKRQ_1,NULL,CUR_FXGZ.GZ_MC,SYSDATE,'1'
                   FROM DUAL
                  WHERE NOT EXISTS (SELECT 1
                                      FROM MSG_PUSH_DATA A
                                     WHERE A.BIZTYPE='风险出口电子信息'
                                       AND A.BIZKEY=CUR_FXSJ.CKBGD18)
                    AND NOT EXISTS (SELECT 1
                                      FROM TL_ADMIN.YJ_CS_BMD B
                                      LEFT JOIN TL_ADMIN.YJ_CS_BMD_SUB C ON C.BMDID=B.ID
                                     WHERE B.NSRDZDAH=CUR_FXSJ.NSRDZDAH
                                       AND B.YJCODE='140'
                                       AND (B.OBJFLAG='0' OR C.YJ_OBJECT=CUR_FXGZ.GZ_MC));  
          END IF;
          COMMIT;
        END;
      END LOOP;
    END;
  END LOOP;

  MERGE INTO FXGL_SZ_SPFXJH A
       USING (SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'一年以上未回函' AS GZ_MC,
                     T.FAHDSWJGMC||TO_CHAR(T.FAHQFRQ,'yyyy-mm-dd')||'发函，至今尚无明确回函意见' AS GZ_FXMS
                FROM TL_ADMIN.YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM IS NULL AND SYSDATE-T.FAHQFRQ>365) B
          ON (B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC)
        WHEN NOT MATCHED THEN
          INSERT (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID)
          VALUES (SEQ_FXGL_SZ_SPFXJH.NEXTVAL,'13300000000','浙江省税务局','SYSTEM',SYSDATE,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID);
  COMMIT;
  MERGE INTO FXGL_SZ_SPFXJH A
       USING (SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'回函存在异常业务' AS GZ_MC,
                     T.FAHDSWJGMC||TO_CHAR(T.FAHQFRQ,'yyyy-mm-dd')||'发函，对方税务机关回函存在异常业务' AS GZ_FXMS
                FROM TL_ADMIN.YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM='2') B
          ON (B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC)
        WHEN NOT MATCHED THEN
          INSERT (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID,GZ_YXQZ)
          VALUES (SEQ_FXGL_SZ_SPFXJH.NEXTVAL,'13300000000','浙江省税务局','SYSTEM',SYSDATE,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID,ADD_MONTHS(B.FUHQFRQ,12));
  COMMIT;
  /*MERGE INTO FXGL_SZ_SPFXJH A
       USING (SELECT T.FHXXBUUID,T.FUHQFRQ,T.GHQYNSRSBH_1,T.GHFQYMC_1,'回函正常其他情况不予退税' AS GZ_MC,
                     T.FAHDSWJGMC||TO_CHAR(T.FAHQFRQ,'yyyy-mm-dd')||'发函，对方税务机关回函正常，经核查其他情况不予退税' AS GZ_FXMS
                FROM TL_ADMIN.YJ_CS_YCHD_JS T
               WHERE T.FUHLX_DM<>'2' AND T.FUHCLYJ_DM='3') B
          ON (B.FHXXBUUID=A.FHXXBUUID AND B.GZ_MC=A.GZ_MC)
        WHEN NOT MATCHED THEN
          INSERT (ID,TSSWJG_DM,TSSWJG_MC,TBR,TBRQ,GZ_FW_SWJG,GZ_FW_DATA,GZ_MC,GZ_FXMS,GZ_GHQYSH,GZ_GHQYMC,GZ_DXTXBZ,QYBJ,FHXXBUUID,GZ_YXQZ)
          VALUES (SEQ_FXGL_SZ_SPFXJH.NEXTVAL,'13300000000','浙江省税务局','SYSTEM',SYSDATE,'133','2',B.GZ_MC,B.GZ_FXMS,B.GHQYNSRSBH_1,B.GHFQYMC_1,'N','Y',B.FHXXBUUID,ADD_MONTHS(B.FUHQFRQ,12));
  COMMIT;*/
  UPDATE FXGL_SZ_SPFXJH A
     SET A.GZ_YXQZ=(SELECT FUHQFRQ FROM TL_ADMIN.YJ_CS_YCHD_JS B WHERE B.FHXXBUUID=A.FHXXBUUID)
   WHERE A.FHXXBUUID IS NOT NULL AND A.GZ_MC='一年以上未回函';
  COMMIT;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_SZYJ_WLXX
prompt =====================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_SZYJ_WLXX
/*
 * 从出口发票备注或申报明细备注提取物流信息（车牌号、起运日期、起运地、快递单号）
 * LN_WLBZ : 初始NULL，
 *           备注（发票+出口）空白99，
 *           从发票备注提取到车牌号，初始10；日期大于出口日期+1；大于系统日期+2；日期空+3；地址空+5
 *           从发票备注提取到快递信息20
 *           从出口明细备注提取到车牌号，初始30；日期大于出口日期+1；大于系统日期+2；日期空+3；地址空+5
 *           从出口明细备注提取到快递信息40
 *           备注非空白，未提取到物流98
 */
AS
  LC_WLXX    VARCHAR2(1000);
  LN_WLBZ    NUMBER(2);
  LC_WLDM    CHAR(1);
  LC_CPH     VARCHAR2(500);
  LD_QYR     DATE;
  LC_QYD     VARCHAR2(500);
  LN_ADDR    NUMBER(3);
  LC_PATTERN VARCHAR2(500);
BEGIN
  FOR CUR_BGD IN (SELECT DJXH,BGDHGBH,CKFPBZ,CKMXBZ,WLXXLY_DM,CPH,QYRQ,QYD,CKRQ_1
                    FROM CKLLFX_DATA_BGDWL
                   WHERE WLXXLY_BZ IS NULL
                   ORDER BY SJGXSJ)
  LOOP
    LN_WLBZ := NULL;
    LC_WLDM := NULL;
    LC_CPH := NULL;
    LD_QYR := NULL;
    LC_QYD := NULL;
    
    -- 1、发票备注+出口明细备注 为空
    IF (TRIM(CUR_BGD.CKFPBZ) IS NULL) AND (TRIM(CUR_BGD.CKMXBZ) IS NULL) THEN
      LN_WLBZ := 99;
      LC_WLDM := '0';
      UPDATE CKLLFX_DATA_BGDWL T
         SET T.WLXXLY_BZ=LN_WLBZ,
             T.WLXXLY_DM=LC_WLDM,
             T.CPH=LC_CPH,
             T.QYRQ=LD_QYR,
             T.QYD=LC_QYD
       WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
      COMMIT;
      CONTINUE;
    END IF;

    -- 2、发票备注提取到车牌号
    LC_CPH := f_wlgl_extract_plate(CUR_BGD.CKFPBZ,LN_ADDR);
    IF LC_CPH IS NOT NULL THEN
      -- 2.1、从车牌号以后备注内容提取起运日、起运地信息，剔除前面的干扰因素
      LC_WLXX := SUBSTR(CUR_BGD.CKFPBZ,LN_ADDR);
      LD_QYR := f_wlgl_extract_date(LC_WLXX,CUR_BGD.CKRQ_1);
      LC_QYD := f_wlgl_extract_from(LC_WLXX);

      -- 2.2、起运日或起运地为空，提取物流关键字位置，从关键字位置以后再提取一次
      LC_PATTERN := '车牌|车号|车辆|起运|起始|起送|起至运|启运|始运|始发|出发|出运|出货|发车|发货|装车|装货|装柜|装箱|装运|送货|拉货|货源地|托运';
      LN_ADDR := REGEXP_INSTR(CUR_BGD.CKFPBZ,LC_PATTERN,1);
      IF LN_ADDR > 0 THEN
        LC_WLXX := SUBSTR(CUR_BGD.CKFPBZ,LN_ADDR);
        IF LD_QYR IS NULL THEN
          LD_QYR := f_wlgl_extract_date(LC_WLXX,CUR_BGD.CKRQ_1);
        END IF;
        IF LC_QYD IS NULL THEN
          LC_QYD := f_wlgl_extract_from(LC_WLXX);
        END IF;
      END IF;

      -- 2.3、如果起运日或起运地还是为空，从完整备注中再提取一次
      IF LD_QYR IS NULL THEN
        LD_QYR := f_wlgl_extract_date(CUR_BGD.CKFPBZ,CUR_BGD.CKRQ_1);
      END IF;
      IF LC_QYD IS NULL THEN
        LC_QYD := f_wlgl_extract_from(CUR_BGD.CKFPBZ);
      END IF;

      -- 2.4、根据起运日或起运地是否为空，记录不同结果
      LC_WLDM := '1';
      LN_WLBZ := 10;
      IF LD_QYR IS NULL THEN
        LN_WLBZ := LN_WLBZ + 3;
      ELSIF LD_QYR>=SYSDATE THEN
        LN_WLBZ := LN_WLBZ + 2;
      ELSIF LD_QYR>=CUR_BGD.CKRQ_1 THEN
        LN_WLBZ := LN_WLBZ + 1;
      END IF;
      IF LC_QYD IS NULL THEN
        LN_WLBZ := LN_WLBZ + 5;
      END IF;
      UPDATE CKLLFX_DATA_BGDWL T
         SET T.WLXXLY_BZ=LN_WLBZ,
             T.WLXXLY_DM=LC_WLDM,
             T.CPH=LC_CPH,
             T.QYRQ=LD_QYR,
             T.QYD=LC_QYD
       WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
      COMMIT;
      CONTINUE;
    END IF;

    -- 2、发票备注未提取到车牌号，但提取到快递信息
    LC_CPH := f_wlgl_extract_parcel(CUR_BGD.CKFPBZ);
    IF LC_CPH IS NOT NULL THEN
      LN_WLBZ := 20;
      LC_WLDM := '1';
      UPDATE CKLLFX_DATA_BGDWL T
         SET T.WLXXLY_BZ=LN_WLBZ,
             T.WLXXLY_DM=LC_WLDM,
             T.CPH=LC_CPH,
             T.QYRQ=LD_QYR,
             T.QYD=LC_QYD
       WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
      COMMIT;
      CONTINUE;
    END IF;

    -- 3、出口明细备注提取到车牌号
    LC_CPH := f_wlgl_extract_plate(CUR_BGD.CKMXBZ,LN_ADDR);
    IF LC_CPH IS NOT NULL THEN
      LN_WLBZ := 30;
      LC_WLDM := '2';
      LD_QYR := f_wlgl_extract_date(CUR_BGD.CKMXBZ,CUR_BGD.CKRQ_1);
      IF LD_QYR IS NULL THEN
        LN_WLBZ := LN_WLBZ + 3;
      ELSIF LD_QYR>=SYSDATE THEN
        LN_WLBZ := LN_WLBZ + 2;
      ELSIF LD_QYR>=CUR_BGD.CKRQ_1 THEN
        LN_WLBZ := LN_WLBZ + 1;
      END IF;
      LC_QYD := f_wlgl_extract_from(CUR_BGD.CKMXBZ);
      IF LC_QYD IS NULL THEN
        LN_WLBZ := LN_WLBZ + 5;
      END IF;
      UPDATE CKLLFX_DATA_BGDWL T
         SET T.WLXXLY_BZ=LN_WLBZ,
             T.WLXXLY_DM=LC_WLDM,
             T.CPH=LC_CPH,
             T.QYRQ=LD_QYR,
             T.QYD=LC_QYD
       WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
      COMMIT;
      CONTINUE;
    END IF;

    -- 4、出口明细备注未提取到车牌号，但提取到快递信息
    LC_CPH := f_wlgl_extract_parcel(CUR_BGD.CKMXBZ);
    IF LC_CPH IS NOT NULL THEN
      LN_WLBZ := 40;
      LC_WLDM := '2';
      UPDATE CKLLFX_DATA_BGDWL T
         SET T.WLXXLY_BZ=LN_WLBZ,
             T.WLXXLY_DM=LC_WLDM,
             T.CPH=LC_CPH,
             T.QYRQ=LD_QYR,
             T.QYD=LC_QYD
       WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
      COMMIT;
      CONTINUE;
    END IF;

    -- 5、发票备注+出口明细备注 不包含物流关键字
    LN_WLBZ := 98;
    UPDATE CKLLFX_DATA_BGDWL T
       SET T.WLXXLY_BZ=LN_WLBZ,
           T.WLXXLY_DM=LC_WLDM,
           T.CPH=LC_CPH,
           T.QYRQ=LD_QYR,
           T.QYD=LC_QYD
     WHERE T.DJXH=CUR_BGD.DJXH AND T.BGDHGBH=CUR_BGD.BGDHGBH;
    COMMIT;
  END LOOP;
  
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_AFTER_ETL
prompt =====================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_AFTER_ETL
(
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_SBYY          VARCHAR2(2000);
  LD_DEALDATA      DATE;          --用于基础数据处理的提前量
  LN_LOG           NUMBER(2);
  LC_BBNY          VARCHAR2(6);   --本期制表年月
  LD_BBNY_KSNF     DATE;          --本期制表年月年初
  LD_BBNY_KSRQ     DATE;          --本期制表年月开始日期，一般为制表年月的月初
  LD_BBNY_JZRQ     DATE;          --本期制表年月结束日期，一般为制表年月的下一个月初
  LC_DJZCLX        VARCHAR2(6);   --本期制表年月
  GLH_JSJE         NUMBER(18,2);
  GLH_TSL          NUMBER(18,2);
  GLH_TMSE         NUMBER(18,2);
  LN_ALLCK         NUMBER(18,2);
  LN_SNCK          NUMBER(18,2);
  LN_MYLAJ         NUMBER(18,2);
  LN_RMBLAJ        NUMBER(18,2);
  LN_MDTSE         NUMBER(18,2);
  LN_ZH_MDTSE      NUMBER(18,2);
  LN_BYTS_MDTSE    NUMBER(18,2);
  LN_BYBL_MDTSE    NUMBER(18,2);
  LN_ZZS           NUMBER(18,2);
  LN_XFS           NUMBER(18,2);
  LN_MDSE          NUMBER(18,2);
  SN_ZZS           NUMBER(18,2);
  SN_XFS           NUMBER(18,2);
  SN_MDSE          NUMBER(18,2);
  SY_ZZS           NUMBER(18,2);
  SY_XFS           NUMBER(18,2);
  SY_MDSE          NUMBER(18,2);
  LD_LASTRQ        DATE;
  V_ZLC_FS         NUMBER(18,2);
  V_ZLC_TS_AMT     NUMBER(18,2);
  V_ZLC_MD_AMT     NUMBER(18,2);
  V_ZLC_ZK_AMT     NUMBER(18,2);
  V_FF_DATE        DATE;
  V_SL_DATE        DATE;
  V_FH_DATE        DATE;
  V_FH_USER        VARCHAR2(20);
  V_YWHZ_DATE      DATE;
  V_YWHZ_USER      VARCHAR2(20);
  V_SEHZ_DATE      DATE;
  V_SEHZ_USER      VARCHAR2(20);
  V_TSKP_DATE      DATE;
  V_TSTK_DATE      DATE;
  LN_I             NUMBER(10);
  V_ZFBZ           CHAR(1);
  V_ZFR_DM         VARCHAR2(100);
  V_ZFRQ           DATE;
  V_CKSPTSSPLX_DM  CHAR(1);
  V_TSL            NUMBER(18,2);
  V_JGFSTSLX_DM    CHAR(1);
  V_HYDXZQH_DM     CHAR(4);
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  LD_DEALDATA:=TRUNC(SYSDATE) - 3;
  LN_LOG  :=2;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_AFTER_ETL开始处理！');
  COMMIT;

  --获取当前制表区间
  BEGIN
    SELECT T.BBNY, T.BBNY_KSRQ, T.BBNY_JZRQ, T.BBNY_KSNF
      INTO LC_BBNY, LD_BBNY_KSRQ, LD_BBNY_JZRQ, LD_BBNY_KSNF
      FROM (SELECT *
              FROM TL_ADMIN.TJBB_CS_ZBRQ
             WHERE SYSDATE>=BBNY_JZRQ
             ORDER BY BBNY_JZRQ DESC) T
     WHERE ROWNUM=1;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('获取当前制表区间成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('获取当前制表区间失败！', LC_SBYY);
      COMMIT;

      LC_BBNY := TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMM');
      LD_BBNY_KSRQ := TRUNC(ADD_MONTHS(SYSDATE,-1),'MM');
      LD_BBNY_JZRQ := TRUNC(SYSDATE,'MM');
      LD_BBNY_KSNF := TRUNC(ADD_MONTHS(SYSDATE,-1),'YY');
  END;

  --对部分外贸企业免退税申报，前一次全部分流以后又作废重新申报导致CKTS_LC_SBXX数据重复，LCSLID_SB设置错误进行纠正
  BEGIN
    LN_I:=0;
    FOR CUR_DUP IN (SELECT T.DJXH,T.SSQ,T.SBPC
                      FROM CKTS_LC_SBXX T
                     WHERE T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL
                     GROUP BY T.DJXH,T.SSQ,T.SBPC
                    HAVING COUNT(1)>1)
    LOOP
      FOR CUR_ZFLC IN (SELECT S.UUID,S.LCSLID_SB
                         FROM CKTS_LC_SBXX S
                        WHERE S.DJXH=CUR_DUP.DJXH AND S.SSQ=CUR_DUP.SSQ AND S.SBPC=CUR_DUP.SBPC AND S.ZFBZ IS NULL
                          AND S.QDSJ<>(SELECT MAX(R.QDSJ)
                                         FROM CKTS_LC_SBXX R
                                        WHERE R.DJXH=CUR_DUP.DJXH AND R.SSQ=CUR_DUP.SSQ AND R.SBPC=CUR_DUP.SBPC))
      LOOP
        BEGIN
          SELECT A.ZFBZ,A.ZFR_DM,A.ZFRQ
            INTO V_ZFBZ,V_ZFR_DM,V_ZFRQ
            FROM CKTS_LC_SHXX_ZF A
           WHERE A.DJXH=CUR_DUP.DJXH AND A.SSQ=CUR_DUP.SSQ AND A.SBPC=CUR_DUP.SBPC AND A.ZLCLCSLID=CUR_ZFLC.LCSLID_SB
             AND A.ZFRQ=(SELECT MAX(B.ZFRQ)
                           FROM CKTS_LC_SHXX_ZF B
                          WHERE B.DJXH=CUR_DUP.DJXH AND B.SSQ=CUR_DUP.SSQ AND B.SBPC=CUR_DUP.SBPC AND B.ZLCLCSLID=CUR_ZFLC.LCSLID_SB)
             AND ROWNUM=1;
        EXCEPTION
          WHEN OTHERS THEN
            CONTINUE;
        END;

        UPDATE CKTS_LC_SBXX A
           SET A.ZFBZ=V_ZFBZ,A.ZFR_DM=V_ZFR_DM,A.ZFRQ=V_ZFRQ
         WHERE A.UUID=CUR_ZFLC.UUID;
        UPDATE CKTS_LC_SHXX A
           SET A.ZFBZ=V_ZFBZ,A.ZFR_DM=V_ZFR_DM,A.ZFRQ=V_ZFRQ
         WHERE A.UUID=CUR_ZFLC.UUID;
        UPDATE CKTS_LC_SHXX A
           SET A.LCSLID_SB=' '
         WHERE A.DJXH=CUR_DUP.DJXH AND A.SSQ=CUR_DUP.SSQ AND A.SBPC=CUR_DUP.SBPC AND A.LCSLID<>CUR_ZFLC.LCSLID_SB;
        UPDATE CKTS_SB_MTS_CKMX A
           SET A.LCSLID_SB=' '
         WHERE A.LCSLID_SB=CUR_ZFLC.LCSLID_SB;
        UPDATE CKTS_SB_MTS_JHMX A
           SET A.LCSLID_SB=' '
         WHERE A.LCSLID_SB=CUR_ZFLC.LCSLID_SB;
        DELETE FROM GLXT_BB_SHXT_LCXX A
         WHERE A.UUID=CUR_ZFLC.UUID;
        COMMIT;
        LN_I:=LN_I +1;
      END LOOP;
    END LOOP;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('对部分外贸企业免退税申报重复数据处理成功！' || LN_I);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('对部分外贸企业免退税申报重复数据处理失败！', LC_SBYY);
      COMMIT;
  END;

  --GLXT_BB_SHXT_DJXX数据处理
  --设置备案信息的级次
  BEGIN
    UPDATE GLXT_BB_SHXT_DJXX T
       SET T.SQ_DATE=DATE'2009-11-19'
     WHERE T.CPCODE='10113305000049913646';
    COMMIT;

    --外贸综合服务企业
    --35号公告+17号公告
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '71'
     WHERE BAJC_YEAR='00' AND WZFQY='Y' AND WZFQY13='Y' AND JSMODE='2';
    COMMIT;
    --35号公告
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '72'
     WHERE BAJC_YEAR='00' AND WZFQY='Y' AND JSMODE='2';
    COMMIT;
    --17号公告
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '70'
     WHERE BAJC_YEAR='00' AND WZFQY13='Y' AND JSMODE='2';
    COMMIT;
    --服务贸易
    --国际运输业务
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '60'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE LIKE '%01%' AND YSFS IS NOT NULL;
    COMMIT;
    --研发设计业务
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '50'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE LIKE '%03%' AND (YFSJFW LIKE '%01%' OR YFSJFW LIKE '%03%');
    COMMIT;
    --其他服务贸易
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '40'
     WHERE BAJC_YEAR='00' AND YSFW='Y' AND YSFWCODE IS NOT NULL;
    COMMIT;
    --其他企业
    --周边业务
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '30'
     WHERE BAJC_YEAR='00'
       AND EXISTS (SELECT 1 FROM CKTS_LC_SBXX A WHERE A.TSSWJG_DM=T.SWJGDM AND A.DJXH=T.DJXH_JS AND A.SBYWB_DM IN ('A0302001','A0303001','A0304001') AND A.ZFBZ IS NULL);
    COMMIT;
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '30'
     WHERE BAJC_YEAR='00'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.TSSWJG_DM=T.SWJGDM AND A.DJXH=T.DJXH_JS AND A.TBYY_DM IN ('470','480'));
    COMMIT;
    --生产企业
    --外商投资企业
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '23'
     WHERE BAJC_YEAR='00' AND JSMODE='1' AND SUBSTR(DJZCLX_JS,0,1) IN ('2','3');
    COMMIT;
    --委托出口企业
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '22'
     WHERE BAJC_YEAR='00' AND JSMODE='1' AND LENGTH(QYHGDM)=10 AND QYHGDM LIKE '9%';
    COMMIT;
    --内资生产企业
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '21'
     WHERE BAJC_YEAR='00' AND JSMODE='1';
    COMMIT;
    --外贸企业
    UPDATE GLXT_BB_SHXT_DJXX T
       SET BAJC_YEAR = '10'
     WHERE BAJC_YEAR='00' AND JSMODE='2';
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('GLXT_BB_SHXT_DJXX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('GLXT_BB_SHXT_DJXX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --部分生产企业登记注册类型调整过，导致既有内资又有外资，统计级次按最新调整
  BEGIN
    FOR CUR_DJXH IN (SELECT DJXH FROM TL_TSSH.CKTS_LC_SHXX
                      WHERE LCJSRQ>=DATE'2024-01-01' AND SBYWB_DM='A0305001' AND LCTJJC IN ('21','23')
                      GROUP BY DJXH HAVING COUNT(DISTINCT LCTJJC)>1)
    LOOP
      BEGIN
        SELECT T.DJZCLX_JS
          INTO LC_DJZCLX
          FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
         WHERE T.DJXH_JS=CUR_DJXH.DJXH;
      EXCEPTION
        WHEN OTHERS THEN
          CONTINUE;
      END;
      IF SUBSTR(LC_DJZCLX,1,1)='1' THEN
        UPDATE TL_TSSH.CKTS_LC_SHXX t SET T.LCTJJC='21' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='23';
        UPDATE TL_TSSH.CKTS_LC_YWHZXX t SET T.LCTJJC='21' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='23';
        UPDATE TL_TSSH.CKTS_LC_SEHZXX t SET T.LCTJJC='21' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='23';
        COMMIT;
      ELSIF SUBSTR(LC_DJZCLX,1,1) IN ('2','3') THEN
        UPDATE TL_TSSH.CKTS_LC_SHXX t SET T.LCTJJC='23' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='21';
        UPDATE TL_TSSH.CKTS_LC_YWHZXX t SET T.LCTJJC='23' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='21';
        UPDATE TL_TSSH.CKTS_LC_SEHZXX t SET T.LCTJJC='23' WHERE T.DJXH=CUR_DJXH.DJXH AND T.LCTJJC='21';
        COMMIT;
      END IF;
    END LOOP;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('部分生产企业登记注册类型调整过，统计级次按最新调整成功！' || LN_I);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('部分生产企业登记注册类型调整过，统计级次按最新调整失败！', LC_SBYY);
      COMMIT;
  END;

  --部分企业出口与收核登记序号不一致，需要通过CKTS_ZS_DJXHDZB转换
  BEGIN
    LN_I:=0;
    FOR CUR_DJXH IN (SELECT S.DJXH_CK,S.DJXH_ZS FROM CKTS_ZS_DJXHDZB S)
    LOOP
      UPDATE TL_ADMIN.FG_CKTSFN_HXZG T
         SET (T.SKSSSWJG_DM,T.CPCODE,T.QYHGDM,T.NSRSBH,T.NSRMC)=
             (SELECT R.SWJGDM,R.CPCODE,R.QYHGDM,NVL(R.SHXYNO,R.NSRDJNO),R.NSRMC FROM GLXT_BB_SHXT_DJXX R WHERE R.DJXH_JS=CUR_DJXH.DJXH_CK)
       WHERE T.DJXH=CUR_DJXH.DJXH_ZS;
      COMMIT;
      UPDATE CKTS_ZS_SRTHS T
         SET T.DJXH=CUR_DJXH.DJXH_CK
       WHERE T.DJXH=CUR_DJXH.DJXH_ZS;
      COMMIT;
      UPDATE CKTS_ZS_MDTKB T
         SET T.DJXH=CUR_DJXH.DJXH_CK
       WHERE T.DJXH=CUR_DJXH.DJXH_ZS;
      COMMIT;
      UPDATE CKTS_ZS_TKGZ T
         SET T.DJXH=CUR_DJXH.DJXH_CK
       WHERE T.DJXH=CUR_DJXH.DJXH_ZS;
      COMMIT;
      LN_I:=LN_I +1;
    END LOOP;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('出口与收核登记序号不一致，通过CKTS_ZS_DJXHDZB转换成功！' || LN_I);
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('出口与收核登记序号不一致，通过CKTS_ZS_DJXHDZB转换失败！', LC_SBYY);
      COMMIT;
  END;

  --针对部分税局返纳不符合返纳数据etl条件，设置临时表保存转换
  BEGIN
    INSERT INTO TL_ADMIN.FG_CKTSFN_HXZG
           (SPUUID,SKSSSWJG_DM,DJXH,CPCODE,QYHGDM,NSRSBH,NSRMC,ZSUUID,DZSPHM,DZSPMXXH,ZSXM_DM,SKSX_DM,YSKM_DM,
           SKSSQQ,SKSSQZ,KJRQ,JSYJ,JKQX,RKRQ,SJJE,YZPZXH_CKTS,XGRQ,SJTB_DATE,DZJG,SKSSSWJG_JS,YZHYTMSKYY_DM,YWHZBUUID,BZ)
    SELECT SPUUID,SKSSSWJG_DM,DJXH,CPCODE,QYHGDM,NSRSBH,NSRMC,ZSUUID,DZSPHM,DZSPMXXH,ZSXM_DM,SKSX_DM,YSKM_DM,
           SKSSQQ,SKSSQZ,KJRQ,JSYJ,JKQX,RKRQ,SJJE,YZPZXH_CKTS,XGRQ,SJTB_DATE,DZJG,SKSSSWJG_JS,YZHYTMSKYY_DM,YWHZBUUID,BZ
      FROM TL_ADMIN.FG_CKTSFN_HXZG_YGP T
     WHERE NOT EXISTS (SELECT 1 FROM TL_ADMIN.FG_CKTSFN_HXZG S WHERE S.SPUUID=T.SPUUID);

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('青田有企业返纳不符合返纳数据etl条件，设置临时表保存转换成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('青田有企业返纳不符合返纳数据etl条件，设置临时表保存转换失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_MDT_CKMX
  BEGIN
    --删除作废流程信息
    LN_I:=0;
    FOR CUR_MDT IN (SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0305001' AND NVL(ZFRQ,QDSJ)>=LD_DEALDATA)
    LOOP
      BEGIN
        DELETE FROM CKTS_SB_MDT_CKMX T WHERE T.LCSLID=CUR_MDT.LCSLID_SB;
        DELETE FROM CKTS_SB_MDT_GJYS T WHERE T.LCSLID=CUR_MDT.LCSLID_SB;
        DELETE FROM CKTS_SB_MDT_YFSJ T WHERE T.LCSLID=CUR_MDT.LCSLID_SB;
        COMMIT;
        LN_I:=LN_I +1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX删除作废流程信息！' || LN_I);
      COMMIT;
    END IF;
    --设置LCSLID_SB
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ' AND T.SSQ>='201901';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX分流数据设置LCSLID_SB！');
      COMMIT;
    END IF;
    --设置LCSLID_FS
    --按税局、企业、业务、准予退税所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.MDTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.MDTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期准予退税设置LCSLID_FS！');
      COMMIT;
    END IF;
    --按税局、企业、业务、不予退税所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.BYTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期不予退税设置LCSLID_FS！');
      COMMIT;
    END IF;
    --按税局、企业、业务、不予办理所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYBLNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.BYBLNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期不予办理设置LCSLID_FS！');
      COMMIT;
    END IF;
    --企业撤回申报数据
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.LCSLID_FS=T.LCSLID
     WHERE T.LCSLID_FS=' ' AND T.SSQ>='201901' AND T.SJLY='2' AND T.CHBZ='Y';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX撤回申报数据设置LCSLID_FS！');
      COMMIT;
    END IF;
/*
    UPDATE CKTS_SB_MDT_CKMX T
       SET T.ZHBZ_1='N'
     WHERE T.ZHBZ_1='Y' AND (T.MDTSNY IS NOT NULL OR T.BYTSNY IS NOT NULL);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX后期取消暂缓！');
      COMMIT;
    END IF;
*/
    --BYTSBZ：明确
    --ZBBLBZ：待定
    --ZYTSBZ：CASE WHEN TRIM(B.MDTSNY) IS NOT NULL THEN 'Y' ELSE 'N' END

    --免抵退FSRQ处理
    FOR LCXX_FH IN (SELECT T.LCSLID, MIN(S.FSRQ) AS FSRQ
                      FROM CKTS_SB_MDT_CKMX T
                     INNER JOIN CKTS_LC_SHXX R ON R.LCSLID=T.LCSLID
                     INNER JOIN CKTS_LC_YWHZXX S ON S.LCSLID_FS=R.LCSLID_FS
                     WHERE T.FSRQ IS NULL
                     GROUP BY T.LCSLID)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MDT_CKMX T
           SET T.FSRQ=LCXX_FH.FSRQ
         WHERE LCSLID=LCXX_FH.LCSLID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_CKMX设置FSRQ！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MDT_CKMX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_MDT_GJYS
  BEGIN
    --设置LCSLID_SB
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_GJYS T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    --设置LCSLID_FS
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_GJYS T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.MDTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SJLY='2' AND T.MDTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_GJYS后期准予设置LCSLID_FS！');
      COMMIT;
    END IF;
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_GJYS T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SJLY='2' AND T.BYTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_GJYS后期不予设置LCSLID_FS！');
      COMMIT;
    END IF;
    --BYTSBZ：明确
    --ZBBLBZ：待定
    --ZYTSBZ：CASE WHEN TRIM(B.MDTSNY) IS NOT NULL THEN 'Y' ELSE 'N' END

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MDT_GJYS数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_GJYS数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_MDT_YFSJ
  BEGIN
    --设置LCSLID_SB
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_YFSJ T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    --设置LCSLID_FS
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_YFSJ T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.MDTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SJLY='2' AND T.MDTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_YFSJ后期准予设置LCSLID_FS！');
      COMMIT;
    END IF;
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MDT_YFSJ T
       SET T.LCSLID_FS=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0305001' AND T.BYTSNY=A.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_FS=' ' AND T.SJLY='2' AND T.BYTSNY IS NOT NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MDT_YFSJ后期不予设置LCSLID_FS！');
      COMMIT;
    END IF;
    --BYTSBZ：明确
    --ZBBLBZ：待定
    --ZYTSBZ：CASE WHEN TRIM(B.MDTSNY) IS NOT NULL THEN 'Y' ELSE 'N' END

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MDT_YFSJ数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MDT_YFSJ数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_MTS_JHMX, CKTS_SB_MTS_CKMX
  BEGIN
    --删除作废流程信息
    LN_I:=0;
    FOR CUR_MTS IN (SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0301001' AND NVL(ZFRQ,QDSJ)>=LD_DEALDATA)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX T SET T.LCSLID_SB=' ' WHERE T.LCSLID_SB=CUR_MTS.LCSLID_SB;
        UPDATE CKTS_SB_MTS_CKMX T SET T.LCSLID_SB=' ' WHERE T.LCSLID_SB=CUR_MTS.LCSLID_SB;
        UPDATE CKTS_SB_MTS_YSFW T SET T.LCSLID_SB=' ' WHERE T.LCSLID_SB=CUR_MTS.LCSLID_SB;
        COMMIT;
        DELETE FROM CKTS_SB_MTS_JHMX T WHERE T.LCSLID=CUR_MTS.LCSLID_SB;
        DELETE FROM CKTS_SB_MTS_CKMX T WHERE T.LCSLID=CUR_MTS.LCSLID_SB;
        DELETE FROM CKTS_SB_MTS_YSFW T WHERE T.LCSLID=CUR_MTS.LCSLID_SB;
        COMMIT;
        LN_I:=LN_I +1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_**MX删除作废流程信息！' || LN_I);
      COMMIT;
    END IF;

    --设置LCSLID_SB
    UPDATE CKTS_SB_MTS_JHMX T
       SET T.LCSLID_SB=T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.SL<0;
    COMMIT;
    UPDATE CKTS_SB_MTS_CKMX T
       SET T.LCSLID_SB=T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.CKSL<0;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_*设置LCSLID_SB(红字冲减业务)！');
      COMMIT;
    END IF;
    UPDATE CKTS_SB_MTS_JHMX T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0301001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_JHMX设置LCSLID_SB！');
      COMMIT;
    END IF;
    UPDATE CKTS_SB_MTS_CKMX T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_SB_MTS_JHMX A
                             WHERE A.DJXH=T.DJXH AND A.GLH=T.GLH AND A.LCSLID=T.LCSLID
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_CKMX设置LCSLID_SB！');
      COMMIT;
    END IF;

    -- CKMX.JSJE, TSL, TMSE
    -- 每天过程表的数据全部刷新（15-55W）+结果表的增量
    --20260728加数据同步时间条件，期望可以用到索引
    LN_I:=0;
    FOR CUR_MTSCK IN (SELECT T.DJXH,T.GLH,T.CKSP_DM,T.LCSLID,NVL(T.LCSLID_SB,'1') AS LCSLID_SB,SUM(T.CKSL) AS GLH_CKSL,COUNT(1) AS GLH_N
                        FROM CKTS_SB_MTS_CKMX T
                       WHERE T.SJTB_SJ>=LD_DEALDATA AND NVL(T.JSJE,0)=0
                       GROUP BY T.DJXH,T.GLH,T.CKSP_DM,T.LCSLID,NVL(T.LCSLID_SB,'1'))
    LOOP
      BEGIN
        SELECT SUM(CASE WHEN S.SZ='V' THEN S.JSJE ELSE 0 END), MAX(CASE WHEN S.SZ='V' THEN S.TSL ELSE 0 END), SUM(S.TSE)
          INTO GLH_JSJE, GLH_TSL, GLH_TMSE
          FROM CKTS_SB_MTS_JHMX S
         WHERE S.DJXH=CUR_MTSCK.DJXH AND S.GLH=CUR_MTSCK.GLH AND S.CKSP_DM=CUR_MTSCK.CKSP_DM AND S.LCSLID=CUR_MTSCK.LCSLID AND NVL(S.LCSLID_SB,'1')=CUR_MTSCK.LCSLID_SB;
      EXCEPTION
        WHEN OTHERS THEN
          GLH_JSJE :=0;
          GLH_TSL :=0;
          GLH_TMSE :=0;
      END;
      UPDATE CKTS_SB_MTS_CKMX A
         SET A.JSJE = CASE WHEN CUR_MTSCK.GLH_N=1 THEN GLH_JSJE
                           WHEN CUR_MTSCK.GLH_CKSL=0 THEN (CASE WHEN A.CKSL>0 THEN GLH_JSJE WHEN A.CKSL<0 THEN (-1)*GLH_JSJE ELSE 0 END)
                           ELSE GLH_JSJE * A.CKSL / CUR_MTSCK.GLH_CKSL END,
             A.TSL = GLH_TSL,
             A.TSE = CASE WHEN CUR_MTSCK.GLH_N=1 THEN GLH_TMSE
                           WHEN CUR_MTSCK.GLH_CKSL=0 THEN (CASE WHEN A.CKSL>0 THEN GLH_TMSE WHEN A.CKSL<0 THEN (-1)*GLH_TMSE ELSE 0 END)
                          ELSE GLH_TMSE * A.CKSL / CUR_MTSCK.GLH_CKSL END
       WHERE A.DJXH=CUR_MTSCK.DJXH AND A.GLH=CUR_MTSCK.GLH AND A.CKSP_DM=CUR_MTSCK.CKSP_DM AND A.LCSLID=CUR_MTSCK.LCSLID AND NVL(A.LCSLID_SB,'1')=CUR_MTSCK.LCSLID_SB;
      COMMIT;
      LN_I:=LN_I +1;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_CKMX 设置（JSJE、TSL、TSE）！' || LN_I);
      COMMIT;
    END IF;

    -- JHMX.CKRQ_1
    -- 每天过程表的数据全部刷新（15-55W）+结果表的增量
    --20260728鉴于查询条件有索引，仅优化关联条件
    LN_I:=0;
    FOR CUR_MTS IN (SELECT S.UUID,S.DJXH,S.GLH,S.LCSLID,MAX(T.CKRQ_1) AS CKRQ_1
                      FROM CKTS_SB_MTS_JHMX S
                     INNER JOIN CKTS_SB_MTS_CKMX T
                        ON T.DJXH=S.DJXH AND T.GLH=S.GLH AND T.CKSP_DM=S.CKSP_DM AND T.LCSLID=S.LCSLID
                     WHERE S.CKRQ_1=DATE'1900-01-01'
                     GROUP BY S.UUID,S.DJXH,S.GLH,S.LCSLID)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX R
           SET CKRQ_1 = CUR_MTS.CKRQ_1
         WHERE R.UUID=CUR_MTS.UUID;
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_JHMX设置CKRQ_1！合计'|| LN_I);
      COMMIT;
    END IF;

    --BYBLBZ
    --20260728加数据同步时间条件，期望可以用到索引
    LN_I:=0;
    FOR CUR_MTS IN (SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM CKTS_SB_MTS_CKMX T
                     INNER JOIN CKTS_SB_MTS_JHMX S
                        ON T.DJXH=S.DJXH AND T.GLH=S.GLH AND T.CKSP_DM=S.CKSP_DM AND T.LCSLID=S.LCSLID
                     WHERE T.SJTB_SJ>=LD_DEALDATA AND T.BYBLBZ<>S.BYBLBZ)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX R
           SET R.BYBLBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID;
        UPDATE CKTS_SB_MTS_CKMX R
           SET R.BYBLBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID;
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_**MX同步BYBLBZ！' || LN_I);
      COMMIT;
    END IF;

    --BYTSBZ：明确
    --20260728加数据同步时间条件，期望可以用到索引
    LN_I:=0;
    FOR CUR_MTS IN (SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM CKTS_SB_MTS_CKMX T
                     INNER JOIN CKTS_SB_MTS_JHMX S
                        ON T.DJXH=S.DJXH AND T.GLH=S.GLH AND T.CKSP_DM=S.CKSP_DM AND T.LCSLID=S.LCSLID
                     WHERE T.SJTB_SJ>=LD_DEALDATA AND T.BYTSBZ<>S.BYTSBZ)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX R
           SET R.BYTSBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID;
        UPDATE CKTS_SB_MTS_CKMX R
           SET R.BYTSBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID;
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_**MX同步BYTSBZ！' || LN_I);
      COMMIT;
    END IF;

    --ZBBLBZ：需要根据CKTS_LC_SHYDDCL重新设置
    --20260730从CKTS_LC_SHYDDCL设置暂不办理，从CKTS_LC_JCZBBL解除暂不办理
    LN_I:=0;
    FOR CUR_MTS IN (SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM (SELECT * FROM CKTS_LC_SHYDDCL WHERE SBYWB_DM='A0301001'
                             UNION ALL
                            SELECT * FROM CKTS_LC_SHYDDCL_SHXT WHERE SBYWB_DM='A0301001') T)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX R
           SET R.SJTB_SJ=SYSDATE, R.ZBBLBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID AND R.ZBBLBZ='N';
        UPDATE CKTS_SB_MTS_CKMX R
           SET R.SJTB_SJ=SYSDATE, R.ZBBLBZ='Y'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID AND R.ZBBLBZ='N';
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_**MX设置ZBBLBZ！' || LN_I);
      COMMIT;
    END IF;

    LN_I:=0;
    FOR CUR_MTS IN (SELECT DISTINCT T.DJXH, T.GLH, T.LCSLID
                      FROM CKTS_LC_JCZBBL T
                     WHERE T.SBYWB_DM='A0301001')
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_JHMX R
           SET R.SJTB_SJ=SYSDATE, R.ZBBLBZ='N'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID AND R.ZBBLBZ='Y';
        UPDATE CKTS_SB_MTS_CKMX R
           SET R.SJTB_SJ=SYSDATE, R.ZBBLBZ='N'
         WHERE R.DJXH=CUR_MTS.DJXH AND R.GLH=CUR_MTS.GLH AND R.LCSLID=CUR_MTS.LCSLID AND R.ZBBLBZ='Y';
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_**MX解除ZBBLBZ！' || LN_I);
      COMMIT;
    END IF;

    --ZYTSBZ
    --20260728加数据同步时间条件，期望可以用到索引
    UPDATE CKTS_SB_MTS_JHMX T
       SET T.MTSBZ='Y'
     WHERE T.SJTB_SJ>=LD_DEALDATA AND T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID AND A.CKTMSHWYSFWLX_DM='1');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_JHMX设置MTSBZ(ALL=N)！');
      COMMIT;
    END IF;
    UPDATE CKTS_SB_MTS_CKMX T
       SET T.MTSBZ='Y'
     WHERE T.SJTB_SJ>=LD_DEALDATA AND T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID AND A.CKTMSHWYSFWLX_DM='1');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_CKMX设置MTSBZ(ALL=N)！');
      COMMIT;
    END IF;

    --免退税FSRQ处理
    FOR LCXX_FH IN (SELECT T.LCSLID, MIN(S.FSRQ) AS FSRQ
                      FROM CKTS_SB_MTS_CKMX T
                     INNER JOIN CKTS_LC_YWHZXX S ON S.LCSLID_FS=T.LCSLID
                     WHERE T.FSRQ IS NULL
                     GROUP BY T.LCSLID)
    LOOP
      BEGIN
        UPDATE CKTS_SB_MTS_CKMX T
           SET T.FSRQ=LCXX_FH.FSRQ
         WHERE LCSLID=LCXX_FH.LCSLID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_CKMX设置FSRQ！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MTS_JHMX, CKTS_SB_MTS_CKMX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_JHMX, CKTS_SB_MTS_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_MTS_YSFW
  BEGIN
    --设置LCSLID_SB
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_MTS_YSFW T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0301001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_MTS_YSFW设置LCSLID_SB！');
      COMMIT;
    END IF;
    --BYTSBZ：明确
    --ZBBLBZ：待定
    --ZYTSBZ
    UPDATE CKTS_SB_MTS_YSFW T
       SET T.MTSBZ='Y'
     WHERE T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID AND A.CKTMSHWYSFWLX_DM='2');
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_MTS_YSFW数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_MTS_YSFW数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_SB_WZF_CKMX
  BEGIN
    --删除作废流程信息
    LN_I:=0;
    FOR CUR_MTS IN (SELECT LCSLID_SB FROM CKTS_LC_SBXX WHERE ZFBZ='Y' AND SBYWB_DM='A0310001' AND NVL(ZFRQ,QDSJ)>=LD_DEALDATA)
    LOOP
      BEGIN
        DELETE FROM CKTS_SB_WZF_CKMX T WHERE T.LCSLID=CUR_MTS.LCSLID_SB;
        COMMIT;
        LN_I :=LN_I+1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_WZF_CKMX删除作废流程信息！' || LN_I);
      COMMIT;
    END IF;
    --设置LCSLID_SB
    --按税局、企业、业务、所属期、批次查找申报流程
    UPDATE CKTS_SB_WZF_CKMX T
       SET T.LCSLID_SB=NVL((SELECT A.LCSLID_SB
                              FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM='A0310001' AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_WZF_CKMX设置LCSLID_SB！');
      COMMIT;
    END IF;
    --BYTSBZ：明确
    --ZBBLBZ：待定
    --ZYTSBZ

    --代办退税FSRQ处理
    FOR LCXX_FH IN (SELECT T.LCSLID, MIN(S.FSRQ) AS FSRQ
                      FROM CKTS_SB_WZF_CKMX T
                     INNER JOIN CKTS_LC_YWHZXX S ON S.LCSLID_FS=T.LCSLID
                     WHERE T.FSRQ IS NULL
                     GROUP BY T.LCSLID)
    LOOP
      BEGIN
        UPDATE CKTS_SB_WZF_CKMX T
           SET T.FSRQ=LCXX_FH.FSRQ
         WHERE LCSLID=LCXX_FH.LCSLID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_SB_WZF_CKMX设置FSRQ！');
      COMMIT;
    END IF;

    UPDATE CKTS_SB_WZF_CKMX T
       SET T.MTSBZ='Y'
     WHERE T.MTSBZ ='N' AND T.BYTSBZ='N' AND T.BYBLBZ='N' AND T.ZBBLBZ='N'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID);
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_SB_WZF_CKMX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_SB_WZF_CKMX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SBXX（CKQYGLLB_DM、SB_XSEMY,SB_XSERMB,SB_MDTSE,SB_ZZSTSE,SB_XFSTSE,SB_MDSE）
  BEGIN
    --设置分类管理等级（注：还有一部分申报数据在总局分类管理政策之前申报的，已按最接近年份设置分类管理类别，当前无分类的默认C）
    UPDATE CKTS_LC_SBXX T
       SET T.CKQYGLLB_DM=
           (SELECT KZXX
              FROM TL_BJTS.GS_DJ_CKTMSDAB A, TL_BJTS.GS_DJ_CKTMSDAB_KZ B
             WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=TO_CHAR(T.DJXH) AND B.KZLX='FLGLCD' AND T.XGRQ BETWEEN B.ST_DATE AND B.END_DATE
               AND ROWNUM=1)
     WHERE T.CKQYGLLB_DM IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置CKQYGLLB_DM！');
      COMMIT;
    END IF;

    --缺免抵退业务申报信息，该部分新增从免抵退汇总表获取

    --免退税业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX T
       SET T.SB_XSEMY =(SELECT SUM(A.MYLAJ)
                          FROM CKTS_SB_MTS_CKMX A
                         WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0301001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    UPDATE CKTS_LC_SBXX T
       SET (T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE) =
           (SELECT SUM(CASE WHEN A.SZ='V' THEN A.JSJE ELSE 0 END), SUM(A.TSE),
                   SUM(CASE WHEN A.SZ='V' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.SZ='C' THEN A.TSE ELSE 0 END), 0
              FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0301001' AND T.SB_XSERMB IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(A0301001)！');
      COMMIT;
    END IF;

    --外综服业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE) =
           (SELECT SUM(A.MYLAJ),SUM(A.JSJE),SUM(A.TSE),SUM(A.TSE),0,0
              FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID_SB=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0310001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(A0310001)！');
      COMMIT;
    END IF;

    --非自产业务申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE) =
           (SELECT 0,SUM(A.JSJE),SUM(A.XFSTSE),0,SUM(A.XFSTSE),0
              FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0302001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    --旧设备申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE) =
           (SELECT 0,SUM(A.SBZYJZ),SUM(A.TSE),SUM(A.TSE),0,0
              FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0303001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    --购进自用申报信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SBXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE) =
           (SELECT 0,SUM(A.JSJE),SUM(A.TSE),SUM(A.TSE),0,0
              FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID_SB)
     WHERE T.SBYWB_DM='A0304001' AND T.SB_XSEMY IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SBXX设置SB_XSEMY(特殊业务)！');
      COMMIT;
    END IF;

    --部分免退税业务含跨境应税行为，需要两边合计
    FOR CUR_MTSYSFW IN (SELECT LCSLID_SB, SUM(SKJEMY) AS MYLAJ, SUM(BQQRYSFWYYSRRMBJE) AS RMBLAJ,SUM(ZZSTSE) AS ZZSTSE FROM CKTS_SB_MTS_YSFW GROUP BY LCSLID_SB)
    LOOP
      BEGIN
        UPDATE CKTS_LC_SBXX T
           SET T.SB_XSEMY = CUR_MTSYSFW.MYLAJ + (SELECT NVL(SUM(A.MYLAJ),0) FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB),
               T.SB_XSERMB = CUR_MTSYSFW.RMBLAJ + (SELECT NVL(SUM(A.JSJE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB AND A.SZ='V'),
               T.SB_MDTSE = CUR_MTSYSFW.ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB),
               T.SB_ZZSTSE = CUR_MTSYSFW.ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB AND A.SZ='V'),
               T.SB_XFSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB AND A.SZ='C'),
               T.SB_MDSE = 0
         WHERE T.LCSLID_SB=CUR_MTSYSFW.LCSLID_SB;
        COMMIT;
      END;
    END LOOP;

    UPDATE CKTS_LC_SBXX T
       SET T.SB_MDTSE=T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE
     WHERE T.ZFBZ IS NULL AND T.SB_MDTSE<>T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SBXX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SBXX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SHXX数据处理（LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC）
  BEGIN
    --清除作废流程
    INSERT INTO CKTS_LC_SHXX_ZF
         SELECT * FROM CKTS_LC_SHXX T WHERE T.ZFBZ='Y' AND NVL(T.FFBZ,'N')<>'Y';
    COMMIT;
    DELETE FROM CKTS_LC_SHXX T WHERE T.ZFBZ='Y' AND NVL(T.FFBZ,'N')<>'Y';
    COMMIT;
    DELETE FROM CKTS_LC_YWHZXX T WHERE T.LCSLID_FS IN (SELECT S.LCSLID_FS FROM CKTS_LC_SHXX_ZF S);
    COMMIT;
    DELETE FROM CKTS_LC_SEHZXX T WHERE T.LCSLID_FS IN (SELECT S.LCSLID_FS FROM CKTS_LC_SHXX_ZF S);
    COMMIT;
    DELETE FROM CKTS_LC_SHXX T WHERE (T.LCSLID_SB,T.LCSLID,T.QDSJ) IN
           (SELECT S.LCSLID_SB,S.LCSLID,MAX(S.QDSJ) FROM CKTS_LC_SHXX S WHERE S.LCSWSX_DM IN ('LCSXA081038005','LCSXA081039005') GROUP BY S.LCSLID_SB,S.LCSLID HAVING COUNT(1)>1);
    COMMIT;
    DELETE FROM CKTS_LC_SHXX_ZF T WHERE EXISTS (SELECT 1 FROM CKTS_LC_SHXX_ZF S WHERE S.UUID=T.UUID AND S.ROWID<T.ROWID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX删除作废流程！');
      COMMIT;
    END IF;

    --审核信息lcslid_sb、lcslid_fs设置
    --设置LCSLID_SB
    --T.LCSWSX_DM='LCSXA081038005'发放以后，免抵退出口明细表中对应调查评估的lcslid会发生变化，是一个新的在业务流程表中不存在的数据，需要通过语句补偿
    DELETE FROM CKTS_LC_SHXX T WHERE T.SBYWB_DM='A0305001' AND T.LCSLID<>T.LCSLID_SB AND T.SJTB_BZ='9' AND T.LCJSRQ>SYSDATE;
    COMMIT;
    INSERT INTO CKTS_LC_SHXX (UUID,CKTMSHWYSFWLX_DM,LCTJJC,TSSWJG_DM,DJXH,CKQYGLLB_DM,WZHBZ,SBYWB_DM,SSQ,SBPC,LCSLID,LCSLID_SB,LCSLID_FS,QDR_DM,QDSJ,LCJSRQ,XGRQ,SJTB_SJ,SJTB_BZ,ZLCLCSLID,LCSWSX_DM)
    SELECT TT.UUID,A.CKTMSHWYSFWLX_DM,'00',A.TSSWJG_DM,A.DJXH,A.CKQYGLLB_DM,A.WZHBZ,A.SBYWB_DM,A.SSQ,A.SBPC,TT.LCSLID,TT.LCSLID_SB,TT.LCSLID_FS,A.QDR_DM,A.QDSJ,TO_DATE('2100-12-31','YYYY-MM-DD'),A.XGRQ,SYSDATE,'9',A.ZLCLCSLID,A.LCSWSX_DM
      FROM CKTS_LC_SHXX A
     INNER JOIN (SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID
                   FROM (SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_CKMX B
                          WHERE B.LCSLID<>B.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=B.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                          UNION ALL
                         SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_GJYS C
                          WHERE C.LCSLID<>C.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=C.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                          UNION ALL
                         SELECT LCSLID,LCSLID_SB,LCSLID_FS,MIN(UUID) AS UUID FROM CKTS_SB_MDT_YFSJ D
                          WHERE D.LCSLID<>D.LCSLID_SB AND NOT EXISTS(SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID=D.LCSLID)
                          GROUP BY LCSLID,LCSLID_SB,LCSLID_FS ) T
                  GROUP BY LCSLID,LCSLID_SB,LCSLID_FS
                ) TT ON TT.LCSLID_SB=A.LCSLID;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(A0305001分流信息)！');
      COMMIT;
    END IF;

    --设置LCSLID_SB
    --特殊政策退税不分流，申报流程等于当前流程，
    UPDATE CKTS_LC_SHXX T
       SET T.LCSLID_SB = T.LCSLID
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
    COMMIT;
    --免抵退业务分流程在前一步刷新时申报流程非空，其他主流程申报流程等于当前流程
    UPDATE CKTS_LC_SHXX T
       SET LCSLID_SB = NVL((SELECT A.LCSLID_SB FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM=T.SBYWB_DM AND A.SSQ=T.SSQ AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM = 'A0305001';
    COMMIT;
    --免退税、代办退税按当前流程到对应明细表中找申报流程（必须有明细数据）
    UPDATE CKTS_LC_SHXX T
       SET LCSLID_SB = NVL((SELECT A.LCSLID_SB FROM CKTS_LC_SBXX A
                             WHERE A.DJXH=T.DJXH AND A.SBYWB_DM=T.SBYWB_DM AND A.SSQ=T.SSQ AND A.SBPC=T.SBPC AND A.ZFBZ IS NULL
                               AND A.SJTB_BZ='2'
                               AND ROWNUM=1),' ')
     WHERE T.LCSLID_SB=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0301001','A0310001');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCSLID_SB)！');
      COMMIT;
    END IF;

    --设置LCSLID_FS
    --非免抵退税业务，复审流程等于当前流程
    UPDATE CKTS_LC_SHXX T
       SET T.LCSLID_FS = T.LCSLID
     WHERE T.LCJSRQ>=LD_DEALDATA AND T.LCSLID_FS=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM IN ('A0301001','A0302001','A0303001','A0304001','A0310001')
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    --免抵退主流程，复审流程等于当前流程
    --免抵退分流程，不用处理
    UPDATE CKTS_LC_SHXX T
       SET T.LCSLID_FS = T.LCSLID
     WHERE T.LCJSRQ>=LD_DEALDATA AND T.LCSLID_FS=' ' AND T.ZFBZ IS NULL
       AND T.SBYWB_DM='A0305001' AND T.LCSLID=T.LCSLID_SB
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCSLID_FS)！');
      COMMIT;
    END IF;

    --设置分类管理等级（注：还有一部分申报数据在总局分类管理政策之前申报的，已按最接近年份设置分类管理类别，当前无分类的默认C）
    UPDATE CKTS_LC_SHXX T
       SET T.CKQYGLLB_DM=(SELECT KZXX
                            FROM TL_BJTS.GS_DJ_CKTMSDAB A, TL_BJTS.GS_DJ_CKTMSDAB_KZ B
                           WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=TO_CHAR(T.DJXH) AND B.KZLX='FLGLCD' AND T.QDSJ BETWEEN B.ST_DATE AND B.END_DATE
                             AND ROWNUM=1)
     WHERE T.CKQYGLLB_DM IS NULL AND T.ZFBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(CKQYGLLB_DM)！');
      COMMIT;
    END IF;

    --LCTJJC
    --35号公告代办退税
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='72'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0310001';
    COMMIT;
    --17号公告代办退税
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='71'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.CKTMSYWLXDMJH LIKE 'WMZHFW%');
    COMMIT;
    --综服企业自营业务
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='70'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.BAJC_YEAR LIKE '7%');
    COMMIT;
    --国际运输业务
    --外商投资企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='63'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    --委托出口企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='62'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    --内资生产企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='61'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    --研发设计业务
    --外商投资企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='53'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    --委托出口企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='52'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    --内资生产企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='51'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
    COMMIT;
    --其他服务贸易
    --外商投资企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='43'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    --委托出口企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='42'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    --内资生产企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='41'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    --外贸服务贸易
    --研发设计业务
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='50'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
    COMMIT;
    --其他服务贸易
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='40'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB);
    COMMIT;
    --周边业务
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='30'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
    COMMIT;
    --外商投资企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='23'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    --委托出口企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='22'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    --内资生产企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='21'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' ';
    COMMIT;
    --外贸企业
    UPDATE CKTS_LC_SHXX T
       SET T.LCTJJC='10'
     WHERE T.LCTJJC='00' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' ';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(LCTJJC)！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据,LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据,LCSLID_SB、LCSLID_FS、CKQYGLLB_DM、LCTJJC,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SEHZXX数据处理（GKBL_、XHRQ_、SNCKZB）
  BEGIN
    --CKTMSJHSSSWJGDM、MDTKSSSWJGDM补充
    UPDATE CKTS_LC_SEHZXX T
       SET T.CKTMSJHSSSWJGDM=T.TSSWJG_DM
     WHERE T.CKTMSJHSSSWJGDM IS NULL;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX T
       SET T.MDTKSSSWJGDM=T.TSSWJG_DM
     WHERE T.MDTKSSSWJGDM IS NULL;
    COMMIT;
    --税额核准数为0的情况更新
    UPDATE CKTS_LC_SEHZXX T
       SET T.GKBL_ZZSTSE=0, T.XHRQ_TK =T.SEHZRQ, T.KPRQ=T.SEHZRQ
     WHERE T.GKBL_ZZSTSE IS NULL AND T.SEHZ_ZZSTSE=0;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX T
       SET T.GKBL_XFSTSE=0, T.XHRQ_XFS =T.SEHZRQ
     WHERE T.GKBL_XFSTSE IS NULL AND T.SEHZ_XFSTSE=0;
    COMMIT;
    UPDATE CKTS_LC_SEHZXX T
       SET T.GKBL_MDSE=0, T.XHRQ_MD =T.SEHZRQ
     WHERE T.GKBL_MDSE IS NULL AND T.SEHZ_MDSE=0;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_(SEHZ_=0)！');
      COMMIT;
    END IF;

    --根据收核回推至LD_DEALDATA免抵调数据，更新税额核准表办理数
    FOR CUR_TKXX IN (SELECT R.UUID,R.SEHZ_MDSE,LEAST(R.SEHZ_MDSE,S.MD_AMT,T.JE) AS GKBL_MDSE, T.XHRQ_1, NVL(T.HSSWJG_DM,R.CKTMSJHSSSWJGDM) AS MDTKSSSWJGDM
                       FROM CKTS_ZS_TKGZ T
                      INNER JOIN CKTS_ZS_MDTKB S ON S.DJXH=T.DJXH AND S.CKTS_NO=T.BTKGZUUID AND S.KJTKBJ='Y'
                      INNER JOIN CKTS_LC_SEHZXX R ON R.DJXH=T.DJXH AND NVL(R.GZTKTZSBH,R.YWHZBID||R.XH)=S.CKTS_NO AND R.XHRQ_MD>SYSDATE
                      WHERE T.XHRQ_1>=LD_DEALDATA AND T.TZSLY='3' AND T.TZLX_DM='1' AND T.GZBZ='Y' AND T.ZFRQ_1 IS NULL
                        AND T.JE>0
                        AND NOT EXISTS (SELECT 1
                                          FROM CKTS_LC_SEHZXX Q
                                         WHERE Q.DJXH=T.DJXH
                                           AND NVL(Q.GZTKTZSBH,Q.YWHZBID||Q.XH)=S.CKTS_NO
                                           AND Q.XHRQ_MD=T.XHRQ_1))
    LOOP
      BEGIN
        IF CUR_TKXX.SEHZ_MDSE<=CUR_TKXX.GKBL_MDSE THEN
          UPDATE CKTS_LC_SEHZXX T
             SET T.GKBL_MDSE = CUR_TKXX.GKBL_MDSE,
                 T.XHRQ_MD = CUR_TKXX.XHRQ_1,
                 T.MDTKSSSWJGDM = CUR_TKXX.MDTKSSSWJGDM
           WHERE T.UUID=CUR_TKXX.UUID;
          COMMIT;
        ELSE
          INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                      SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                      GZTKTZSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                      SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                      GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
               SELECT 'YANGUOPINGXTYW'||TO_CHAR(SYSDATE,'YYYYMMDD')||TO_CHAR(SEQ_DEAL_TKGZ.NEXTVAL),
                      LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                      SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                      GZTKTZSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                      CUR_TKXX.SEHZ_MDSE-CUR_TKXX.GKBL_MDSE,0,0,CUR_TKXX.SEHZ_MDSE-CUR_TKXX.GKBL_MDSE,
                      0,0,0,0
                 FROM CKTS_LC_SEHZXX
                WHERE UUID=CUR_TKXX.UUID;
          UPDATE CKTS_LC_SEHZXX T
             SET T.SEHZ_MDTSE = T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE + CUR_TKXX.GKBL_MDSE,
                 T.SEHZ_MDSE = CUR_TKXX.GKBL_MDSE,
                 T.GKBL_MDSE = CUR_TKXX.GKBL_MDSE,
                 T.XHRQ_MD = CUR_TKXX.XHRQ_1,
                 T.MDTKSSSWJGDM = CUR_TKXX.MDTKSSSWJGDM
           WHERE T.UUID=CUR_TKXX.UUID;
          COMMIT;
        END IF;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_MDSE(SEHZ_<>0)！');
      COMMIT;
    END IF;

    --根据收核回推至LD_DEALDATA增值税退库数据，更新税额核准表办理数
    --KPRQ
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND S.KPRQ>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTUUID AND T.XHRQ_TK>SYSDATE)
    LOOP
      BEGIN
        IF CUR_TKXX.THRQ_1 IS NOT NULL THEN
          UPDATE CKTS_LC_SEHZXX T
             SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
                 T.XHRQ_TK = CUR_TKXX.THRQ_1,
                 T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
           WHERE T.UUID=CUR_TKXX.UUID;
        ELSE
          UPDATE CKTS_LC_SEHZXX T
             SET T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
           WHERE T.UUID=CUR_TKXX.UUID;
        END IF;
        COMMIT;
      END;
    END LOOP;
    --THRQ_1
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTUUID AND T.XHRQ_TK>SYSDATE)
    LOOP
      BEGIN
        UPDATE CKTS_LC_SEHZXX T
           SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
               T.XHRQ_TK = CUR_TKXX.THRQ_1,
               T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
         WHERE T.UUID=CUR_TKXX.UUID;
        COMMIT;
      END;
    END LOOP;
    --KPRQ
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND S.KPRQ>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_TK>SYSDATE)
    LOOP
      BEGIN
        IF CUR_TKXX.THRQ_1 IS NOT NULL THEN
          UPDATE CKTS_LC_SEHZXX T
             SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
                 T.XHRQ_TK = CUR_TKXX.THRQ_1,
                 T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
           WHERE T.UUID=CUR_TKXX.UUID;
        ELSE
          UPDATE CKTS_LC_SEHZXX T
             SET T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
           WHERE T.UUID=CUR_TKXX.UUID;
        END IF;
        COMMIT;
      END;
    END LOOP;
    --THRQ_1
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.ZZSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_TK>SYSDATE)
    LOOP
      BEGIN
        UPDATE CKTS_LC_SEHZXX T
           SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
               T.XHRQ_TK = CUR_TKXX.THRQ_1,
               T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
         WHERE T.UUID=CUR_TKXX.UUID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_ZZSTSE(SEHZ_>0)！');
      COMMIT;
    END IF;
    --增值税审核数为负处理
    FOR CUR_TKXX IN (SELECT T.UUID,T.DJXH,T.ZZSSSSRTHSBH,T.SEHZ_ZZSTSE FROM CKTS_LC_SEHZXX T
                      WHERE T.SEHZ_ZZSTSE<0 AND T.XHRQ_TK>SYSDATE AND T.ZZSSSSRTHSBH IS NOT NULL)
    LOOP
      BEGIN
        -- 检查是否正负对冲及对冲后剩余税额
        SELECT SUM(T.SEHZ_ZZSTSE),SUM(NVL(T.GKBL_ZZSTSE,0))
          INTO LN_ZZS,SN_ZZS
          FROM CKTS_LC_SEHZXX T
         WHERE T.DJXH=CUR_TKXX.DJXH AND T.ZZSSSSRTHSBH=CUR_TKXX.ZZSSSSRTHSBH;
        IF LN_ZZS=0 THEN
          --对冲后为0
          UPDATE CKTS_LC_SEHZXX T
             SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
                 T.KPRQ = T.SEHZRQ,
                 T.XHRQ_TK = T.SEHZRQ
           WHERE T.DJXH=CUR_TKXX.DJXH AND T.ZZSSSSRTHSBH=CUR_TKXX.ZZSSSSRTHSBH;
          COMMIT;
        ELSIF LN_ZZS<0 THEN
          --对冲后为负数，需要返纳，考虑用户分次返纳的情况
          BEGIN
            SELECT COUNT(1),SUM(S.SJJE),MAX(S.KJRQ),MAX(S.RKRQ)
              INTO LN_I, SY_ZZS, V_TSKP_DATE,V_TSTK_DATE
              FROM TL_ADMIN.FG_CKTSFN_HXZG S
             WHERE S.DJXH=CUR_TKXX.DJXH AND S.YZPZXH_CKTS=CUR_TKXX.ZZSSSSRTHSBH AND S.RKRQ IS NOT NULL;
            IF LN_I>0 THEN
              --存在返纳入库记录的时候判断
              IF SY_ZZS+LN_ZZS=0 THEN
                --返纳数+税额核准数=0，表示对应退还书已全部返纳
                UPDATE CKTS_LC_SEHZXX T
                   SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_TK = V_TSTK_DATE
                 WHERE T.DJXH=CUR_TKXX.DJXH AND T.ZZSSSSRTHSBH=CUR_TKXX.ZZSSSSRTHSBH
                   AND T.XHRQ_TK>SYSDATE;
                COMMIT;
              ELSIF SY_ZZS+SN_ZZS+CUR_TKXX.SEHZ_ZZSTSE>=0 THEN
                --返纳数+已办理数+当前未销号记录核准数>=0，表示对应未销号记录已全部返纳
                UPDATE CKTS_LC_SEHZXX T
                   SET T.GKBL_ZZSTSE=T.SEHZ_ZZSTSE,
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_TK = V_TSTK_DATE
                 WHERE T.UUID=CUR_TKXX.UUID;
                COMMIT;
              ELSIF SY_ZZS+SN_ZZS>0 THEN
                --返纳数+已办理数>0，表示对应未销号记录可部分返纳，按（SY_ZZS+SN_ZZS）拆分已返纳部分
                INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            ZZSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                            GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
                     SELECT 'YANGUOPINGXTYW'||TO_CHAR(SYSDATE,'YYYYMMDD')||TO_CHAR(SEQ_DEAL_TKGZ.NEXTVAL),
                            LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            ZZSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            (SY_ZZS+SN_ZZS)+CUR_TKXX.SEHZ_ZZSTSE,(SY_ZZS+SN_ZZS)+CUR_TKXX.SEHZ_ZZSTSE,0,0,
                            0,0,0,0
                       FROM CKTS_LC_SEHZXX
                      WHERE UUID=CUR_TKXX.UUID;
                UPDATE CKTS_LC_SEHZXX T
                   SET T.SEHZ_MDTSE = 0 - (SY_ZZS+SN_ZZS) + T.SEHZ_XFSTSE + T.SEHZ_MDSE,
                       T.SEHZ_ZZSTSE = 0 - (SY_ZZS+SN_ZZS),
                       T.GKBL_ZZSTSE = 0 - (SY_ZZS+SN_ZZS),
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_TK = V_TSTK_DATE
                 WHERE T.UUID=CUR_TKXX.UUID;
                COMMIT;
              END IF;
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              CONTINUE;
          END;
        END IF;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_ZZSTSE(SEHZ_<0)(对冲/返纳)！');
      COMMIT;
    END IF;

    --根据收核回推两天消费税退库数据，更新税额核准表办理数
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))='SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.XFSSSSRTHSBH=S.YDTUUID AND T.XHRQ_XFS>SYSDATE)
    LOOP
      BEGIN
        UPDATE TL_TSSH.CKTS_LC_SEHZXX T
           SET T.GKBL_XFSTSE=T.SEHZ_XFSTSE,
               T.XHRQ_XFS = CUR_TKXX.THRQ_1,
               T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
         WHERE T.UUID=CUR_TKXX.UUID;
        COMMIT;
      END;
    END LOOP;
    FOR CUR_TKXX IN (SELECT T.UUID,S.KPRQ,S.THRQ_1 FROM CKTS_ZS_SRTHS S, CKTS_LC_SEHZXX T
                      WHERE UPPER(TRIM(T.LRR_DM))<>'SJQY' AND GREATEST(S.THRQ_1,S.XHRQ_1)>=LD_DEALDATA AND S.TZLX_DM IN ('1','4') AND T.DJXH=S.DJXH AND T.XFSSSSRTHSBH=S.YDTLYUUID AND T.XHRQ_XFS>SYSDATE)
    LOOP
      BEGIN
        UPDATE CKTS_LC_SEHZXX T
           SET T.GKBL_XFSTSE=T.SEHZ_XFSTSE,
               T.XHRQ_XFS = CUR_TKXX.THRQ_1,
               T.KPRQ = GREATEST(CUR_TKXX.KPRQ,T.SEHZRQ)
         WHERE T.UUID=CUR_TKXX.UUID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_XFSTSE(SEHZ_<>0)！');
      COMMIT;
    END IF;
    --消费税审核数为负处理
    FOR CUR_TKXX IN (SELECT T.UUID,T.DJXH,T.XFSSSSRTHSBH,T.SEHZ_XFSTSE FROM CKTS_LC_SEHZXX T
                     WHERE T.SEHZ_XFSTSE<0 AND T.XHRQ_XFS>SYSDATE AND T.XFSSSSRTHSBH IS NOT NULL)
    LOOP
      BEGIN
        -- 检查是否正负对冲及对冲后剩余税额
        SELECT SUM(T.SEHZ_XFSTSE),SUM(NVL(T.GKBL_XFSTSE,0))
          INTO LN_XFS,SN_XFS
          FROM CKTS_LC_SEHZXX T
         WHERE T.DJXH=CUR_TKXX.DJXH AND T.XFSSSSRTHSBH=CUR_TKXX.XFSSSSRTHSBH;
        IF LN_XFS=0 THEN
          --对冲后为0
          UPDATE CKTS_LC_SEHZXX T
             SET T.GKBL_XFSTSE=T.SEHZ_XFSTSE,
                 T.KPRQ = T.SEHZRQ,
                 T.XHRQ_XFS = T.SEHZRQ
           WHERE T.DJXH=CUR_TKXX.DJXH AND T.XFSSSSRTHSBH=CUR_TKXX.XFSSSSRTHSBH;
          COMMIT;
        ELSIF LN_XFS<0 THEN
          --对冲后为负数，需要返纳，考虑用户分次返纳的情况
          BEGIN
            SELECT COUNT(1),SUM(S.SJJE),MAX(S.KJRQ),MAX(S.RKRQ)
              INTO LN_I, SY_XFS, V_TSKP_DATE,V_TSTK_DATE
              FROM TL_ADMIN.FG_CKTSFN_HXZG S
             WHERE S.DJXH=CUR_TKXX.DJXH AND S.YZPZXH_CKTS=CUR_TKXX.XFSSSSRTHSBH AND S.RKRQ IS NOT NULL;
            IF LN_I>0 THEN
              --存在返纳入库记录的时候判断
              IF SY_XFS+LN_XFS=0 THEN
                --返纳数+税额核准数=0，表示对应退还书已全部返纳
                UPDATE CKTS_LC_SEHZXX T
                   SET T.GKBL_XFSTSE=T.SEHZ_XFSTSE,
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_XFS = V_TSTK_DATE
                 WHERE T.DJXH=CUR_TKXX.DJXH AND T.XFSSSSRTHSBH=CUR_TKXX.XFSSSSRTHSBH
                   AND T.XHRQ_XFS>SYSDATE;
                COMMIT;
              ELSIF SY_XFS+SN_XFS+CUR_TKXX.SEHZ_XFSTSE>=0 THEN
                --返纳数+已办理数+当前未销号记录核准数>=0，表示对应未销号记录已全部返纳
                UPDATE CKTS_LC_SEHZXX T
                   SET T.GKBL_XFSTSE=T.SEHZ_XFSTSE,
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_XFS = V_TSTK_DATE
                 WHERE T.UUID=CUR_TKXX.UUID;
                COMMIT;
              ELSIF SY_XFS+SN_XFS>0 THEN
                --返纳数+已办理数>0，表示对应未销号记录可部分返纳，按（SY_XFS+SN_XFS）拆分已返纳部分
                INSERT INTO CKTS_LC_SEHZXX(UUID,LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            XFSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            SEHZ_MDTSE,SEHZ_ZZSTSE,SEHZ_XFSTSE,SEHZ_MDSE,
                            GKBL_MDTSE,GKBL_ZZSTSE,GKBL_XFSTSE,GKBL_MDSE)
                     SELECT 'YANGUOPINGXTYW'||TO_CHAR(SYSDATE,'YYYYMMDD')||TO_CHAR(SEQ_DEAL_TKGZ.NEXTVAL),
                            LCSLID_FS,TSSWJG_DM,DJXH,YWHZBUUID,YWHZBID,XH,SEHZR_DM,SEHZRQ,LRR_DM,
                            SJTB_SJ,XGRQ,SJTB_BZ,SBYWB_DM,SSQ,SBPC,CKQYGLLB_DM,WZHBZ,LCTJJC,CKTMSHWYSFWLX_DM,SNCKZB,
                            XFSSSSRTHSBH,CKTMSJHSSSWJGDM,MDTKSSSWJGDM,KPRQ,XHRQ_TK,XHRQ_MD,XHRQ_XFS,
                            (SY_XFS+SN_XFS)+CUR_TKXX.SEHZ_XFSTSE,0,(SY_XFS+SN_XFS)+CUR_TKXX.SEHZ_XFSTSE,0,
                            0,0,0,0
                       FROM CKTS_LC_SEHZXX
                      WHERE UUID=CUR_TKXX.UUID;
                UPDATE CKTS_LC_SEHZXX T
                   SET T.SEHZ_MDTSE = 0 - (SY_XFS+SN_XFS) + T.SEHZ_ZZSTSE + T.SEHZ_MDSE,
                       T.SEHZ_XFSTSE = 0 - (SY_XFS+SN_XFS),
                       T.GKBL_XFSTSE = 0 - (SY_XFS+SN_XFS),
                       T.KPRQ = V_TSKP_DATE,
                       T.XHRQ_XFS = V_TSTK_DATE
                 WHERE T.UUID=CUR_TKXX.UUID;
                COMMIT;
              END IF;
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              CONTINUE;
          END;
        END IF;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_XFSTSE(SEHZ_<0)(对冲/返纳)！');
      COMMIT;
    END IF;

    UPDATE TL_TSSH.CKTS_LC_SEHZXX T
       SET T.GKBL_MDTSE=NVL(T.GKBL_ZZSTSE,0)+NVL(T.GKBL_XFSTSE,0)+NVL(T.GKBL_MDSE,0)
     WHERE GREATEST(T.XHRQ_TK,T.XHRQ_MD,T.XHRQ_XFS)>=LD_DEALDATA;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX.GKBL_MDTSE=GKBL_ZZSTSE+GKBL_XFSTSE+GKBL_MDSE！');
      COMMIT;
    END IF;

    --部分税局征管与退税需要调整对应关系
    UPDATE TL_TSSH.CKTS_LC_SEHZXX T SET T.CKTMSJHSSSWJGDM='13311930000' WHERE T.CKTMSJHSSSWJGDM='13311910000';
    COMMIT;
    UPDATE TL_TSSH.CKTS_LC_SEHZXX T SET T.MDTKSSSWJGDM='13311930000' WHERE T.MDTKSSSWJGDM='13311910000';
    COMMIT;
    UPDATE TL_ADMIN.FG_CKTSFN_HXZG T SET T.SKSSSWJG_DM='13311930000' WHERE T.SKSSSWJG_DM='13311910000';
    COMMIT;
    UPDATE TL_TSSH.CKTS_LC_SEHZXX T SET T.CKTMSJHSSSWJGDM='13307030000' WHERE T.CKTMSJHSSSWJGDM='13307920000';
    COMMIT;
    UPDATE TL_TSSH.CKTS_LC_SEHZXX T SET T.MDTKSSSWJGDM='13307030000' WHERE T.MDTKSSSWJGDM='13307920000';
    COMMIT;
    UPDATE TL_ADMIN.FG_CKTSFN_HXZG T SET T.SKSSSWJG_DM='13307030000' WHERE T.SKSSSWJG_DM='13307920000';
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX（丽水二分局, 金华金义局）！');
      COMMIT;
    END IF;

    --设置上年出口占比
    UPDATE CKTS_LC_SEHZXX T
       SET SSQ='200001'
     WHERE T.SSQ IS NULL;
    COMMIT;
    --非免抵退业务，按所属期确定上年与本年（非0即1）
    UPDATE CKTS_LC_SEHZXX T
       SET SNCKZB=(CASE WHEN T.SSQ<(TO_CHAR(T.SEHZRQ,'YYYY')||'01') THEN 1 ELSE 0 END)
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM<>'A0305001';
    COMMIT;
    --免抵退上年申报数据（1）
    UPDATE CKTS_LC_SEHZXX T
       SET SNCKZB=1
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ<(TO_CHAR(T.SEHZRQ,'YYYY')||'01');
    COMMIT;
    --免抵退本年服务贸易（0）
    UPDATE CKTS_LC_SEHZXX T
       SET SNCKZB=0
     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ>=(TO_CHAR(T.SEHZRQ,'YYYY')||'01') AND T.CKTMSHWYSFWLX_DM='2';
    COMMIT;
    --免抵退本年申报业务，区分
    FOR CUR_MDT IN (SELECT T.UUID, T.LCSLID_FS, T.SEHZRQ FROM CKTS_LC_SEHZXX T
                     WHERE T.SNCKZB IS NULL AND T.SBYWB_DM='A0305001' AND T.SSQ>=(TO_CHAR(T.SEHZRQ,'YYYY')||'01') AND T.CKTMSHWYSFWLX_DM='1')
    LOOP
      BEGIN
        SELECT NVL(SUM(A.MDTSE),0)
          INTO LN_ALLCK
          FROM CKTS_SB_MDT_CKMX A
         WHERE A.LCSLID_FS=CUR_MDT.LCSLID_FS;
        SELECT NVL(SUM(A.MDTSE),0)
          INTO LN_SNCK
          FROM CKTS_SB_MDT_CKMX A
         WHERE A.LCSLID_FS=CUR_MDT.LCSLID_FS
           AND A.CKRQ_1<TRUNC(CUR_MDT.SEHZRQ,'YY');
        UPDATE CKTS_LC_SEHZXX T
           SET SNCKZB=(CASE WHEN LN_SNCK<=0 THEN 0 ELSE (CASE WHEN LN_ALLCK<=LN_SNCK THEN 1 ELSE LN_SNCK / LN_ALLCK END) END)
         WHERE T.UUID=CUR_MDT.UUID;
        COMMIT;
      END;
    END LOOP;
    --以前年度税额核准，结转到本年未结束流程
    UPDATE CKTS_LC_SEHZXX T
       SET SNCKZB=1
     WHERE T.SNCKZB<>1 AND T.SEHZRQ<TRUNC(ADD_MONTHS(SYSDATE,-1),'YY') AND GREATEST(T.XHRQ_TK,T.XHRQ_MD,T.XHRQ_XFS)>=TRUNC(ADD_MONTHS(SYSDATE,-1),'YY');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SEHZXX(SNCKZB)！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SEHZXX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SEHZXX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_YWHZXX数据处理（FSRQ、YWHZWCBZ、SEHZWCBZ、CKQYGLLB_DM、WZHBZ、LCTJJC）
  BEGIN
    UPDATE CKTS_LC_YWHZXX T
       SET T.SSQ='200001'
     WHERE T.SSQ IS NULL;
    COMMIT;
    --YWHZWCBZ，用于省局报表统计可调库资源
    UPDATE CKTS_LC_YWHZXX T
       SET T.YWHZWCBZ='N'
     WHERE T.YWHZWCBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.YWHZWCBZ！');
      COMMIT;
    END IF;
    --FSRQ，用于更新明细表复审日期，从而统计省局分类报表
    UPDATE CKTS_LC_YWHZXX T
       SET T.FSRQ=T.YWHZRQ
     WHERE T.YWHZWCBZ='Y' AND T.FSRQ>T.YWHZRQ;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.FSRQ！');
      COMMIT;
    END IF;
    --SEHZWCBZ，用于后续结束流程
    UPDATE CKTS_LC_YWHZXX T
       SET T.SEHZWCBZ='N'
     WHERE T.SEHZWCBZ IS NULL;
    COMMIT;
    UPDATE CKTS_LC_YWHZXX T
       SET T.SEHZWCBZ='Y'
     WHERE T.FS_MDTSE=0 AND T.YWHZWCBZ='Y' AND T.SEHZWCBZ='N';
    COMMIT;

    FOR CUR_TKXX IN (SELECT T.YWHZBUUID, T.FS_MDTSE FROM CKTS_LC_YWHZXX T WHERE T.SEHZWCBZ='N' AND EXISTS (SELECT 1 FROM CKTS_LC_SEHZXX S WHERE S.YWHZBUUID=T.YWHZBUUID))
    LOOP
      BEGIN
        SELECT SUM(A.GKBL_MDTSE+A.BYHZ_MDTSE)
          INTO LN_MDTSE
          FROM CKTS_LC_SEHZXX A
         WHERE A.YWHZBUUID=CUR_TKXX.YWHZBUUID;
        IF LN_MDTSE=CUR_TKXX.FS_MDTSE THEN
          UPDATE CKTS_LC_YWHZXX T
             SET T.SEHZWCBZ='Y'
           WHERE T.YWHZBUUID=CUR_TKXX.YWHZBUUID;
          COMMIT;
        END IF;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.SEHZWCBZ！');
      COMMIT;
    END IF;
    --部分单机版老数据无流程信息，不处理，仅处理有流程信息的数据
    --根据审核信息设置分类管理等级
    UPDATE CKTS_LC_YWHZXX T
       SET T.CKQYGLLB_DM=(SELECT A.CKQYGLLB_DM
                            FROM CKTS_LC_SHXX A
                           WHERE A.LCSLID_FS=T.LCSLID_FS
                             AND ROWNUM=1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    --无审核信息数据设置分类管理等级
    UPDATE CKTS_LC_YWHZXX T
       SET T.CKQYGLLB_DM=(SELECT KZXX
                            FROM TL_BJTS.GS_DJ_CKTMSDAB A, TL_BJTS.GS_DJ_CKTMSDAB_KZ B
                           WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=TO_CHAR(T.DJXH) AND B.KZLX='FLGLCD' AND T.FSRQ BETWEEN B.ST_DATE AND B.END_DATE
                             AND ROWNUM=1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    --无审核信息数据设置分类管理等级，复审日期未实行分类管理政策，按当前
    UPDATE CKTS_LC_YWHZXX T
       SET T.CKQYGLLB_DM=(SELECT FLGLCD
                            FROM GLXT_BB_SHXT_DJXX A
                           WHERE A.DJXH_JS=T.DJXH
                             AND ROWNUM=1)
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    UPDATE CKTS_LC_YWHZXX T
       SET T.CKQYGLLB_DM='M'
     WHERE T.CKQYGLLB_DM IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.CKQYGLLB_DM！');
      COMMIT;
    END IF;

    --根据审核信息设置无纸化标志
    UPDATE CKTS_LC_YWHZXX T
       SET T.WZHBZ=(SELECT A.WZHBZ
                      FROM CKTS_LC_SHXX A
                     WHERE A.LCSLID_FS=T.LCSLID_FS
                       AND ROWNUM=1)
     WHERE T.LCSLID_FS IS NOT NULL AND T.WZHBZ IS NULL;
    COMMIT;
    --无审核信息数据设置无纸化标志
    UPDATE CKTS_LC_YWHZXX T
       SET T.WZHBZ='Y'
     WHERE T.WZHBZ IS NULL
       AND EXISTS (SELECT 1
                     FROM TL_BJTS.GS_DJ_CKTMSDAB A, TL_BJTS.GS_DJ_CKTMSDAB_KZ B
                    WHERE A.NSRDZDAH=B.NSRDZDAH AND A.CPCODE=TO_CHAR(T.DJXH) AND B.KZLX='WZHQY'
                      AND ((T.FSRQ BETWEEN B.ST_DATE AND B.END_DATE) OR (TRUNC(SYSDATE) BETWEEN B.ST_DATE AND B.END_DATE)));
    COMMIT;
    UPDATE CKTS_LC_YWHZXX T
       SET T.WZHBZ='N'
     WHERE T.WZHBZ IS NULL;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.WZHBZ！');
      COMMIT;
    END IF;

    --根据审核信息设置LCTJJC
    FOR CUR_HZXX IN (SELECT T.YWHZBUUID,T.CKTMSHWYSFWLX_DM,MAX(S.LCTJJC) AS LCTJJC
                       FROM CKTS_LC_YWHZXX T
                      INNER JOIN CKTS_LC_SHXX S ON S.LCSLID_FS=T.LCSLID_FS
                      WHERE T.LCSLID_FS IS NOT NULL AND T.LCTJJC='00'
                      GROUP BY T.YWHZBUUID,T.CKTMSHWYSFWLX_DM)
    LOOP
      UPDATE CKTS_LC_YWHZXX A
         SET A.LCTJJC=(CASE WHEN (CUR_HZXX.LCTJJC IN ('72','71','70','30','23','22','21','10')) OR (CUR_HZXX.CKTMSHWYSFWLX_DM='2') THEN CUR_HZXX.LCTJJC
                            ELSE (CASE WHEN CUR_HZXX.LCTJJC IN ('63','53','43') THEN '23'
                                       WHEN CUR_HZXX.LCTJJC IN ('62','52','42') THEN '22'
                                       WHEN CUR_HZXX.LCTJJC IN ('61','51','41') THEN '21'
                                       WHEN CUR_HZXX.LCTJJC IN ('50','40') THEN '10'
                                       ELSE '00'
                                 END)
                      END)
       WHERE A.YWHZBUUID=CUR_HZXX.YWHZBUUID;
      COMMIT;
    END LOOP;

    --解除暂不办理退税（免退税）
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='10'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082038001';
    COMMIT;
    --解除暂不办理退税（周边）
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='30'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082039001';
    COMMIT;
    --解除暂不办理退税（代办退税）
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='72'
     WHERE T.LCTJJC='00'
       AND T.SBYWB_DM='LCSXA082040001';
    COMMIT;
    --离境退税
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='30', T.SBYWB_DM='LCSXA082042001'
     WHERE T.LCTJJC='00'
       AND T.TBYY_DM='470';
    COMMIT;
    --外商投资企业
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='23'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1' AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
    COMMIT;
    --委托出口企业
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='22'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1' AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
    COMMIT;
    --内资生产企业
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='21'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='1');
    COMMIT;
    --外贸企业
    UPDATE CKTS_LC_YWHZXX T
       SET T.LCTJJC='10'
     WHERE T.LCTJJC='00'
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_SHXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
       AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.JSMODE='2');
    COMMIT;

    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_YWHZXX.LCTJJC！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_YWHZXX数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_YWHZXX数据,处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SEHZXX数据处理（设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次）
  BEGIN
    UPDATE CKTS_LC_SEHZXX T
       SET (T.SBYWB_DM, T.SSQ, T.SBPC, T.CKQYGLLB_DM, T.WZHBZ, T.LCTJJC, T.CKTMSHWYSFWLX_DM)=
           (SELECT A.SBYWB_DM, A.SSQ, A.SBPC, A.CKQYGLLB_DM, A.WZHBZ, A.LCTJJC, A.CKTMSHWYSFWLX_DM
              FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND ROWNUM=1)
     WHERE T.LCTJJC='00';
    COMMIT;

    UPDATE CKTS_LC_SEHZXX T
       SET (T.SBYWB_DM, T.SSQ, T.SBPC, T.CKQYGLLB_DM, T.WZHBZ, T.LCTJJC, T.CKTMSHWYSFWLX_DM)=
           (SELECT A.SBYWB_DM, A.SSQ, A.SBPC, A.CKQYGLLB_DM, A.WZHBZ, A.LCTJJC, A.CKTMSHWYSFWLX_DM
              FROM CKTS_LC_YWHZXX A
             WHERE A.YWHZBUUID=T.YWHZBUUID
               AND ROWNUM=1)
     WHERE T.SBYWB_DM IS NULL;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SEHZXX(设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次),处理成功！');
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SEHZXX(设置分类管理等级、无纸化标志、所属期、复审lcslid及统计级次),处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、BYBL_、SNBL_、SYBL_）
  BEGIN
    --免抵退业务审核信息
    FOR CUR_SHXX IN (SELECT T.UUID,T.LCSLID_SB,T.LCSLID,T.LCSLID_FS,T.SJTB_BZ,NVL(S.SB_MDTSE,0) AS SB_MDTSE,S.SB_ZZSTSE,S.SB_XFSTSE,S.SB_MDSE
                       FROM CKTS_LC_SHXX T
                      INNER JOIN CKTS_LC_SBXX S ON S.LCSLID_SB=T.LCSLID_SB
                      WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA))
    LOOP
      BEGIN
        IF (CUR_SHXX.SJTB_BZ='9') AND (CUR_SHXX.LCSLID<>CUR_SHXX.LCSLID_SB) AND (TRIM(CUR_SHXX.LCSLID_FS) IS NOT NULL) THEN
          UPDATE CKTS_LC_SHXX R
             SET (R.FFBZ,R.FFR_DM,R.FFRQ)=(SELECT S.FFBZ,S.FFR_DM,S.FFRQ
                                             FROM CKTS_LC_SHXX S
                                            WHERE S.LCSLID_SB=CUR_SHXX.LCSLID_FS
                                              AND S.LCSLID=CUR_SHXX.LCSLID_FS
                                              AND ROWNUM=1)
           WHERE R.UUID=CUR_SHXX.UUID;
          COMMIT;
        END IF;

        SELECT NVL(SUM(TT.YSFWYYEMY),0), NVL(SUM(TT.YSFWYYERMB),0), NVL(SUM(TT.MDTSE),0), NVL(SUM(CASE WHEN TT.BYBLBZ='Y' THEN TT.MDTSE ELSE 0 END),0)
          INTO LN_MYLAJ, LN_RMBLAJ, LN_MDTSE, LN_BYBL_MDTSE
          FROM (SELECT A.YSFWYYEMY,A.YSFWYYERMB,A.MDTSE,A.BYBLBZ FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID=CUR_SHXX.LCSLID
                 UNION ALL
                SELECT B.YSFWYYEMY,B.YSFWYYERMB,B.MDTSE,B.BYBLBZ FROM CKTS_SB_MDT_YFSJ B WHERE B.LCSLID=CUR_SHXX.LCSLID
                 UNION ALL
                SELECT C.MYLAJ AS YSFWYYEMY,C.RMBLAJ AS YSFWYYERMB,C.MDTSE,C.BYBLBZ FROM CKTS_SB_MDT_CKMX C WHERE C.LCSLID=CUR_SHXX.LCSLID) TT;
        IF CUR_SHXX.SB_MDTSE=0 THEN
          UPDATE CKTS_LC_SHXX A
             SET A.SB_XSEMY=LN_MYLAJ, A.SB_XSERMB=LN_RMBLAJ,
                 A.SB_MDTSE=0, A.SB_ZZSTSE=0, A.SB_XFSTSE=0, A.SB_MDSE=0,
                 A.BYBL_MDTSE=0, A.BYBL_ZZSTSE=0, A.BYBL_XFSTSE=0, A.BYBL_MDSE=0
           WHERE A.UUID=CUR_SHXX.UUID;
        ELSE
          UPDATE CKTS_LC_SHXX A
             SET A.SB_XSEMY=LN_MYLAJ, A.SB_XSERMB=LN_RMBLAJ,
                 A.SB_MDTSE =LN_MDTSE,
                 A.SB_ZZSTSE=LN_MDTSE * CUR_SHXX.SB_ZZSTSE / CUR_SHXX.SB_MDTSE,
                 A.SB_XFSTSE=LN_MDTSE * CUR_SHXX.SB_XFSTSE / CUR_SHXX.SB_MDTSE,
                 A.SB_MDSE  =LN_MDTSE * CUR_SHXX.SB_MDSE   / CUR_SHXX.SB_MDTSE,
                 A.BYBL_MDTSE =LN_BYBL_MDTSE,
                 A.BYBL_ZZSTSE=LN_BYBL_MDTSE * CUR_SHXX.SB_ZZSTSE / CUR_SHXX.SB_MDTSE,
                 A.BYBL_XFSTSE=LN_BYBL_MDTSE * CUR_SHXX.SB_XFSTSE / CUR_SHXX.SB_MDTSE,
                 A.BYBL_MDSE  =LN_BYBL_MDTSE * CUR_SHXX.SB_MDSE   / CUR_SHXX.SB_MDTSE
           WHERE A.UUID=CUR_SHXX.UUID;
        END IF;
        COMMIT;
      END;
    END LOOP;
    UPDATE CKTS_LC_SHXX T
       SET T.SB_MDTSE=T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE
     WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND T.SB_MDTSE<>T.SB_ZZSTSE+T.SB_XFSTSE+T.SB_MDSE;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(免抵退业务审核信息SB_)！');
      COMMIT;
    END IF;

    FOR CUR_SHXX IN (SELECT T.UUID,T.LCSLID,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE
                       FROM CKTS_LC_SHXX T
                      WHERE T.SBYWB_DM='A0305001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
                        AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID_FS))
    LOOP
      BEGIN
        SELECT NVL(SUM(CASE WHEN TT.ZHBZ_1='Y' THEN TT.MDTSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN TT.BYTSBZ='Y' THEN TT.MDTSE ELSE 0 END),0)
          INTO LN_ZH_MDTSE, LN_BYTS_MDTSE
          FROM (SELECT A.MDTSE,A.ZHBZ_1,A.BYTSBZ FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID=CUR_SHXX.LCSLID
                 UNION ALL
                SELECT B.MDTSE,B.ZHBZ_1,B.BYTSBZ FROM CKTS_SB_MDT_YFSJ B WHERE B.LCSLID=CUR_SHXX.LCSLID
                 UNION ALL
                SELECT C.MDTSE,C.ZHBZ_1,C.BYTSBZ FROM CKTS_SB_MDT_CKMX C WHERE C.LCSLID=CUR_SHXX.LCSLID) TT;
        UPDATE CKTS_LC_SHXX A
           SET A.ZH_MDTSE = LN_ZH_MDTSE, A.ZH_XFSTSE=0,
               A.ZH_ZZSTSE= LN_ZH_MDTSE * CASE WHEN CUR_SHXX.SB_MDTSE=0 THEN 1 ELSE CUR_SHXX.SB_ZZSTSE / CUR_SHXX.SB_MDTSE END,
               A.ZH_MDSE  = LN_ZH_MDTSE * CASE WHEN CUR_SHXX.SB_MDTSE=0 THEN 0 ELSE CUR_SHXX.SB_MDSE / CUR_SHXX.SB_MDTSE END,
               A.BY_MDTSE = LN_BYTS_MDTSE, A.BY_XFSTSE=0,
               A.BY_ZZSTSE= LN_BYTS_MDTSE * CASE WHEN CUR_SHXX.SB_MDTSE=0 THEN 1 ELSE CUR_SHXX.SB_ZZSTSE / CUR_SHXX.SB_MDTSE END,
               A.BY_MDSE  = LN_BYTS_MDTSE * CASE WHEN CUR_SHXX.SB_MDTSE=0 THEN 0 ELSE CUR_SHXX.SB_MDSE / CUR_SHXX.SB_MDTSE END
         WHERE A.UUID=CUR_SHXX.UUID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(免抵退业务审核信息BY_ZH_)！');
      COMMIT;
    END IF;

    --免退税业务审核信息
    UPDATE CKTS_LC_SHXX T
       SET T.SB_XSEMY =(SELECT NVL(SUM(A.MYLAJ),0)
                          FROM CKTS_SB_MTS_CKMX A
                         WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE,T.BYBL_MDTSE,T.BYBL_ZZSTSE,T.BYBL_XFSTSE,T.BYBL_MDSE) =
           (SELECT NVL(SUM(CASE WHEN A.SZ='V' THEN A.JSJE ELSE 0 END),0),
                   NVL(SUM(A.TSE),0),
                   NVL(SUM(CASE WHEN A.SZ='V' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.SZ='C' THEN A.TSE ELSE 0 END),0),
                   0,
                   NVL(SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.BYBLBZ='Y' AND A.SZ='V' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.BYBLBZ='Y' AND A.SZ='C' THEN A.TSE ELSE 0 END),0),
                   0
              FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE  T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.BY_MDTSE,T.BY_ZZSTSE,T.BY_XFSTSE,T.BY_MDSE,T.ZH_MDTSE,T.ZH_ZZSTSE,T.ZH_XFSTSE,T.ZH_MDSE) =
           (SELECT NVL(SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.BYTSBZ='Y' AND A.SZ='V' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.BYTSBZ='Y' AND A.SZ='C' THEN A.TSE ELSE 0 END),0),
                   0,
                   NVL(SUM(CASE WHEN A.ZBBLBZ='Y' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.ZBBLBZ='Y' AND A.SZ='V' THEN A.TSE ELSE 0 END),0),
                   NVL(SUM(CASE WHEN A.ZBBLBZ='Y' AND A.SZ='C' THEN A.TSE ELSE 0 END),0),
                   0
              FROM CKTS_SB_MTS_JHMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID AND S.CKTMSHWYSFWLX_DM='1');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(免退税业务审核信息)！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SHXX T
       SET T.LCSLID_SB=T.LCSLID
     WHERE T.SBYWB_DM='A0301001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND T.LCSLID_SB<>T.LCSLID AND T.SB_XSEMY<0;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(免退税红字冲减业务的申报流程)！');
      COMMIT;
    END IF;

    --外综服业务审核信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SHXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE,T.BYBL_MDTSE,T.BYBL_ZZSTSE,T.BYBL_XFSTSE,T.BYBL_MDSE) =
           (SELECT SUM(A.MYLAJ),SUM(A.JSJE),SUM(A.TSE),SUM(A.TSE),0,0,
                   SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), 0, 0
              FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0310001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.BY_MDTSE,T.BY_ZZSTSE,T.BY_XFSTSE,T.BY_MDSE,T.ZH_MDTSE,T.ZH_ZZSTSE,T.ZH_XFSTSE,T.ZH_MDSE) =
           (SELECT SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END), 0, 0,
                   SUM(CASE WHEN A.ZBBLBZ='Y' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.ZBBLBZ='Y' THEN A.TSE ELSE 0 END), 0, 0
              FROM CKTS_SB_WZF_CKMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0310001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID AND S.CKTMSHWYSFWLX_DM='1');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(外综服业务审核信息)！');
      COMMIT;
    END IF;

    --非自产业务审核信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SHXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE,T.BYBL_MDTSE,T.BYBL_ZZSTSE,T.BYBL_XFSTSE,T.BYBL_MDSE) =
           (SELECT 0,SUM(A.JSJE),SUM(A.XFSTSE),0,SUM(A.XFSTSE),0,
                   SUM(CASE WHEN A.BYBLBZ='Y' THEN A.XFSTSE ELSE 0 END),0,SUM(CASE WHEN A.BYBLBZ='Y' THEN A.XFSTSE ELSE 0 END), 0
              FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0302001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.BY_MDTSE,T.BY_ZZSTSE,T.BY_XFSTSE,T.BY_MDSE,T.ZH_MDTSE,T.ZH_ZZSTSE,T.ZH_XFSTSE,T.ZH_MDSE) =
           (SELECT SUM(CASE WHEN A.BYTSBZ='Y' THEN A.XFSTSE ELSE 0 END),0,SUM(CASE WHEN A.BYTSBZ='Y' THEN A.XFSTSE ELSE 0 END),0,
                   0, 0, 0, 0
              FROM CKTS_SB_FZC_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0302001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(非自产业务审核信息)！');
      COMMIT;
    END IF;

    --旧设备审核信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SHXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE,T.BYBL_MDTSE,T.BYBL_ZZSTSE,T.BYBL_XFSTSE,T.BYBL_MDSE) =
           (SELECT 0,SUM(A.SBZYJZ),SUM(A.TSE),SUM(A.TSE),0,0,
                   SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), 0, 0
              FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0303001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.BY_MDTSE,T.BY_ZZSTSE,T.BY_XFSTSE,T.BY_MDSE,T.ZH_MDTSE,T.ZH_ZZSTSE,T.ZH_XFSTSE,T.ZH_MDSE) =
           (SELECT SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END),SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END),0,0,
                   0, 0, 0, 0
              FROM CKTS_SB_YS_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0303001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(旧设备审核信息)！');
      COMMIT;
    END IF;

    --购进自用审核信息，如果etl抽取则取消本次更新
    UPDATE CKTS_LC_SHXX T
       SET (T.SB_XSEMY,T.SB_XSERMB,T.SB_MDTSE,T.SB_ZZSTSE,T.SB_XFSTSE,T.SB_MDSE,T.BYBL_MDTSE,T.BYBL_ZZSTSE,T.BYBL_XFSTSE,T.BYBL_MDSE) =
           (SELECT 0,SUM(A.JSJE),SUM(A.TSE),SUM(A.TSE),0,0,
                   SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), SUM(CASE WHEN A.BYBLBZ='Y' THEN A.TSE ELSE 0 END), 0, 0
              FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0304001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA);
    UPDATE CKTS_LC_SHXX T
       SET (T.BY_MDTSE,T.BY_ZZSTSE,T.BY_XFSTSE,T.BY_MDSE,T.ZH_MDTSE,T.ZH_ZZSTSE,T.ZH_XFSTSE,T.ZH_MDSE) =
           (SELECT SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END),SUM(CASE WHEN A.BYTSBZ='Y' THEN A.TSE ELSE 0 END),0,0,
                   0, 0, 0, 0
              FROM CKTS_SB_GJ_SBMX A
             WHERE A.LCSLID=T.LCSLID)
     WHERE T.SBYWB_DM='A0304001' AND T.ZFBZ IS NULL AND (T.FFBZ IS NULL OR T.FFRQ>=LD_DEALDATA)
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(购进自用审核信息)！');
      COMMIT;
    END IF;

    --部分免退税业务含跨境应税行为，需要两边合计
    FOR CUR_MTSYSFW IN (SELECT LCSLID, SUM(SKJEMY) AS MYLAJ, SUM(BQQRYSFWYYSRRMBJE) AS RMBLAJ,SUM(ZZSTSE) AS ZZSTSE,
                               SUM(CASE WHEN BYTSBZ='Y' THEN ZZSTSE ELSE 0 END) AS BY_ZZSTSE, SUM(CASE WHEN BYBLBZ='Y' THEN ZZSTSE ELSE 0 END) AS BYBL_ZZSTSE
                          FROM CKTS_SB_MTS_YSFW GROUP BY LCSLID)
    LOOP
      BEGIN
        UPDATE CKTS_LC_SHXX T
           SET T.SB_XSEMY = CUR_MTSYSFW.MYLAJ + (SELECT NVL(SUM(A.MYLAJ),0) FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID),
               T.SB_XSERMB = CUR_MTSYSFW.RMBLAJ + (SELECT NVL(SUM(A.JSJE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.SZ='V'),
               T.SB_MDTSE = CUR_MTSYSFW.ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID),
               T.SB_ZZSTSE = CUR_MTSYSFW.ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.SZ='V'),
               T.SB_XFSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.SZ='C'),
               T.SB_MDSE = 0,
               T.BY_MDTSE = CUR_MTSYSFW.BY_ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYTSBZ='Y'),
               T.BY_ZZSTSE = CUR_MTSYSFW.BY_ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYTSBZ='Y' AND A.SZ='V'),
               T.BY_XFSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYTSBZ='Y' AND A.SZ='C'),
               T.BY_MDSE = 0,
               T.ZH_MDTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.ZBBLBZ='Y'),
               T.ZH_ZZSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.ZBBLBZ='Y' AND A.SZ='V'),
               T.ZH_XFSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.ZBBLBZ='Y' AND A.SZ='C'),
               T.ZH_MDSE = 0,
               T.BYBL_MDTSE = CUR_MTSYSFW.BYBL_ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYBLBZ='Y'),
               T.BYBL_ZZSTSE = CUR_MTSYSFW.BYBL_ZZSTSE + (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYBLBZ='Y' AND A.SZ='V'),
               T.BYBL_XFSTSE = (SELECT NVL(SUM(A.TSE),0) FROM CKTS_SB_MTS_JHMX A WHERE A.LCSLID=CUR_MTSYSFW.LCSLID AND A.BYBLBZ='Y' AND A.SZ='C'),
               T.BYBL_MDSE = 0
         WHERE T.LCSLID=CUR_MTSYSFW.LCSLID;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(部分免退税业务含跨境应税行为)！');
      COMMIT;
    END IF;

    --根据业务核准表设置准予退税信息
    FOR CUR_SHXX IN (SELECT T.LCSLID_FS, COUNT(1) AS LCSLID_DUP,
                            SUM(NVL(T.SB_MDTSE,0)-NVL(T.BYBL_MDTSE,0)-NVL(T.BY_MDTSE,0)-NVL(T.ZH_MDTSE,0)) AS LCSLID_MDTSE
                       FROM CKTS_LC_SHXX T
                      WHERE T.ZFBZ IS NULL AND T.LCJSRQ>=LD_DEALDATA
                        AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX S WHERE S.LCSLID_FS=T.LCSLID_FS)
                      GROUP BY T.LCSLID_FS)
    LOOP
      BEGIN
        SELECT NVL(SUM(A.FS_MDTSE),0),NVL(SUM(A.FS_ZZSTSE),0),NVL(SUM(A.FS_XFSTSE),0),NVL(SUM(A.FS_MDSE),0)
          INTO LN_MDTSE, LN_ZZS, LN_XFS, LN_MDSE
          FROM CKTS_LC_YWHZXX A
         WHERE A.LCSLID_FS=CUR_SHXX.LCSLID_FS;
        SELECT NVL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSNF THEN B.GKBL_ZZSTSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSNF THEN B.GKBL_XFSTSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN B.XHRQ_MD<LD_BBNY_KSNF THEN B.GKBL_MDSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSRQ THEN B.GKBL_ZZSTSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN B.XHRQ_TK<LD_BBNY_KSRQ THEN B.GKBL_XFSTSE ELSE 0 END),0),
               NVL(SUM(CASE WHEN B.XHRQ_MD<LD_BBNY_KSRQ THEN B.GKBL_MDSE ELSE 0 END),0)
          INTO SN_ZZS, SN_XFS, SN_MDSE, SY_ZZS, SY_XFS, SY_MDSE
          FROM CKTS_LC_YWHZXX A
         INNER JOIN CKTS_LC_SEHZXX B ON B.YWHZBUUID=A.YWHZBUUID
         WHERE A.LCSLID_FS=CUR_SHXX.LCSLID_FS;
        IF CUR_SHXX.LCSLID_DUP=1 THEN
          UPDATE CKTS_LC_SHXX A
             SET A.ZY_MDTSE = LN_MDTSE, A.ZY_ZZSTSE= LN_ZZS, A.ZY_XFSTSE=LN_XFS, A.ZY_MDSE  = LN_MDSE,
                 A.SNBL_MDTSE= SN_ZZS + SN_XFS + SN_MDSE, A.SNBL_ZZSTSE= SN_ZZS, A.SNBL_XFSTSE= SN_XFS, A.SNBL_MDSE= SN_MDSE,
                 A.SYBL_MDTSE= SY_ZZS + SY_XFS + SY_MDSE, A.SYBL_ZZSTSE= SY_ZZS, A.SYBL_XFSTSE= SY_XFS, A.SYBL_MDSE= SY_MDSE
           WHERE A.LCSLID_FS=CUR_SHXX.LCSLID_FS;
        ELSIF CUR_SHXX.LCSLID_MDTSE<>0 THEN
          UPDATE CKTS_LC_SHXX A
             SET A.ZY_MDTSE = LN_MDTSE * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.ZY_ZZSTSE= LN_ZZS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.ZY_XFSTSE=LN_XFS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.ZY_MDSE  = LN_MDSE * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SNBL_MDTSE= (SN_ZZS + SN_XFS + SN_MDSE) * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SNBL_ZZSTSE= SN_ZZS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SNBL_XFSTSE= SN_XFS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SNBL_MDSE= SN_MDSE * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SYBL_MDTSE= (SY_ZZS + SY_XFS + SY_MDSE) * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SYBL_ZZSTSE= SY_ZZS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SYBL_XFSTSE= SY_XFS * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE,
                 A.SYBL_MDSE= SY_MDSE * (NVL(A.SB_MDTSE,0)-NVL(A.BYBL_MDTSE,0)-NVL(A.BY_MDTSE,0)-NVL(A.ZH_MDTSE,0)) / CUR_SHXX.LCSLID_MDTSE
           WHERE A.LCSLID_FS=CUR_SHXX.LCSLID_FS;
        END IF;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX设置(根据业务核准表设置准予退税信息)！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SHXX T
       SET (T.BYHZ_MDTSE,T.BYHZ_ZZSTSE,T.BYHZ_XFSTSE,T.BYHZ_MDSE) =
           (SELECT NVL(SUM(A.BYHZ_MDTSE),0),NVL(SUM(A.BYHZ_ZZSTSE),0),NVL(SUM(A.BYHZ_XFSTSE),0),NVL(SUM(A.BYHZ_MDSE),0)
              FROM CKTS_LC_SEHZXX A
             WHERE A.LCSLID_FS=T.LCSLID_FS AND A.SEHZRQ<SYSDATE)
     WHERE T.LCJSRQ>=LD_DEALDATA ;
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.BYHZ_MDTSE！');
      COMMIT;
    END IF;

    UPDATE CKTS_LC_SHXX T
       SET T.ZH_MDTSE=T.ZH_ZZSTSE+T.ZH_XFSTSE+T.ZH_MDSE
     WHERE T.ZFBZ IS NULL AND T.ZH_MDTSE<>T.ZH_ZZSTSE+T.ZH_XFSTSE+T.ZH_MDSE;
    COMMIT;
    UPDATE CKTS_LC_SHXX T
       SET T.BY_MDTSE=T.BY_ZZSTSE+T.BY_XFSTSE+T.BY_MDSE
     WHERE T.ZFBZ IS NULL AND T.BY_MDTSE<>T.BY_ZZSTSE+T.BY_XFSTSE+T.BY_MDSE;
    COMMIT;
    UPDATE CKTS_LC_SHXX T
       SET T.ZY_MDTSE=T.ZY_ZZSTSE+T.ZY_XFSTSE+T.ZY_MDSE
     WHERE T.ZFBZ IS NULL AND T.ZY_MDTSE<>T.ZY_ZZSTSE+T.ZY_XFSTSE+T.ZY_MDSE;
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、SNBL_、SYBL_）处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据处理（SB_、ZH_、BY_、ZY_、SNBL_、SYBL_）处理失败！', LC_SBYY);
      COMMIT;
  END;

  --CKTS_LC_SHXX数据处理（判断LCJSRQ、LASTOPDATE）
  BEGIN
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = DATE'2100-12-31'
     WHERE T.LCJSRQ IS NULL;
    COMMIT;
    --申报数为0
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND NVL(T.SB_MDTSE,0)=0
       AND NVL(T.ZY_MDTSE,0)=0
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --复核数为0
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND T.SB_MDTSE>0
       AND T.SB_MDTSE=T.BYBL_MDTSE + NVL(T.BY_MDTSE,0)+NVL(T.ZH_MDTSE,0)
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --核准数为0
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND T.ZY_MDTSE>0
       AND T.ZY_MDTSE=T.BYHZ_MDTSE
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --有税额且税额核准全部完成
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = (SELECT MAX(GREATEST(A.XHRQ_TK,A.XHRQ_MD,A.XHRQ_XFS)) FROM CKTS_LC_SEHZXX A WHERE A.LCSLID_FS=T.LCSLID_FS)
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y' AND B.FS_MDTSE<>0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='N')
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --无税额且税额核准全部完成
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y' AND B.FS_MDTSE=0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='N')
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --流程有子流程也本身无明细数据
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND NVL(T.SB_MDTSE,0)=0
       AND EXISTS (SELECT 1 FROM CKTS_LC_SHXX R WHERE R.LCSLID_SB=T.LCSLID_SB AND R.ZLCLCSLID=T.LCSLID)
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;
    --免抵退分流程复核数=0
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = T.FFRQ
     WHERE T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9'
       AND T.LCJSRQ>=LD_DEALDATA
       AND T.FFBZ='Y'
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX A WHERE A.LCSLID_FS=T.LCSLID_FS AND A.FS_MDTSE=0)
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.FS_MDTSE<>0);
    COMMIT;
    --免抵退分流程复核数<>0
    UPDATE CKTS_LC_SHXX T
       SET T.LCJSRQ = (SELECT MAX(GREATEST(A.XHRQ_TK,A.XHRQ_MD,A.XHRQ_XFS))
                         FROM CKTS_LC_SEHZXX A
                        WHERE A.LCSLID_FS=T.LCSLID_FS)
     WHERE T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9'
       AND T.LCJSRQ>=LD_DEALDATA
       AND EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX B WHERE B.LCSLID_FS=T.LCSLID_FS AND B.SEHZWCBZ='Y')
       AND NOT EXISTS (SELECT 1 FROM CKTS_LC_YWHZXX C WHERE C.LCSLID_FS=T.LCSLID_FS AND C.SEHZWCBZ='N');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.LCJSRQ！');
      COMMIT;
    END IF;

    --LASTOPDATE，流程已结束的按结束日期
    UPDATE CKTS_LC_SHXX T
       SET T.LASTOPDATE = T.LCJSRQ
     WHERE T.LCJSRQ<=SYSDATE AND T.LCJSRQ<>T.LASTOPDATE
       AND NOT (T.SBYWB_DM='A0305001' AND T.SJTB_BZ='9');
    COMMIT;

    FOR CUR_LCSLID IN (SELECT S.UUID,S.LCSLID_FS,NVL(S.FFRQ,S.QDSJ) AS SHSJ
                         FROM CKTS_LC_SHXX S
                        WHERE S.LCJSRQ>=LD_DEALDATA)
    LOOP
      BEGIN
        LD_LASTRQ := CUR_LCSLID.SHSJ;

        SELECT GREATEST(LD_LASTRQ,NVL(MAX(FSRQ),LD_LASTRQ),NVL(MAX(YWHZRQ),LD_LASTRQ))
          INTO LD_LASTRQ
          FROM CKTS_LC_YWHZXX
         WHERE LCSLID_FS=CUR_LCSLID.LCSLID_FS;
        SELECT GREATEST(LD_LASTRQ,NVL(MAX(SEHZRQ),LD_LASTRQ),NVL(MAX(DECODE(XHRQ_TK,DATE'2100-12-31',LD_LASTRQ,XHRQ_TK)),LD_LASTRQ),NVL(MAX(DECODE(XHRQ_MD,DATE'2100-12-31',LD_LASTRQ,XHRQ_MD)),LD_LASTRQ),NVL(MAX(DECODE(XHRQ_XFS,DATE'2100-12-31',LD_LASTRQ,XHRQ_XFS)),LD_LASTRQ))
          INTO LD_LASTRQ
          FROM CKTS_LC_SEHZXX
         WHERE LCSLID_FS=CUR_LCSLID.LCSLID_FS;

        UPDATE CKTS_LC_SHXX T
           SET T.LASTOPDATE = LD_LASTRQ
         WHERE T.UUID=CUR_LCSLID.UUID AND T.LASTOPDATE<LD_LASTRQ;
        COMMIT;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             CKTS_LC_SHXX.LASTOPDATE！');
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_LC_SHXX数据（LCJSRQ、LASTOPDATE）处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_LC_SHXX数据（LCJSRQ、LASTOPDATE）处理失败！', LC_SBYY);
      COMMIT;
  END;

  --每月初，进行报表中间数据提取，包括未申报数据、跨境电商数据、明细复审时间及分类统计数据，然后调用报表初始化过程
  --CKTS_WBSJ_BGD_9X10数据
  --20250718，基于态势感知新业态9810数据展现需求，9X10数据改为每日gcb数据全部刷新，jgb数据按提前量增量刷新
  BEGIN
    DELETE FROM CKTS_WBSJ_BGD_9X10 A WHERE A.SJLY='1';
    COMMIT;
    
    MERGE INTO CKTS_WBSJ_BGD_9X10 A
         USING (SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0305001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       NVL(T.CKBGDH,T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.MDTSE,
                       ROUND(T.MDTSE * CASE WHEN S.MDTSEHJ<=0 THEN 0 ELSE S.YTSE_1/S.MDTSEHJ END, 2) AS TSE,
                       CASE WHEN T.MDTSNY IS NULL THEN 'N' ELSE 'Y' END AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MDT_CKMX T
                 INNER JOIN CKTS_SB_MDT_SBDSHZ S ON S.LCSLID=T.LCSLID_SB
                 WHERE T.SJLY='1'
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0305001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       NVL(T.CKBGDH,T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.MDTSE,
                       ROUND(T.MDTSE * CASE WHEN S.MDTSEHJ<=0 THEN 0 ELSE S.YTSE_1/S.MDTSEHJ END, 2) AS TSE,
                       CASE WHEN T.MDTSNY IS NULL THEN 'N' ELSE 'Y' END AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MDT_CKMX T
                 INNER JOIN CKTS_SB_MDT_SBDSHZ S ON S.LCSLID=T.LCSLID_FS
                 WHERE T.SJLY='2'
                   AND T.SJTB_SJ>=LD_DEALDATA
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0301001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       NVL(T.CKBGDH,T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.TSE AS MDTSE,T.TSE,
                       T.MTSBZ AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MTS_CKMX T
                 WHERE T.SJLY='1'
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0301001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       NVL(T.CKBGDH,T.DLCKHWZMHM) AS CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.TSE AS MDTSE,T.TSE,
                       T.MTSBZ AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_MTS_CKMX T
                 WHERE T.SJLY='2'
                   AND T.SJTB_SJ>=LD_DEALDATA
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0310001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       T.CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.TSE AS MDTSE,T.TSE,
                       T.MTSBZ AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_WZF_CKMX T
                 WHERE T.SJLY='1'
                   AND T.TDCODE IN ('9610','9710','9810')
                 UNION ALL
                SELECT T.UUID,T.LCSLID,T.TSSWJG_DM,T.DJXH,'A0310001' AS SBYWB_DM,T.SSQ,T.SBPC,T.SBXH,
                       T.CKBGDH,T.CKRQ_1,T.CKSP_DM,T.TDCODE,T.MYLAJ,T.TSE AS MDTSE,T.TSE,
                       T.MTSBZ AS ZYTSBZ,T.SBRQ,T.FSRQ,
                       CASE WHEN INSTR(T.CKTMSYWLXDMJH,'HWC-YT')>0 THEN 'HWC-YT' ELSE NULL END AS CKTMSYWLXDMJH,
                       T.SJLY,T.SJTB_SJ
                  FROM CKTS_SB_WZF_CKMX T
                 WHERE T.SJLY='2'
                   AND T.SJTB_SJ>=LD_DEALDATA
                   AND T.TDCODE IN ('9610','9710','9810')
                ) B
            ON (A.UUID=B.UUID)
          WHEN MATCHED THEN
            UPDATE SET A.LCSLID=B.LCSLID, A.TSSWJG_DM=B.TSSWJG_DM, A.DJXH=B.DJXH, A.SBYWB_DM=B.SBYWB_DM, A.SSQ=B.SSQ, A.SBPC=B.SBPC, A.SBXH=B.SBXH, 
                       A.CKBGDH=B.CKBGDH, A.CKRQ_1=B.CKRQ_1, A.CKSP_DM=B.CKSP_DM, A.TDCODE=B.TDCODE, A.MYLAJ=B.MYLAJ, A.MDTSE=B.MDTSE, A.TSE=B.TSE, 
                       A.ZYTSBZ=B.ZYTSBZ, A.SBRQ=B.SBRQ, A.FSRQ=B.FSRQ, A.CKTMSYWLXDMJH=B.CKTMSYWLXDMJH, A.SJLY=B.SJLY, A.SJTB_SJ=B.SJTB_SJ
          WHEN NOT MATCHED THEN
            INSERT (UUID,LCSLID,TSSWJG_DM,DJXH,SBYWB_DM,SSQ,SBPC,SBXH,CKBGDH,CKRQ_1,CKSP_DM,TDCODE,MYLAJ,MDTSE,TSE,ZYTSBZ,SBRQ,FSRQ,CKTMSYWLXDMJH,SJLY,SJTB_SJ)
            VALUES (B.UUID,B.LCSLID,B.TSSWJG_DM,B.DJXH,B.SBYWB_DM,B.SSQ,B.SBPC,B.SBXH,B.CKBGDH,B.CKRQ_1,B.CKSP_DM,B.TDCODE,B.MYLAJ,B.MDTSE,B.TSE,B.ZYTSBZ,B.SBRQ,
                   B.FSRQ,B.CKTMSYWLXDMJH,B.SJLY,B.SJTB_SJ);
    COMMIT;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_WBSJ_BGD_9X10数据,处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('CKTS_WBSJ_BGD_9X10数据,处理失败！', LC_SBYY);
      COMMIT;
  END;
  
  --CKTS_WBSJ_BGD_WSB数据处理
  --20251204，因为未申报报关单处理比较耗时，提前至月底前一天执行
  IF TRUNC(SYSDATE) = ADD_MONTHS(LD_BBNY_JZRQ,1) -1 THEN
    BEGIN
      EXECUTE IMMEDIATE 'TRUNCATE TABLE CKTS_WBSJ_BGD_WSB';
      COMMIT;
      --插入生产、外贸企业所有未申报报关单数据
      INSERT INTO CKTS_WBSJ_BGD_WSB(UUID,TSSWJG_DM,DJXH,CKBGDH,CKRQ_1,CKSP_DM,JGFS_DM,RMBLAJ,MYLAJ,BAH)
           SELECT T.UUID,T.TSSWJG_DM_1,T.DJXH,T.CKBGDH,T.CKRQ_1,T.CKSP_DM,T.JGFS_DM,T.RMBLAJ,T.MYLAJ,T.BAH
             FROM GLXT_BB_SHXT_DJXX S, CKTS_WBSJ_HG_BGD T
            WHERE S.JSMODE IN ('1','2')
              AND NVL(S.ZX_FLAG,'N')='N'
              AND S.DJXH_JS=T.DJXH
              AND T.TSSBSL+T.DLSBSL+T.TYSL=0
              AND T.JGFS_DM<>'1039';
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             插入生产、外贸企业所有未申报报关单数据！');
        COMMIT;
      END IF;
      --删除免税贸易方式
      DELETE CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM TL_BJTS.CKTS_DM_HGJGFS
                       WHERE JGFS_DM = CKTS_WBSJ_BGD_WSB.JGFS_DM
                         AND JGFSTSLX_DM = '0');
      COMMIT;
      IF LN_LOG>1 THEN
        INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             删除免税贸易方式！');
        COMMIT;
      END IF;
      --删除禁止出口商品或不退税商品、免税商品
      DELETE CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM TL_BJTS.CKTS_DM_TSLVWK
                       WHERE CKSP_DM = CKTS_WBSJ_BGD_WSB.CKSP_DM
                         AND CKTS_WBSJ_BGD_WSB.CKRQ_1 BETWEEN YXQQ AND YXQZ
                         AND CKSPTSSPLX_DM IN ('1','2'));
      COMMIT;
      DELETE CKTS_WBSJ_BGD_WSB
       WHERE EXISTS ( SELECT 1
                        FROM TL_BJTS.CKTS_DM_TSLVWK
                       WHERE CKSP_DM = SUBSTR(CKTS_WBSJ_BGD_WSB.CKSP_DM,1,8)
                         AND CKTS_WBSJ_BGD_WSB.CKRQ_1 BETWEEN YXQQ AND YXQZ
                         AND CKSPTSSPLX_DM IN ('1','2'));
      COMMIT;
