  END IF;

  --每月初+2，处理绩效考核月报表
  IF TRUNC(SYSDATE) = LD_BBNY_JZRQ + 2 THEN
    FOR LSF_SWJG IN (SELECT SWJG_DM,YXWS FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1' AND QYBZ='Y' ORDER BY YXWS DESC,SWJG_DM) LOOP
      INSERT INTO TL_BJTS.JXKH_TJBB(TJMONTH,SWCODE,FLGLCD,SBHS,SBPCS,SL_DAY,SH_DAY,HZ_DAY,KP_DAY,HJ_DAY)
           SELECT LC_BBNY,LSF_SWJG.SWJG_DM,TT.FLGLCD,TT.SBHS,TT.SBPCS,TT.SL_DAY,TT.SH_DAY,TT.HZ_DAY,TT.KP_DAY,TT.HJ_DAY
             FROM ((SELECT T.CKQYGLLB_DM AS FLGLCD,
                           COUNT(DISTINCT T.DJXH) AS SBHS,COUNT(1) AS SBPCS,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SL_DAY ELSE NULL END),2) AS SL_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SH_DAY ELSE NULL END),2) AS SH_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.HZ_DAY ELSE NULL END),2) AS HZ_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.KP_DAY ELSE NULL END),2) AS KP_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SUM_DAY ELSE NULL END),2) AS HJ_DAY
                      FROM TL_TSSH.GLXT_BB_SHXT_LCXX T
                     WHERE T.SWJGDM LIKE SUBSTR(LSF_SWJG.SWJG_DM,1,LSF_SWJG.YXWS)||'%'
                       AND T.SL_DATE>=LD_BBNY_KSNF
                       AND T.SL_DATE< LD_BBNY_JZRQ
                     GROUP BY T.CKQYGLLB_DM
                   )
                     UNION ALL
                   (SELECT '0' AS FLGLCD,
                           COUNT(DISTINCT T.DJXH) AS SBHS,COUNT(1) AS SBPCS,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SL_DAY ELSE NULL END),2) AS SL_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SH_DAY ELSE NULL END),2) AS SH_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.HZ_DAY ELSE NULL END),2) AS HZ_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.KP_DAY ELSE NULL END),2) AS KP_DAY,
                           ROUND(AVG(CASE WHEN T.ZLC_TS_AMT>0 THEN T.SUM_DAY ELSE NULL END),2) AS HJ_DAY
                      FROM TL_TSSH.GLXT_BB_SHXT_LCXX T
                     WHERE T.SWJGDM LIKE SUBSTR(LSF_SWJG.SWJG_DM,1,LSF_SWJG.YXWS)||'%'
                       AND T.SL_DATE>=LD_BBNY_KSNF
                       AND T.SL_DATE< LD_BBNY_JZRQ
                   )
                  ) TT
            ORDER BY FLGLCD;
      COMMIT;
    END LOOP;
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('处理绩效考核月报表成功！');
    COMMIT;
  END IF;

  --每月初+3，处理健康管理供货企业增量
  IF TRUNC(SYSDATE) = LD_BBNY_JZRQ + 3 THEN
    BEGIN
      MERGE INTO JKGL_GY_GHQYXX A
           USING (SELECT DISTINCT T.GHFNSRSBH_1
                    FROM CKTS_SB_MTS_JHMX T
                   WHERE T.SBRQ>=LD_BBNY_KSRQ
                     AND T.GHFNSRSBH_1 IS NOT NULL) B
              ON (A.QYSBH=B.GHFNSRSBH_1)
            WHEN NOT MATCHED THEN
              INSERT (QYSBH,CR_TIME)
              VALUES (B.GHFNSRSBH_1,SYSDATE);
      COMMIT;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('增量JKGL_GY_GHQYXX处理成功！');
      COMMIT;
    END;
  END IF;

  --每月初+4，日常风险指标扫描
  IF TRUNC(SYSDATE) = LD_BBNY_JZRQ + 4 THEN
    PRO_FXGL_COMPUTE_MAIN;
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('日常风险指标扫描处理成功！');
    COMMIT;
  END IF;

  --每年初+5，处理GLXT_BB_SHXT_DJXX的出口规模等数据
  IF TRUNC(SYSDATE) = TRUNC(SYSDATE, 'YY') + 5 THEN
    PRO_DEAL_JCFX_NSR_BLV;
    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('GLXT_BB_SHXT_DJXX的出口规模等数据处理成功！');
    COMMIT;
  END IF;

  -- GLXT_BB_SHXT_LCXX数据处理
  BEGIN
    --增加新的企业申报信息
    INSERT INTO GLXT_BB_SHXT_LCXX(UUID,SWJGDM,ZBSWCODE,DJXH,CKQYGLLB_DM,SBYWB_DM,SB_YM,SB_PC,LCSLID,BJTS_DATE,SB_DATE,SL_DATE,SL_USER,USD_AMT,RMB_AMT,SB_TS_AMT,SB_MD_AMT,WZHBZ)
         SELECT T.UUID,T.TSSWJG_DM,T.TSSWJG_DM,T.DJXH,T.CKQYGLLB_DM,T.SBYWB_DM,T.SSQ,T.SBPC,T.LCSLID_SB,T.SBRQ,T.QDSJ,T.DYSLTZSJ,T.QDR_DM,T.SB_XSEMY,T.SB_XSERMB,T.SB_ZZSTSE+T.SB_XFSTSE,T.SB_MDSE,T.WZHBZ
           FROM CKTS_LC_SBXX T
          WHERE T.ZFBZ IS NULL
            AND T.SJTB_BZ='2'
            AND NOT EXISTS (SELECT 1 FROM GLXT_BB_SHXT_LCXX S WHERE S.UUID=T.UUID);
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.增加新的申报信息！');
      COMMIT;
    END IF;

    --删除已作废的流程
    DELETE FROM GLXT_BB_SHXT_LCXX T WHERE NOT EXISTS (SELECT 1 FROM CKTS_LC_SBXX S WHERE S.UUID=T.UUID AND NVL(S.ZFBZ,'N')='N');
    COMMIT;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.删除已作废流程！');
      COMMIT;
    END IF;

    --主流程未发放之前，更新主流程信息
    LN_I:=0;
    FOR CUR_LCXX IN (SELECT T.UUID,T.LCSLID,NVL(T.BJTS_DATE,T.SB_DATE) AS SB_DATE,T.SL_DATE,T.CKQYGLLB_DM FROM GLXT_BB_SHXT_LCXX T WHERE NVL(T.ZLC_FFRQ,DATE'2100-12-31')>=LD_DEALDATA)
    LOOP
      BEGIN
        V_SL_DATE := CUR_LCXX.SL_DATE;
        --SL_DATE IS NULL
        IF V_SL_DATE IS NULL THEN
          SELECT A.DYSLTZSJ
            INTO V_SL_DATE
            FROM CKTS_LC_SBXX A
           WHERE A.UUID=CUR_LCXX.UUID;
        END IF;
        --主流程复审数
        SELECT COUNT(1), NVL(SUM(S.FS_ZZSTSE+S.FS_XFSTSE),0), NVL(SUM(S.FS_MDSE),0), NVL(SUM(S.ZK_ZZSTSE+S.ZK_XFSTSE),0)
          INTO V_ZLC_FS, V_ZLC_TS_AMT, V_ZLC_MD_AMT, V_ZLC_ZK_AMT
          FROM CKTS_LC_YWHZXX S
         WHERE S.LCSLID_FS=CUR_LCXX.LCSLID;
        IF V_ZLC_FS=0 THEN
          --未复审，按主流程申报数以及发放时间
          SELECT NVL(SUM(S.SB_ZZSTSE+S.SB_XFSTSE),0), NVL(SUM(S.SB_MDSE),0), MIN(S.FFRQ)
            INTO V_ZLC_TS_AMT, V_ZLC_MD_AMT, V_FF_DATE
            FROM CKTS_LC_SHXX S
           WHERE S.LCSLID=CUR_LCXX.LCSLID;
          IF V_FF_DATE > SYSDATE THEN
            V_FF_DATE:=NULL;
          END IF;
          --如果已经发放且没有业务核准表，说明全部暂缓或不予了
          IF V_FF_DATE IS NOT NULL THEN
            V_ZLC_TS_AMT:=0;
            V_ZLC_MD_AMT:=0;
            IF V_SL_DATE IS NULL THEN
              V_SL_DATE:=V_FF_DATE;
            END IF;
          END IF;
          UPDATE GLXT_BB_SHXT_LCXX S
             SET S.ZLC_TS_AMT=V_ZLC_TS_AMT, S.ZLC_MD_AMT=V_ZLC_MD_AMT,
                 S.ZLC_FFRQ=V_FF_DATE,
                 S.SL_DATE=V_SL_DATE,
                 S.BLJZ_DATE=TL_BJTS.COMPUTE_BLJZDATE(CUR_LCXX.CKQYGLLB_DM, V_SL_DATE),
                 S.FH_DATE=V_FF_DATE,
                 S.SL_DAY=TL_BJTS.COMPUTE_BLDATE(V_SL_DATE, CUR_LCXX.SB_DATE),
                 S.SH_DAY=TL_BJTS.COMPUTE_BLDATE(V_FF_DATE, V_SL_DATE),
                 S.HZ_DAY=0,
                 S.KP_DAY=0
           WHERE S.UUID=CUR_LCXX.UUID;
          COMMIT;
        ELSE
          --已复审，取业务核准表的复审数
          SELECT FSRQ, FSR_DM, YWHZRQ, YWHZR_DM
            INTO V_FH_DATE, V_FH_USER, V_YWHZ_DATE, V_YWHZ_USER
            FROM (SELECT S.FSRQ, S.FSR_DM, S.YWHZRQ,S.YWHZR_DM
                    FROM CKTS_LC_YWHZXX S
                   WHERE S.LCSLID_FS=CUR_LCXX.LCSLID
                   ORDER BY S.FSRQ)
           WHERE ROWNUM=1;
          IF (V_FH_DATE > SYSDATE) OR (V_FH_DATE=DATE'1900-01-01') THEN
            V_FH_DATE:=NULL;
          END IF;
          IF (V_YWHZ_DATE > SYSDATE) OR (V_YWHZ_DATE=DATE'1900-01-01') THEN
            V_YWHZ_DATE:=NULL;
          END IF;
          IF V_ZLC_TS_AMT - V_ZLC_ZK_AMT <=0 THEN
            --复审退税额=0
            IF (V_YWHZ_DATE IS NULL) AND (V_FF_DATE IS NOT NULL) THEN
              V_YWHZ_DATE:=V_FF_DATE;
            END IF;
            IF (V_FH_DATE IS NULL) AND (V_YWHZ_DATE IS NOT NULL) THEN
              V_FH_DATE:=V_YWHZ_DATE;
            END IF;
            IF (V_SL_DATE IS NULL) AND (V_FH_DATE IS NOT NULL) THEN
              V_SL_DATE:=V_FH_DATE;
            END IF;
            UPDATE GLXT_BB_SHXT_LCXX S
               SET S.ZLC_TS_AMT=V_ZLC_TS_AMT, S.ZLC_MD_AMT=V_ZLC_MD_AMT,
                   S.ZLC_FFRQ=(SELECT R.FFRQ FROM CKTS_LC_SHXX R WHERE R.UUID=CUR_LCXX.UUID),
                   S.SL_DATE=V_SL_DATE,
                   S.BLJZ_DATE=TL_BJTS.COMPUTE_BLJZDATE(CUR_LCXX.CKQYGLLB_DM, V_SL_DATE),
                   S.FH_DATE=V_FH_DATE, S.FH_USER=V_FH_USER,
                   S.YWHZ_DATE=V_YWHZ_DATE, S.YWHZ_USER=V_YWHZ_USER,
                   S.SL_DAY=TL_BJTS.COMPUTE_BLDATE(V_SL_DATE, CUR_LCXX.SB_DATE),
                   S.SH_DAY=TL_BJTS.COMPUTE_BLDATE(V_FH_DATE, V_SL_DATE),
                   S.HZ_DAY=TL_BJTS.COMPUTE_BLDATE(V_YWHZ_DATE, V_FH_DATE),
                   S.KP_DAY=0
             WHERE S.UUID=CUR_LCXX.UUID;
            COMMIT;
            IF V_ZLC_MD_AMT>0 THEN
              BEGIN
                SELECT SEHZRQ, SEHZR_DM
                  INTO V_SEHZ_DATE, V_SEHZ_USER
                  FROM (SELECT S.SEHZRQ, S.SEHZR_DM
                          FROM CKTS_LC_SEHZXX S
                         WHERE S.LCSLID_FS=CUR_LCXX.LCSLID
                         ORDER BY SEHZRQ)
                 WHERE ROWNUM=1;
              EXCEPTION
                WHEN OTHERS THEN
                  V_SEHZ_DATE :=NULL;
                  V_SEHZ_USER :=NULL;
              END;
              UPDATE GLXT_BB_SHXT_LCXX S
                 SET S.SEHZ_DATE=V_SEHZ_DATE, S.SEHZ_USER=V_SEHZ_USER
               WHERE S.UUID=CUR_LCXX.UUID;
              COMMIT;
            END IF;
          ELSE
            --复审退税额<>0
            BEGIN
              SELECT SEHZRQ, SEHZR_DM, KPRQ, XHRQ
                INTO V_SEHZ_DATE, V_SEHZ_USER, V_TSKP_DATE, V_TSTK_DATE
                FROM (SELECT S.SEHZRQ, S.SEHZR_DM, S.KPRQ, (CASE WHEN S.SEHZ_ZZSTSE+S.BYHZ_ZZSTSE<>0 THEN S.XHRQ_TK ELSE S.XHRQ_XFS END) AS XHRQ
                        FROM CKTS_LC_SEHZXX S
                       WHERE S.LCSLID_FS=CUR_LCXX.LCSLID
                         AND S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE+S.BYHZ_ZZSTSE+S.BYHZ_XFSTSE<>0
                       ORDER BY SEHZRQ)
               WHERE ROWNUM=1;
            EXCEPTION
              WHEN OTHERS THEN
                V_SEHZ_DATE :=NULL;
                V_SEHZ_USER :=NULL;
                V_TSKP_DATE :=NULL;
                V_TSTK_DATE :=NULL;
            END;
            IF V_SEHZ_DATE > SYSDATE THEN
              V_SEHZ_DATE:=NULL;
            END IF;
            IF V_TSKP_DATE > SYSDATE THEN
              V_TSKP_DATE:=NULL;
            END IF;
            IF V_TSTK_DATE > SYSDATE THEN
              V_TSTK_DATE:=NULL;
            END IF;
            IF (V_YWHZ_DATE IS NULL) AND (V_SEHZ_DATE IS NOT NULL) THEN
              V_YWHZ_DATE:=V_SEHZ_DATE;
            END IF;
            IF (V_FH_DATE IS NULL) AND (V_YWHZ_DATE IS NOT NULL) THEN
              V_FH_DATE:=V_YWHZ_DATE;
            END IF;
            IF (V_SL_DATE IS NULL) AND (V_FH_DATE IS NOT NULL) THEN
              V_SL_DATE:=V_FH_DATE;
            END IF;
            UPDATE GLXT_BB_SHXT_LCXX S
               SET S.ZLC_TS_AMT=V_ZLC_TS_AMT, S.ZLC_MD_AMT=V_ZLC_MD_AMT,
                   S.ZLC_FFRQ=GREATEST(V_TSKP_DATE,(SELECT R.FFRQ FROM CKTS_LC_SHXX R WHERE R.UUID=CUR_LCXX.UUID)),
                   S.SL_DATE=V_SL_DATE,
                   S.BLJZ_DATE=TL_BJTS.COMPUTE_BLJZDATE(CUR_LCXX.CKQYGLLB_DM, V_SL_DATE),
                   S.FH_DATE=V_FH_DATE, S.FH_USER=V_FH_USER,
                   S.YWHZ_DATE=V_YWHZ_DATE, S.YWHZ_USER=V_YWHZ_USER,
                   S.SEHZ_DATE=V_SEHZ_DATE, S.SEHZ_USER=V_SEHZ_USER,
                   S.TSKP_DATE=V_TSKP_DATE, S.TSTK_DATE=V_TSTK_DATE,
                   S.SL_DAY=TL_BJTS.COMPUTE_BLDATE(V_SL_DATE, CUR_LCXX.SB_DATE),
                   S.SH_DAY=TL_BJTS.COMPUTE_BLDATE(V_FH_DATE, V_SL_DATE),
                   S.HZ_DAY=TL_BJTS.COMPUTE_BLDATE(V_SEHZ_DATE, V_FH_DATE),
                   S.KP_DAY=TL_BJTS.COMPUTE_BLDATE(V_TSKP_DATE, V_SEHZ_DATE)
             WHERE S.UUID=CUR_LCXX.UUID;
            COMMIT;
          END IF;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX S
           SET S.SUM_DAY=S.SH_DAY + S.HZ_DAY + S.KP_DAY
         WHERE S.UUID=CUR_LCXX.UUID;
        COMMIT;

        LN_I:=LN_I +1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.更新主流程信息！'||LN_I);
      COMMIT;
    END IF;

    -- 部分流程开票日期与退库日期差距较大，导致退库日期没有赋值，进行补偿
    FOR CUR_LCXX IN (SELECT T.UUID,T.LCSLID
                       FROM GLXT_BB_SHXT_LCXX T
                      WHERE T.TSKP_DATE>=LD_DEALDATA-7 AND T.TSKP_DATE<=LD_DEALDATA AND T.TSTK_DATE IS NULL)
    LOOP
      BEGIN
        BEGIN
          SELECT XHRQ
            INTO V_TSTK_DATE
            FROM (SELECT (CASE WHEN S.SEHZ_ZZSTSE+S.BYHZ_ZZSTSE<>0 THEN S.XHRQ_TK ELSE S.XHRQ_XFS END) AS XHRQ
                    FROM CKTS_LC_SEHZXX S
                   WHERE S.LCSLID_FS=CUR_LCXX.LCSLID
                     AND S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE+S.BYHZ_ZZSTSE+S.BYHZ_XFSTSE<>0
                   ORDER BY SEHZRQ)
           WHERE ROWNUM=1;
        EXCEPTION
          WHEN OTHERS THEN
            V_TSTK_DATE :=NULL;
        END;
        IF V_TSTK_DATE > SYSDATE THEN
          V_TSTK_DATE:=NULL;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX S
           SET S.TSTK_DATE=V_TSTK_DATE
         WHERE S.UUID=CUR_LCXX.UUID;
        COMMIT;
      END;
    END LOOP;

    --流程未全部结束的，更新总数流程信息
    LN_I:=0;
    FOR CUR_LCXX IN (SELECT T.UUID,T.SBYWB_DM,T.LCSLID,T.SB_DATE,T.SL_DATE,T.CKQYGLLB_DM FROM GLXT_BB_SHXT_LCXX T WHERE NVL(T.LCJSRQ,DATE'2100-12-31')>=LD_DEALDATA)
    LOOP
      BEGIN
        UPDATE GLXT_BB_SHXT_LCXX S
           SET (S.USD_AMT, S.RMB_AMT, S.SB_TS_AMT, S.SB_MD_AMT)=
               (SELECT R.SB_XSEMY, R.SB_XSERMB, R.SB_ZZSTSE+R.SB_XFSTSE, R.SB_MDSE
                  FROM CKTS_LC_SBXX R
                 WHERE R.UUID=CUR_LCXX.UUID)
         WHERE S.UUID=CUR_LCXX.UUID
           AND S.USD_AMT IS NULL;
        COMMIT;
        UPDATE GLXT_BB_SHXT_LCXX S
           SET (S.BYBL_AMT,S.BYTS_AMT,S.ZH_AMT,S.ZBBL_AMT,S.LCJSRQ)=
               (SELECT NVL(SUM(R.BYBL_MDTSE),0),NVL(SUM(R.BY_MDTSE),0),NVL(SUM(CASE WHEN R.LCSLID<>R.LCSLID_SB AND R.LCSLID_FS IS NULL THEN R.SB_MDTSE ELSE 0 END),0),
                       NVL(SUM(R.ZH_MDTSE),0), CASE WHEN MAX(R.LCJSRQ)>SYSDATE THEN NULL ELSE MAX(R.LCJSRQ) END
                  FROM CKTS_LC_SHXX R
                 WHERE R.LCSLID_SB=CUR_LCXX.LCSLID)
         WHERE S.UUID=CUR_LCXX.UUID;
        COMMIT;
        IF CUR_LCXX.SBYWB_DM='A0305001' THEN
          UPDATE GLXT_BB_SHXT_LCXX S
             SET (S.FH_TS_AMT,S.FH_MD_AMT,S.ZK_AMT)=
                 (SELECT NVL(SUM(R.FS_ZZSTSE+R.FS_XFSTSE),0),NVL(SUM(R.FS_MDSE),0),NVL(SUM(R.ZK_ZZSTSE+R.ZK_XFSTSE),0)
                    FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS =CUR_LCXX.LCSLID)
           WHERE S.UUID=CUR_LCXX.UUID;
          COMMIT;
          UPDATE GLXT_BB_SHXT_LCXX S
             SET (S.SEHZ_TS_AMT,S.SEHZ_MD_AMT,S.BYHZ_TS_AMT,S.BYHZ_MD_AMT,S.KP_TS_AMT,S.KP_MD_AMT,S.TK_TS_AMT,S.TK_MD_AMT)=
                 (SELECT NVL(SUM(R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE),0),NVL(SUM(R.SEHZ_MDSE),0),NVL(SUM(R.BYHZ_ZZSTSE+R.BYHZ_XFSTSE),0),NVL(SUM(R.BYHZ_MDSE),0),
                         NVL(SUM(CASE WHEN R.KPRQ<SYSDATE THEN R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE ELSE 0 END),0), NVL(SUM(R.GKBL_MDSE),0),
                         NVL(SUM(R.GKBL_ZZSTSE+R.GKBL_XFSTSE),0),NVL(SUM(R.GKBL_MDSE),0)
                    FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS =CUR_LCXX.LCSLID)
           WHERE S.UUID=CUR_LCXX.UUID;
          COMMIT;
        ELSE
          UPDATE GLXT_BB_SHXT_LCXX S
             SET (S.FH_TS_AMT,S.FH_MD_AMT,S.ZK_AMT)=
                 (SELECT NVL(SUM(R.FS_ZZSTSE+R.FS_XFSTSE),0),NVL(SUM(R.FS_MDSE),0),NVL(SUM(R.ZK_ZZSTSE+R.ZK_XFSTSE),0)
                    FROM CKTS_LC_YWHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=CUR_LCXX.LCSLID))
           WHERE S.UUID=CUR_LCXX.UUID;
          COMMIT;
          UPDATE GLXT_BB_SHXT_LCXX S
             SET (S.SEHZ_TS_AMT,S.SEHZ_MD_AMT,S.BYHZ_TS_AMT,S.BYHZ_MD_AMT,S.KP_TS_AMT,S.KP_MD_AMT,S.TK_TS_AMT,S.TK_MD_AMT)=
                 (SELECT NVL(SUM(R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE),0),NVL(SUM(R.SEHZ_MDSE),0),NVL(SUM(R.BYHZ_ZZSTSE+R.BYHZ_XFSTSE),0),NVL(SUM(R.BYHZ_MDSE),0),
                         NVL(SUM(CASE WHEN R.KPRQ<SYSDATE THEN R.SEHZ_ZZSTSE+R.SEHZ_XFSTSE ELSE 0 END),0), NVL(SUM(R.GKBL_MDSE),0),
                         NVL(SUM(R.GKBL_ZZSTSE+R.GKBL_XFSTSE),0),NVL(SUM(R.GKBL_MDSE),0)
                    FROM CKTS_LC_SEHZXX R
                   WHERE R.LCSLID_FS IN (SELECT LCSLID_FS FROM CKTS_LC_SHXX A WHERE A.LCSLID_SB=CUR_LCXX.LCSLID))
           WHERE S.UUID=CUR_LCXX.UUID;
          COMMIT;
        END IF;
        UPDATE GLXT_BB_SHXT_LCXX S
           SET S.YSFW_FLAG='Y'
         WHERE S.UUID=CUR_LCXX.UUID
           AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS R WHERE R.LCSLID_SB=CUR_LCXX.LCSLID
                       UNION ALL
                       SELECT 1 FROM CKTS_SB_MDT_YFSJ U WHERE U.LCSLID_SB=CUR_LCXX.LCSLID
                       UNION ALL
                       SELECT 1 FROM CKTS_SB_MTS_YSFW V WHERE V.LCSLID_SB=CUR_LCXX.LCSLID);
        COMMIT;
        LN_I:=LN_I +1;
      END;
    END LOOP;
    IF LN_LOG>1 THEN
      INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('             GLXT_BB_SHXT_LCXX.更新流程总退税信息！'||LN_I);
      COMMIT;
    END IF;

    INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('同步GLXT_BB_SHXT_LCXX处理成功！');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      LC_SBYY:=SQLERRM;
      INSERT INTO CKTS_LOG_DEALDATA(CZJL,SBYY) VALUES ('同步GLXT_BB_SHXT_LCXX处理失败！', LC_SBYY);
      COMMIT;
  END;

  --报关单征免退税性质处理
  FOR CUR_BGD IN (SELECT T.CKBGDH,T.DJXH,T.CKRQ_1,T.CKSP_DM,T.JGFS_DM,T.HZDWDQ_DM,NVL(S.JSMODE,'9') AS JSMODE
                    FROM CKTS_WBSJ_HG_BGD T
                    LEFT JOIN GLXT_BB_SHXT_DJXX S ON S.DJXH_JS=T.DJXH
                   WHERE T.SJTB_SJ>=LD_DEALDATA)
  LOOP
    BEGIN
      SELECT S.XZQH_DM
        INTO V_HYDXZQH_DM
        FROM TL_BJTS.DM_HGHYD S
       WHERE S.HGHYD_DM=CUR_BGD.HZDWDQ_DM
         AND ROWNUM=1;
    EXCEPTION
      WHEN OTHERS THEN
        --找不到对应的基本商品
        V_HYDXZQH_DM :='0000';
    END;

    BEGIN
      SELECT CKSPTSSPLX_DM,TSL
        INTO V_CKSPTSSPLX_DM, V_TSL
        FROM (SELECT CKSPTSSPLX_DM,TSL
                FROM (SELECT NVL(A.CKSPTSSPLX_DM,'0') AS CKSPTSSPLX_DM,A.TSL
                        FROM TL_BJTS.CKTS_DM_TSLVWK A
                       WHERE A.CKSP_DM LIKE CUR_BGD.CKSP_DM||'%' AND (CUR_BGD.CKRQ_1 BETWEEN A.YXQQ AND A.YXQZ) AND A.JBSPBZ='Y'
                       UNION ALL
                      SELECT NVL(B.CKSPTSSPLX_DM,'0') AS CKSPTSSPLX_DM,B.TSL
                        FROM TL_BJTS.CKTS_DM_TSLVWK B
                       WHERE B.CKSP_DM = SUBSTR(CUR_BGD.CKSP_DM,1,8) AND (CUR_BGD.CKRQ_1 BETWEEN B.YXQQ AND B.YXQZ) AND B.JBSPBZ='Y'
                      ) S
               ORDER BY TSL DESC) R
       WHERE ROWNUM=1;
    EXCEPTION
      WHEN OTHERS THEN
        --找不到对应的基本商品
        V_CKSPTSSPLX_DM :='0';
        V_TSL :=0;
    END;

    BEGIN
      SELECT JGFSTSLX_DM
        INTO V_JGFSTSLX_DM
        FROM TL_BJTS.CKTS_DM_HGJGFS A
       WHERE A.JGFS_DM=CUR_BGD.JGFS_DM;
    EXCEPTION
      WHEN OTHERS THEN
        V_JGFSTSLX_DM :='1';
    END;

    UPDATE CKTS_WBSJ_HG_BGD S
       SET S.HYDXZQH_DM=V_HYDXZQH_DM,
           S.ZMTBZ=CASE WHEN CUR_BGD.JGFS_DM IN ('0214','0255') THEN '2' --来料加工复出口业务，免税
                        WHEN V_CKSPTSSPLX_DM='1' THEN '1' --征税
                        WHEN V_CKSPTSSPLX_DM='2' THEN '2' --免税
                        WHEN V_JGFSTSLX_DM='0' THEN '0' --监管方式不退税
                        WHEN CUR_BGD.JSMODE IN ('3','9') THEN '3' --退税计算方式不退税
                        ELSE 'T' END, --退税
           S.TSL=CASE WHEN CUR_BGD.JGFS_DM IN ('0214','0255') THEN 0 --来料加工复出口业务，免税
                        WHEN V_CKSPTSSPLX_DM='1' THEN 0 --征税
                        WHEN V_CKSPTSSPLX_DM='2' THEN 0 --免税
                        WHEN V_JGFSTSLX_DM='0' THEN 0 --监管方式不退税
                        WHEN CUR_BGD.JSMODE IN ('3','9') THEN 0 --退税计算方式不退税
                        ELSE V_TSL END
     WHERE S.CKBGDH=CUR_BGD.CKBGDH AND S.DJXH=CUR_BGD.DJXH;
    COMMIT;
  END LOOP;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('CKTS_WBSJ_HG_BGD更新征免税标志完成！');
  COMMIT;

  -- 监测分析数据处理
  PRO_DEAL_JCFX_NSR_BADJ;
  --PRO_DEAL_JCFX_DATA_BGDMX;
  PRO_DEAL_JCFX_DATA_TSSBMX;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_JCFX_DATA_*成功！');
  COMMIT;

  -- 风险出口数据处理
  PRO_FXGL_FXSPCK_DZXX;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('风险出口数据处理成功！');
  COMMIT;
  
  -- 海外仓预退税企业处理
  PRO_DEAL_HWCYTS;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('海外仓预退税企业处理成功！');
  COMMIT;
  
  -- 绍兴报关单物流信息（车牌号、起运日期、起运地）提取
  PRO_FXGL_SZYJ_WLXX;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('报关单物流信息处理成功！');
  COMMIT;
  
  -- 长期未申报出口业务退税清理
  FOR CUR_CQWSB IN (SELECT S.DJXH,S.CKBGDH,S.CYTSSBJL
                      FROM RCGL_CQWSB_DATA S
                     WHERE S.QYQR_ZT='3' AND S.JS_ZT='1' AND S.SWSH_ZT='1' AND S.YSB_TSE IS NULL)
  LOOP
    IF SUBSTR(CUR_CQWSB.CYTSSBJL,5,3)='133' THEN
      -- 代理证明，退运证明
      LN_ZZS:=0;
      LN_MDSE:=0;
    ELSE
      --退税申报
      BEGIN
        SELECT SUM(TSE), SUM(MDE)
          INTO LN_ZZS, LN_MDSE
          FROM (SELECT SUM(A.TMSE) AS TSE, 0 AS MDE
                  FROM JCFX_DATA_TSSBMX A
                 WHERE A.DJXH=CUR_CQWSB.DJXH
                   AND A.CKBGDH=CUR_CQWSB.CKBGDH
                   AND A.SBYWLX<>'1'
                 UNION ALL
                SELECT SUM(ROUND(A.TMSE * CASE WHEN B.MDTSEHJ<=0 THEN 0 ELSE B.YTSE_1/B.MDTSEHJ END, 2)) AS TSE,
                       SUM(A.TMSE) - SUM(ROUND(A.TMSE * CASE WHEN B.MDTSEHJ<=0 THEN 0 ELSE B.YTSE_1/B.MDTSEHJ END, 2)) AS MDE
                  FROM JCFX_DATA_TSSBMX A
                 INNER JOIN CKTS_SB_MDT_SBDSHZ B ON B.LCSLID=A.LCSLID
                 WHERE A.DJXH=CUR_CQWSB.DJXH
                   AND A.CKBGDH=CUR_CQWSB.CKBGDH
                   AND A.SBYWLX='1');
      EXCEPTION
        WHEN OTHERS THEN
          --找不到对应的记录，可能未复审、不予办理
          LN_ZZS:=NULL;
          LN_MDSE:=NULL;
      END;
    END IF;
    IF LN_ZZS IS NOT NULL THEN
      UPDATE RCGL_CQWSB_DATA T
         SET T.YSB_TSE=LN_ZZS,
             T.YSB_MDE=LN_MDSE
       WHERE T.DJXH=CUR_CQWSB.DJXH
         AND T.CKBGDH=CUR_CQWSB.CKBGDH;
      COMMIT;
    END IF;
  END LOOP;
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('长期未申报出口业务退税清理成功！');
  COMMIT;
  
  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_AFTER_ETL处理成功！');
  COMMIT;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_JCFX_DATA_BGDMX
prompt ===========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_DATA_BGDMX
AS
  V_BEGINDATE      DATE;
  V_TSSWJG_DM      VARCHAR2(11);
  V_CKSPTSSPLX_DM  CHAR(1);
  V_TSL            NUMBER(18,2);
  V_JGFSTSLX_DM    CHAR(1);
  V_HYDXZQH_DM     CHAR(4);
  LN_ROWS          NUMBER(10);
  LN_REC           NUMBER(10);
  LN_UNIT          NUMBER(10);
BEGIN
  SELECT TRUNC(MAX(T.SJGXSJ))
    INTO V_BEGINDATE
    FROM JCFX_DATA_BGDMX T;
  
  SELECT COUNT(1)
    INTO LN_ROWS
    FROM CKTS_WBSJ_HG_BGD T
   WHERE T.SJTB_SJ>=V_BEGINDATE;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_JCFX_DATA_BGDMX 开始运行，记录总数：' || LN_ROWS);
  COMMIT;
  
  --增量用数据更新时间
  LN_REC :=0;
  LN_UNIT:=0;
  FOR CUR_BGD IN (SELECT T.UUID,T.TSSWJG_DM_1,T.DJXH,T.CKBGDH,T.CKNY,T.CKRQ_1,T.CKSP_DM,
                         T.HGGQKA_DM,T.MYGDQSZ_DM,T.JGFS_DM,T.HZDWDQ_DM,
                         T.CKSL,T.MYLAJ,T.RMBLAJ,T.TSSBSL,T.DLSBSL,T.TYSL,
                         CASE WHEN T.TSSBSL+T.DLSBSL+T.TYSL>T.CKSL+1 THEN T.CKSL / (T.TSSBSL+T.DLSBSL+T.TYSL) ELSE 1 END 
                           * (T.TSSBMYLAJ + T.DLSBMYLAJ + T.TYMYLAJ) AS MYLAJ_YSB,
                         T.SJTB_SJ
                    FROM CKTS_WBSJ_HG_BGD T
                   WHERE T.SJTB_SJ>=V_BEGINDATE)
  LOOP
    BEGIN
      SELECT A.TSSWJG_DM
        INTO V_TSSWJG_DM
        FROM JCFX_DATA_BGDMX A
       WHERE A.DJXH=CUR_BGD.DJXH AND A.CKBGDH=CUR_BGD.CKBGDH;
      
      IF V_TSSWJG_DM=CUR_BGD.TSSWJG_DM_1 THEN
        UPDATE JCFX_DATA_BGDMX A
           SET A.UUID=CUR_BGD.UUID, A.NY=CUR_BGD.CKNY, A.CKRQ=CUR_BGD.CKRQ_1, A.CKSP_DM=CUR_BGD.CKSP_DM, 
               A.HGGQKA_DM=CUR_BGD.HGGQKA_DM, A.MYGDQSZ_DM=CUR_BGD.MYGDQSZ_DM, A.JGFS_DM=CUR_BGD.JGFS_DM, A.HZDWDQ_DM=CUR_BGD.HZDWDQ_DM,
               A.MYLAJ=CUR_BGD.MYLAJ, A.RMBLAJ=CUR_BGD.RMBLAJ, A.MYLAJ_YSB=CUR_BGD.MYLAJ_YSB, A.SJGXSJ=CUR_BGD.SJTB_SJ
         WHERE A.DJXH=CUR_BGD.DJXH AND A.CKBGDH=CUR_BGD.CKBGDH;
        COMMIT;
      ELSE
        DELETE FROM JCFX_DATA_BGDMX A WHERE A.DJXH=CUR_BGD.DJXH AND A.CKBGDH=CUR_BGD.CKBGDH;
        COMMIT;
        INSERT INTO JCFX_DATA_BGDMX(UUID,TSSWJG_DM,DJXH,CKBGDH,NY,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,MYLAJ,RMBLAJ,MYLAJ_YSB,SJGXSJ)
             VALUES (CUR_BGD.UUID,CUR_BGD.TSSWJG_DM_1,CUR_BGD.DJXH,CUR_BGD.CKBGDH,CUR_BGD.CKNY,CUR_BGD.CKRQ_1,CUR_BGD.CKSP_DM,CUR_BGD.HGGQKA_DM,CUR_BGD.MYGDQSZ_DM,CUR_BGD.JGFS_DM,CUR_BGD.HZDWDQ_DM,CUR_BGD.MYLAJ,CUR_BGD.RMBLAJ,CUR_BGD.MYLAJ_YSB,CUR_BGD.SJTB_SJ);
        COMMIT;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        --找不到对应的基本商品
        INSERT INTO JCFX_DATA_BGDMX(UUID,TSSWJG_DM,DJXH,CKBGDH,NY,CKRQ,CKSP_DM,HGGQKA_DM,MYGDQSZ_DM,JGFS_DM,HZDWDQ_DM,MYLAJ,RMBLAJ,MYLAJ_YSB,SJGXSJ)
             VALUES (CUR_BGD.UUID,CUR_BGD.TSSWJG_DM_1,CUR_BGD.DJXH,CUR_BGD.CKBGDH,CUR_BGD.CKNY,CUR_BGD.CKRQ_1,CUR_BGD.CKSP_DM,CUR_BGD.HGGQKA_DM,CUR_BGD.MYGDQSZ_DM,CUR_BGD.JGFS_DM,CUR_BGD.HZDWDQ_DM,CUR_BGD.MYLAJ,CUR_BGD.RMBLAJ,CUR_BGD.MYLAJ_YSB,CUR_BGD.SJTB_SJ);
        COMMIT;
    END;

    BEGIN
      SELECT S.XZQH_DM
        INTO V_HYDXZQH_DM
        FROM TL_BJTS.DM_HGHYD S 
       WHERE S.HGHYD_DM=CUR_BGD.HZDWDQ_DM
         AND ROWNUM=1;
    EXCEPTION
      WHEN OTHERS THEN
        --找不到对应的基本商品
        V_HYDXZQH_DM :='0000';
    END;

    BEGIN
      SELECT CKSPTSSPLX_DM,TSL
        INTO V_CKSPTSSPLX_DM, V_TSL
        FROM (SELECT CKSPTSSPLX_DM,TSL
                FROM (SELECT NVL(A.CKSPTSSPLX_DM,'0') AS CKSPTSSPLX_DM,A.TSL
                        FROM TL_BJTS.CKTS_DM_TSLVWK A
                       WHERE A.CKSP_DM LIKE CUR_BGD.CKSP_DM||'%' AND (CUR_BGD.CKRQ_1 BETWEEN A.YXQQ AND A.YXQZ) AND A.JBSPBZ='Y'
                       UNION ALL
                      SELECT NVL(B.CKSPTSSPLX_DM,'0') AS CKSPTSSPLX_DM,B.TSL
                        FROM TL_BJTS.CKTS_DM_TSLVWK B
                       WHERE B.CKSP_DM = SUBSTR(CUR_BGD.CKSP_DM,1,8) AND (CUR_BGD.CKRQ_1 BETWEEN B.YXQQ AND B.YXQZ) AND B.JBSPBZ='Y'
                      ) S
               ORDER BY TSL DESC) R
       WHERE ROWNUM=1;
    EXCEPTION
      WHEN OTHERS THEN
        --找不到对应的基本商品
        V_CKSPTSSPLX_DM :='0';
        V_TSL :=0;
    END;
      
    BEGIN
      SELECT JGFSTSLX_DM
        INTO V_JGFSTSLX_DM
        FROM TL_BJTS.CKTS_DM_HGJGFS A
       WHERE A.JGFS_DM=CUR_BGD.JGFS_DM;
    EXCEPTION
      WHEN OTHERS THEN
        V_JGFSTSLX_DM :='1';
    END;
      
    IF V_CKSPTSSPLX_DM='1' THEN
      UPDATE JCFX_DATA_BGDMX T
         SET T.MYLAJ_ZS=T.MYLAJ, T.HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=CUR_BGD.DJXH AND T.CKBGDH=CUR_BGD.CKBGDH;
    ELSIF V_CKSPTSSPLX_DM='2' THEN
      UPDATE JCFX_DATA_BGDMX T
         SET T.MYLAJ_MS=T.MYLAJ, T.HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=CUR_BGD.DJXH AND T.CKBGDH=CUR_BGD.CKBGDH;
    ELSIF V_JGFSTSLX_DM='0' THEN
      UPDATE JCFX_DATA_BGDMX T
         SET T.MYLAJ_BTS=T.MYLAJ, T.HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=CUR_BGD.DJXH AND T.CKBGDH=CUR_BGD.CKBGDH;
    ELSE
      UPDATE JCFX_DATA_BGDMX T
         SET T.MYLAJ_KTS=T.MYLAJ, T.TSL=V_TSL, T.YGTMSE=ROUND(T.RMBLAJ * V_TSL / 100,2), T.HYDXZQH_DM=V_HYDXZQH_DM
       WHERE T.DJXH=CUR_BGD.DJXH AND T.CKBGDH=CUR_BGD.CKBGDH;
    END IF;
    COMMIT;
  END LOOP;

  INSERT INTO CKTS_LOG_DEALDATA(CZJL) VALUES ('PRO_DEAL_JCFX_DATA_BGDMX 处理结束！');
  COMMIT;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_JCFX_DATA_QYYHZ_INIT
prompt ================================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_DATA_QYYHZ_INIT
/*
 * 每月月初，取JCFX_NSR_BADJ_TOHZ表中记录并初始化JCFX_DATA_QYYHZ
 */
AS
  LD_ENDMONTH          DATE;             --上上月，汇总截止月份，老企业汇总起始月份
  LD_DEALMONTH         DATE;             --按月汇总的控制时间（月初）
  LD_NEXTMONTH         DATE;             --按月汇总的控制时间（下月初）
  LC_NY                VARCHAR2(6);      --开票月份，财务报表、纳税申报表所属期止月份，免抵退申报所属期或免退税申报月份
  LD_NEWMONTH          DATE;             --新增商品、供应商的控制时间（月初）
  LC_NEWNY             VARCHAR2(6);      --新增商品、供应商的控制时间（月份）
  --JCFX_DATA_QYYHZ.ck
  LN_CK_SB_XSEMY        NUMBER(18,2);     --出口_销售美元
  LN_CK_SB_XSERMB       NUMBER(18,2);     --出口_销售人民币
  LN_CK_SB_JSJE         NUMBER(18,2);     --出口_计税金额
  LN_CK_SB_JHCB         NUMBER(18,2);     --出口_进货成本
  LN_CK_SB_TSE          NUMBER(18,2);     --出口_申报退税
  LN_CK_SB_MDE          NUMBER(18,2);     --出口_申报免抵
  LN_CK_HZ_TSE          NUMBER(18,2);     --出口_核准退税
  LN_CK_HZ_MDE          NUMBER(18,2);     --出口_核准免抵
  LN_CK_BL_TSE          NUMBER(18,2);     --出口_办理退税
  LN_CK_BL_MDE          NUMBER(18,2);     --出口_办理免抵
  LN_CK_XZSP_CKE        NUMBER(18,2);     --出口_新增商品出口额
  LN_CK_XZGHS_JSJE      NUMBER(18,2);     --出口_新增供应商计税金额
  LN_CK_TSSP_CKE        NUMBER(18,2);     --出口_特殊商品出口额
  LN_CK_MGSP_CKE        NUMBER(18,2);     --出口_敏感商品出口额
  LN_CK_MGKA_CKE        NUMBER(18,2);     --出口_敏感口岸出口额
  LN_CNT                INTEGER;          --统计数
BEGIN
  FOR CUR_NSR IN (SELECT DJXH,NSRSBH,NVL(SHXYDM,NSRSBH) AS SHXYDM,SWJGDM,JLXZSJ,BACHSJ,JCFXSJ FROM JCFX_NSR_BADJ_TOHZ)
  LOOP
    IF CUR_NSR.JCFXSJ IS NULL THEN --根据上一次监测分析时间是否为空判定是否新增企业
      LD_DEALMONTH:=ADD_MONTHS(TRUNC(CUR_NSR.JLXZSJ,'YY'),-24); --新增企业汇总起始月份，上上年
    ELSE
      BEGIN
        SELECT TO_DATE(MAX(S.NY)||'01','YYYYMMDD')
          INTO LD_DEALMONTH
          FROM JCFX_DATA_QYYHZ S
          WHERE S.DJXH=CUR_NSR.DJXH;
      EXCEPTION
        WHEN OTHERS THEN
          LD_DEALMONTH := NULL;
      END;
      IF LD_DEALMONTH IS NULL THEN
        LD_DEALMONTH:=ADD_MONTHS(TRUNC(CUR_NSR.JCFXSJ,'MM'),-2); --老企业汇总起始月份，上上月
      END IF;
    END IF;
    -- 终止月份，上上月、备案撤回月份（未撤回按系统日期比较）较小者
    LD_ENDMONTH:=LEAST(ADD_MONTHS(TRUNC(SYSDATE,'MM'),-2),TRUNC(NVL(CUR_NSR.BACHSJ,SYSDATE),'MM'));
    
    --DEBUG
    LOOP
      EXIT WHEN LD_DEALMONTH > LD_ENDMONTH;
      --日期赋值
      LD_NEXTMONTH:=ADD_MONTHS(LD_DEALMONTH,1);
      LC_NY:=TO_CHAR(LD_DEALMONTH,'YYYYMM');
      LD_NEWMONTH:=ADD_MONTHS(LD_DEALMONTH,-6);
      LC_NEWNY:=TO_CHAR(LD_NEWMONTH,'YYYYMM');

      --JCFX_DATA_QYYHZ
      BEGIN
        SELECT COUNT(*) INTO LN_CNT FROM JCFX_DATA_QYYHZ T WHERE T.DJXH=CUR_NSR.DJXH AND T.NY=LC_NY;
        IF LN_CNT = 0 THEN
          INSERT INTO JCFX_DATA_QYYHZ(DJXH,NY,NSRSBH,SHXYDM)
          VALUES(CUR_NSR.DJXH,LC_NY,CUR_NSR.NSRSBH,CUR_NSR.SHXYDM);
          COMMIT;
        END IF;

        SELECT COUNT(*) INTO LN_CNT FROM JCFX_DATA_QYYHZ T WHERE T.DJXH=CUR_NSR.DJXH AND T.NY=LC_NY AND NVL(T.BJTS_ZT,'N') <> 'Y';
        --本地BJTS抽取
        IF LN_CNT > 0 THEN
          --LN_CK_SB_XSEMY,LN_CK_SB_XSERMB,LN_CK_SB_JSJE,LN_CK_SB_JHCB
          BEGIN
            SELECT NVL(SUM(XSEMY),0),NVL(SUM(XSERMB),0),NVL(SUM(JSJE),0),NVL(SUM(JHCB),0)
              INTO LN_CK_SB_XSEMY, LN_CK_SB_XSERMB, LN_CK_SB_JSJE, LN_CK_SB_JHCB
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.RMBLAJ) AS XSERMB, SUM(T.RMBLAJ) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.YSFWYYEMY) AS XSEMY, SUM(T.YSFWYYERMB) AS XSERMB, SUM(T.YSFWYYERMB) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_YFSJ T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.YSFWYYEMY) AS XSEMY, SUM(T.YSFWYYERMB) AS XSERMB, SUM(T.YSFWYYERMB) AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_GJYS T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.MYLAJ * R.RMBLAJ / R.MYLAJ) AS XSERMB, 0 AS JSJE, 0 AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=CUR_NSR.DJXH AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT 0 AS XSEMY, 0 AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_JHMX T ON T.LCSLID_SB=S.LCSLID_SB AND T.SZ='V'
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.SKJEMY) AS XSEMY, SUM(T.BQQRYSFWYYSRRMBJE) AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_YSFW T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY, SUM(T.MYLAJ * R.RMBLAJ / R.MYLAJ) AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=CUR_NSR.DJXH AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT SUM(R.MYLAJ) AS XSEMY, SUM(R.RMBLAJ) AS XSERMB, SUM(T.SBZYJZ) AS JSJE, SUM(T.SBZYJZ * (100+T.ZSSL-T.TSL) / 100) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_YS_SBMX T ON T.LCSLID=S.LCSLID_SB
                     INNER JOIN CKTS_WBSJ_HG_BGD R ON R.DJXH=CUR_NSR.DJXH AND R.CKBGDH=T.CKBGDH
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0303001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                     UNION ALL
                    SELECT 0 AS XSEMY, 0 AS XSERMB, SUM(T.JSJE) AS JSJE, SUM(T.JSJE) AS JHCB
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_GJ_SBMX T ON T.LCSLID=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0304001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_SB_XSEMY  :=0;
              LN_CK_SB_XSERMB :=0;
              LN_CK_SB_JSJE :=0;
              LN_CK_SB_JHCB :=0;
          END;

          --LN_CK_SB_TSE,LN_CK_SB_MDE
          SELECT NVL(SUM(S.SB_ZZSTSE+S.SB_XFSTSE),0),NVL(SUM(S.SB_MDSE),0)
            INTO LN_CK_SB_TSE,LN_CK_SB_MDE
            FROM CKTS_LC_SBXX S
           WHERE S.DJXH=CUR_NSR.DJXH
             AND ((S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY) OR ( S.SBYWB_DM<>'A0305001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH))
             AND S.ZFBZ IS NULL;

          --LN_CK_HZ_TSE,LN_CK_HZ_MDE
          SELECT NVL(SUM(S.SEHZ_ZZSTSE+S.SEHZ_XFSTSE),0),NVL(SUM(S.SEHZ_MDSE),0)
            INTO LN_CK_HZ_TSE,LN_CK_HZ_MDE
            FROM CKTS_LC_SEHZXX S
           WHERE S.DJXH=CUR_NSR.DJXH AND S.SEHZRQ>=LD_DEALMONTH AND S.SEHZRQ<LD_NEXTMONTH;

          --LN_CK_BL_TSE
          SELECT NVL(SUM(S.SE),0)
            INTO LN_CK_BL_TSE
            FROM CKTS_ZS_SRTHS S
           WHERE S.DJXH=CUR_NSR.DJXH AND S.THRQ_1>=LD_DEALMONTH AND S.THRQ_1<LD_NEXTMONTH AND S.TTSJLX_DM='01' AND S.TZLX_DM IN ('1','4');

          --LN_CK_BL_MDE
          SELECT NVL(SUM(S.JE),0)
            INTO LN_CK_BL_MDE
            FROM CKTS_ZS_TKGZ S
           WHERE S.DJXH=CUR_NSR.DJXH AND S.GKGZRQ>=LD_DEALMONTH AND S.GKGZRQ<LD_NEXTMONTH AND S.TZSLY='3' AND S.TZLX_DM='1' AND S.GZBZ='Y';

          --LN_CK_XZSP_CKE             --出口_新增商品出口额
          BEGIN
            SELECT NVL(SUM(XSEMY),0)
              INTO LN_CK_XZSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MDT_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=CUR_NSR.DJXH AND S1.SBYWB_DM='A0305001' AND S1.SSQ>=LC_NEWNY AND S1.SSQ<LC_NY AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE SUBSTR(T.CKSP_DM,1,4)||'%')
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MTS_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=CUR_NSR.DJXH AND S1.SBYWB_DM='A0301001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE SUBSTR(T.CKSP_DM,1,4)||'%')
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_WZF_CKMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=CUR_NSR.DJXH AND S1.SBYWB_DM='A0310001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.CKSP_DM LIKE SUBSTR(T.CKSP_DM,1,4)||'%'
                                          AND T1.WTDBTSSCQYNSRSBH=T.WTDBTSSCQYNSRSBH) ) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_XZSP_CKE  :=0;
          END;

          --LN_CK_XZGHS_JSJE           --出口_新增供应商计税金额
          BEGIN
            SELECT NVL(SUM(JSJE),0)
              INTO LN_CK_XZGHS_JSJE
              FROM (SELECT SUM(T.JSJE) AS JSJE
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_JHMX T ON T.LCSLID_SB=S.LCSLID_SB AND T.SZ='V'
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND NOT EXISTS (SELECT 1
                                         FROM CKTS_LC_SBXX S1
                                        INNER JOIN CKTS_SB_MTS_JHMX T1 ON T1.LCSLID_SB=S1.LCSLID_SB
                                        WHERE S1.DJXH=CUR_NSR.DJXH AND S1.SBYWB_DM='A0301001' AND S1.SBRQ>=LD_NEWMONTH AND S1.SBRQ<LD_DEALMONTH AND S1.ZFBZ IS NULL
                                          AND T1.GHFNSRSBH_1=T.GHFNSRSBH_1) ) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_XZGHS_JSJE  :=0;
          END;

          --LN_CK_TSSP_CKE             --出口_特殊商品出口额
          BEGIN
            SELECT NVL(SUM(XSEMY),0)
              INTO LN_CK_TSSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_TSSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM) ) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_TSSP_CKE  :=0;
          END;

          --LN_CK_MGSP_CKE             --出口_敏感商品出口额
          BEGIN
            SELECT NVL(SUM(XSEMY),0)
              INTO LN_CK_MGSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.CKSP_DM IN (SELECT R.CKSP_DM FROM JCFX_CS_MGSP R WHERE R.SWJGDM=CUR_NSR.SWJGDM) ) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_MGSP_CKE  :=0;
          END;

          --LN_CK_MGKA_CKE             --出口_敏感口岸出口额
          BEGIN
            SELECT NVL(SUM(XSEMY),0)
              INTO LN_CK_MGSP_CKE
              FROM (SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MDT_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0305001' AND S.SSQ=LC_NY AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_MTS_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0301001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=CUR_NSR.SWJGDM)
                     UNION ALL
                    SELECT SUM(T.MYLAJ) AS XSEMY
                      FROM CKTS_LC_SBXX S
                     INNER JOIN CKTS_SB_WZF_CKMX T ON T.LCSLID_SB=S.LCSLID_SB
                     WHERE S.DJXH=CUR_NSR.DJXH AND S.SBYWB_DM='A0310001' AND S.SBRQ>=LD_DEALMONTH AND S.SBRQ<LD_NEXTMONTH AND S.ZFBZ IS NULL
                       AND T.HGCODE IN (SELECT R.HGGQKA_DM FROM JCFX_CS_MGKA R WHERE R.SWJGDM=CUR_NSR.SWJGDM) ) TT;
          EXCEPTION
            WHEN OTHERS THEN
              LN_CK_MGSP_CKE  :=0;
          END;

          UPDATE JCFX_DATA_QYYHZ A
             SET CK_SB_XSEMY=LN_CK_SB_XSEMY,
                 CK_SB_XSERMB=LN_CK_SB_XSERMB,
                 CK_SB_JSJE=LN_CK_SB_JSJE,
                 CK_SB_JHCB=LN_CK_SB_JHCB,
                 CK_SB_TSE=LN_CK_SB_TSE,
                 CK_SB_MDE=LN_CK_SB_MDE,
                 CK_HZ_TSE=LN_CK_HZ_TSE,
                 CK_HZ_MDE=LN_CK_HZ_MDE,
                 CK_BL_TSE=LN_CK_BL_TSE,
                 CK_BL_MDE=LN_CK_BL_MDE,
                 CK_XZSP_CKE=LN_CK_XZSP_CKE,
                 CK_XZGHS_JSJE=LN_CK_XZGHS_JSJE,
                 CK_TSSP_CKE=LN_CK_TSSP_CKE,
                 CK_MGSP_CKE=LN_CK_MGSP_CKE,
                 CK_MGKA_CKE=LN_CK_MGKA_CKE,
                 BJTS_ZT='Y',
                 BJTS_SJ=SYSDATE,
                 SJGXSJ=SYSDATE
          WHERE DJXH=CUR_NSR.DJXH AND NY=LC_NY;
          COMMIT;

        END IF;
      END;

      LD_DEALMONTH:=LD_NEXTMONTH;
    END LOOP;

    UPDATE JCFX_NSR_BADJ_TOHZ SET JCFXSJ = SYSDATE WHERE DJXH=CUR_NSR.DJXH;
    COMMIT;
  END LOOP;

  DBMS_OUTPUT.put_line('检测分析初始化完成');
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DEAL_JCFX_NSR_BADJ_BLV
prompt =============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DEAL_JCFX_NSR_BADJ_BLV
(
  V_YEAR IN VARCHAR2
)
AS
  LN_QBXSE         NUMBER(18,2);
  LN_CKXSE         NUMBER(18,2);
  LN_CKGM          NUMBER(18,2);
  LN_SBMDE         NUMBER(18,2);
  LN_SBMDTSE       NUMBER(18,2);
  LN_SBSF          NUMBER(18,2);
  LN_CKBLV         NUMBER(10,6);
  LN_MDBLV         NUMBER(10,6);
  LN_SFBLV         NUMBER(10,6);
  LC_CKBLV         VARCHAR(1);
  LC_CKGM          VARCHAR(1);
  LC_MDBLV         VARCHAR(1);
  LC_SFBLV         VARCHAR(1);
BEGIN
  IF V_YEAR IS NULL THEN 
    RETURN;
  END IF;
  
  --根据审核信息设置LCTJJC
  FOR CUR_NSR IN (SELECT T.DJXH
                    FROM TL_TSSH.JCFX_NSR_BADJ T)
  LOOP
    SELECT NVL(SUM(S.ZZS_QBXSSR),0), NVL(SUM(S.CK_SB_XSERMB),0), NVL(SUM(S.CK_SB_XSEMY),0), NVL(SUM(S.CK_SB_MDE),0), NVL(SUM(S.CK_SB_TSE+S.CK_SB_MDE),0), NVL(SUM(S.ZZS_YNSE+S.CK_SB_MDE),0)
      INTO LN_QBXSE, LN_CKXSE, LN_CKGM, LN_SBMDE, LN_SBMDTSE, LN_SBSF
      FROM TL_TSSH.JCFX_DATA_QYYHZ S 
     WHERE S.DJXH=CUR_NSR.DJXH AND S.NY LIKE V_YEAR || '%';
    
    IF LN_QBXSE<=0 THEN
      IF LN_CKXSE<=0 THEN
        LN_CKBLV := 0;
      ELSE
        LN_CKBLV := 100;
      END IF;
    ELSE 
      -- LN_QBXSE>0
      IF LN_CKXSE> LN_QBXSE THEN
        LN_CKBLV := 100;
      ELSIF LN_CKXSE<0 THEN
        LN_CKBLV := 0;
      ELSE
        LN_CKBLV := 100 * LN_CKXSE / LN_QBXSE;
      END IF;
    END IF;
    
    IF LN_SBMDTSE<=0 OR LN_SBMDE<=0 THEN
      LN_MDBLV := 0;
    ELSIF LN_SBMDE>LN_SBMDTSE THEN
      LN_MDBLV := 100;
    ELSE
      LN_MDBLV := 100 * LN_SBMDE / LN_SBMDTSE;
    END IF;
    
    IF LN_QBXSE<=0 OR LN_SBSF<=0 THEN
      LN_SFBLV := 0;
    ELSIF LN_SBSF>LN_QBXSE THEN
      LN_SFBLV := 100;
    ELSE
      LN_SFBLV := 100 * LN_SBSF / LN_QBXSE;
    END IF;
      
      
    LC_CKBLV := CASE WHEN LN_CKBLV>=80 THEN 'A' WHEN LN_CKBLV>=60 THEN 'B' WHEN LN_CKBLV>=40 THEN 'C' WHEN LN_CKBLV>=20 THEN 'D' ELSE 'E' END;
    LC_CKGM := CASE WHEN LN_CKGM>=100000000 THEN 'A' WHEN LN_CKGM>=50000000 THEN 'B' WHEN LN_CKGM>=10000000 THEN 'C' WHEN LN_CKGM>=1000000 THEN 'D' ELSE 'E' END;
    LC_MDBLV := CASE WHEN LN_MDBLV>=40 THEN 'A' WHEN LN_MDBLV>=30 THEN 'B' WHEN LN_MDBLV>=20 THEN 'C' WHEN LN_MDBLV>=10 THEN 'D' ELSE 'E' END;
    LC_SFBLV := CASE WHEN LN_SFBLV>=20 THEN 'A' WHEN LN_SFBLV>=15 THEN 'B' WHEN LN_SFBLV>=10 THEN 'C' WHEN LN_SFBLV>=5 THEN 'D' ELSE 'E' END;
    
    UPDATE TL_TSSH.JCFX_NSR_BADJ A
       SET A.CKBLV=LN_CKBLV, A.CKBLV_DM=LC_CKBLV, A.CKGM=LN_CKGM, A.CKGM_DM=LC_CKGM, A.MDBLV=LN_MDBLV, A.MDBLV_DM=LC_MDBLV, A.SFLV=LN_SFBLV, A.SFLV_DM=LC_SFBLV
     WHERE A.DJXH=CUR_NSR.DJXH;
    COMMIT;
  END LOOP;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_DXTX_JJYQ
prompt ================================
prompt
CREATE OR REPLACE PROCEDURE PRO_DXTX_JJYQ
/*
 * 20260515，根据杭州市局王薇意见，每年4月申报期增加卷烟免税核销的提醒
 */
AS
  LL_JJR        NUMBER(10);
  LL_TSSB       NUMBER(10);
  LL_FUH        NUMBER(10);
  LL_FUHCL      NUMBER(10);
  LL_SDHC       NUMBER(10);
  LL_FXCK       NUMBER(10);
  LL_NKSQTX     NUMBER(10);
  LL_NKSHJD     NUMBER(10);
  LL_MSZMHX     NUMBER(10);
  LC_SWJGDM     VARCHAR2(11);
  LC_MSG        VARCHAR2(200);
BEGIN
  SELECT COUNT(1)
    INTO LL_JJR
    FROM TL_BJTS.PUB_JJR T
   WHERE T.JJR_DATE=TRUNC(SYSDATE);

  FOR CUR_USER IN (SELECT T.ID,T.JOB_TYPE,T.PHONE,T.SWJG_DM,T.SWJG_MC,T.USERNAME,
                          T.JJYQ_TSSB,T.JJYQ_FUH,T.JJYQ_FUHCL,T.JJYQ_SDHC,T.FXCK,T.NKSQTX,T.NKSHJD,T.JJRTXBZ
                    FROM TL_TSSH.MSG_PUSH_USER T
                   WHERE T.QYBZ='Y')
  LOOP
    IF CUR_USER.JJRTXBZ='N' AND LL_JJR>0 THEN
      CONTINUE;
    END IF;
    IF CUR_USER.JOB_TYPE IN ('1','2') THEN -- 区县局
      BEGIN
        IF CUR_USER.JJYQ_TSSB='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_TSSB
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='退税办理' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_TSSB>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，有'||LL_TSSB||'笔出口退(免)税业务即将超期，请及时办理。谢谢！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-01',
                          CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM DUAL;
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.JJYQ_FUH='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FUH
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_FUH>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，'||S.YWBZ||'的函调业务即将超期，请及时办理。谢谢！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-02-'||S.BIZKEY,CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=TRUNC(SYSDATE);
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.JJYQ_FUHCL='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FUHCL
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_FUHCL>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，'||S.YWBZ||'已于'||TO_CHAR(QDSJ,'YYYY-MM-DD')||'回函，请及时办理。谢谢！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-05-'||S.BIZKEY,CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=TRUNC(SYSDATE);
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.JJYQ_SDHC='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_SDHC
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_SDHC>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，税号['||S.NSRSBH||']的容缺办理退税业务，实地核查即将超期，请及时办理。谢谢！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-03-'||S.BIZKEY,CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM MSG_PUSH_DATA S
                    WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=TRUNC(SYSDATE);
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.FXCK='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_FXCK
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='风险出口电子信息' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_FXCK>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，您部门扫描到['||LL_FXCK||']笔风险出口电子信息，请加强监管。详情请到便捷退税管理系统的短信关联业务查询！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-04',CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM DUAL;
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.NKSQTX='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_NKSQTX
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='内控提醒' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_NKSQTX>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，您部门扫描到['||LL_FXCK||']笔内控风险事前提醒业务，请及时处理。详情请到便捷退税管理系统的内控管理——内控风险处理——事前提醒信息管理查询！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-04',CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM DUAL;
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.NKSHJD='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_NKSHJD
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='内控监督' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_NKSHJD>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，您部门扫描到['||LL_FXCK||']笔内控风险事后监督业务，请及时处理。详情请到便捷退税管理系统的内控管理——内控风险处理——事后风险信息管理查询！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-04',CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM DUAL;
              COMMIT;
            END IF;
          END;
        END IF;

        IF CUR_USER.JJYQ_TSSB='Y' THEN
          BEGIN
            SELECT COUNT(1)
              INTO LL_MSZMHX
              FROM MSG_PUSH_DATA S
             WHERE S.SWJG_DM=CUR_USER.SWJG_DM AND S.BIZTYPE='免税核销' AND S.SJTBSJ>=TRUNC(SYSDATE);
            IF LL_MSZMHX>0 THEN
              INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
                   SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,
                          '温馨提醒：['||CUR_USER.SWJG_MC||']，您部门扫描到['||LL_FXCK||']笔企业（出口卷烟/来料加工证明）未免税核销的提醒，请提醒企业及时核销。详情请到便捷退税管理系统的内控管理——内控风险处理——事后风险信息管理查询！',
                          '0',CUR_USER.PHONE,SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD')||'-04',CUR_USER.SWJG_DM,CUR_USER.USERNAME
                     FROM DUAL;
              COMMIT;
            END IF;
          END;
        END IF;

      END;
    ELSE
      BEGIN
        IF CUR_USER.JOB_TYPE = '3' THEN
          LC_SWJGDM :=SUBSTR(CUR_USER.SWJG_DM, 1, 5)||'%';
        ELSE
          LC_SWJGDM :=SUBSTR(CUR_USER.SWJG_DM, 1, 3)||'%';
        END IF;
        SELECT COUNT(1)
          INTO LL_TSSB
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='退税办理' AND S.SJTBSJ>=TRUNC(SYSDATE)
           AND CUR_USER.JJYQ_TSSB='Y';
        SELECT COUNT(1)
          INTO LL_FUH
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='函调复函' AND S.SJTBSJ>=TRUNC(SYSDATE)
           AND CUR_USER.JJYQ_FUH='Y';
        SELECT COUNT(1)
          INTO LL_FUHCL
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='函调处理' AND S.SJTBSJ>=TRUNC(SYSDATE)
           AND CUR_USER.JJYQ_FUHCL='Y';
        SELECT COUNT(1)
          INTO LL_SDHC
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='容缺办理' AND S.SJTBSJ>=TRUNC(SYSDATE)
           AND CUR_USER.JJYQ_SDHC='Y';
        SELECT COUNT(1)
          INTO LL_MSZMHX
          FROM MSG_PUSH_DATA S
         WHERE S.SWJG_DM LIKE LC_SWJGDM AND S.BIZTYPE='免税核销' AND S.SJTBSJ>=TRUNC(SYSDATE)
           AND CUR_USER.JJYQ_TSSB='Y';
        IF (LL_TSSB + LL_FUH + LL_FUHCL + LL_SDHC + LL_MSZMHX) >0 THEN
          LC_MSG := '温馨提醒：[' || CUR_USER.SWJG_MC || ']，下属各局共有';
          IF LL_TSSB > 0 THEN
            LC_MSG := LC_MSG || LL_TSSB || '笔出口退(免)税业务，';
          END IF;
          IF LL_FUH > 0 THEN
            LC_MSG := LC_MSG || LL_FUH || '笔函调复函业务，';
          END IF;
          IF LL_FUHCL > 0 THEN
            LC_MSG := LC_MSG || LL_FUHCL || '笔复函处理业务，';
          END IF;
          IF LL_SDHC > 0 THEN
            LC_MSG := LC_MSG || LL_SDHC || '笔容缺办理的实地核查业务，';
          END IF;
          IF LL_MSZMHX > 0 THEN
            LC_MSG := LC_MSG || LL_MSZMHX || '笔企业免税核销提醒，';
          END IF;
          LC_MSG := LC_MSG || '即将超期，请督促办理。谢谢！';
          INSERT INTO MSG_PUSH_PLAN(ID,USERID,CONTENT,SEND_TYPE,SEND_TARG,CRTIME,PLAN_FLAG,QYBZ,PLAN_TAG,SWJG_DM,USERNAME)
               SELECT SEQ_MSG_PUSH_PLAN.NEXTVAL,CUR_USER.ID,LC_MSG,'0',CUR_USER.PHONE,
                      SYSDATE,'0','Y',TO_CHAR(SYSDATE,'YYYY-MM-DD'),CUR_USER.SWJG_DM,CUR_USER.USERNAME
                 FROM DUAL;
          COMMIT;
        END IF;
      END;
    END IF;
  END LOOP;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_ATFX_CKFP
prompt =====================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_ATFX_CKFP
/*
 * 风险管理——案头分析——出口电子信息补充发票号码、境外收货人信息
 */
(
  P_DJXH    IN VARCHAR2
)
AS
  LC_CKFP        VARCHAR2(30);
  LN_FGF         NUMBER(5);
  LC_WSMC        VARCHAR2(300);
BEGIN
  FOR CUR_CK IN (SELECT CK.DJXH,CK.CKBGDH,CK.DLCKHWZMHM
                   FROM TL_TSSH.ATFX_CK_YS_CKDZXX CK
                  WHERE CK.DJXH=P_DJXH
                    AND CK.CYTSSBJL IS NOT NULL AND CK.CKFPHM IS NULL)
  LOOP
    BEGIN
      IF CUR_CK.DLCKHWZMHM IS NULL THEN
        SELECT CKFPH
          INTO LC_CKFP
          FROM (SELECT MTS.CKFPH
                  FROM TL_TSSH.ATFX_TS_YS_CKMXSBB MTS
                 WHERE MTS.DJXH=CUR_CK.DJXH
                   AND MTS.CKBGDH=CUR_CK.CKBGDH
                 UNION ALL
                SELECT MDT.CKFPH
                  FROM TL_TSSH.ATFX_TS_YS_MDTSSBB MDT
                 WHERE MDT.DJXH=CUR_CK.DJXH
                   AND MDT.CKBGDH=CUR_CK.CKBGDH)
         WHERE ROWNUM=1;
      ELSE
        SELECT CKFPH
          INTO LC_CKFP
          FROM (SELECT MTS.CKFPH
                  FROM TL_TSSH.ATFX_TS_YS_CKMXSBB MTS
                 WHERE MTS.DJXH=CUR_CK.DJXH
                   AND MTS.DLZMH=CUR_CK.DLCKHWZMHM
                 UNION ALL
                SELECT MDT.CKFPH
                  FROM TL_TSSH.ATFX_TS_YS_MDTSSBB MDT
                 WHERE MDT.DJXH=CUR_CK.DJXH
                   AND MDT.DLCKHWZMHM=CUR_CK.DLCKHWZMHM)
         WHERE ROWNUM=1;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        LC_CKFP := NULL;
    END;
    
    IF LC_CKFP IS NOT NULL THEN
      LN_FGF := INSTR(LC_CKFP,',');
      IF LN_FGF>0 THEN
        LC_CKFP := SUBSTR(LC_CKFP,1,LN_FGF-1);
      END IF;
      LN_FGF := INSTR(LC_CKFP,'-');
      IF LN_FGF>0 THEN
        LC_CKFP := SUBSTR(LC_CKFP,1,LN_FGF-1);
      END IF;
      BEGIN
        IF LENGTH(LC_CKFP) IN (18,20) THEN
          SELECT FP.GMFMC
            INTO LC_WSMC
            FROM TL_TSSH.ATFX_FP_YS_XSFPXX FP
           WHERE FP.DJXH=CUR_CK.DJXH
             AND FP.FPHM=LC_CKFP
             AND ROWNUM=1;
        ELSE
          SELECT FP.GMFMC
            INTO LC_WSMC
            FROM TL_TSSH.ATFX_FP_YS_XSFPXX FP
           WHERE FP.DJXH=CUR_CK.DJXH
             AND FP.FPHM LIKE '%'||LC_CKFP
             AND ROWNUM=1;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          LC_WSMC := NULL;
      END;
      
      UPDATE ATFX_CK_YS_CKDZXX T
         SET T.CKFPHM = LC_CKFP,
             T.JWSHR = LC_WSMC
       WHERE T.DJXH = CUR_CK.DJXH
         AND T.CKBGDH = CUR_CK.CKBGDH;
      COMMIT;
    END IF;
  END LOOP;
  
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_DATA_FZPCKQY
prompt ========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_DATA_FZPCKQY
/*
 * 纺织品出口企业风险指标提取过程
 */
AS
BEGIN
  -- 1、先运行zj_bjts用户下的PRO_DEAL_FXGL_DATA_FZPCKQY存储过程，获取FXGL_DATA_FZPCKQY企业信息
  -- 2、调用ETL抽取进销项发票数据到FXGL_DATA_FZPCKQY_FPXX表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_FZPCKQY_FPXX
         (FPHM,XH,KPRQ,XSFNSRSBH,XSFMC,XHFDJXH,GMFNSRSBH,GMFMC,GMFDJXH,SPHFWSSFLHBBM,SPFWJC,XMMC,GGXH,DW,FPSPDJ,FPSPSL,JE,SL_1,SE,SPBM5,SL)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XSFMC,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFMC,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.SPFWJC,HW.XMMC,HW.GGXH,
         UPPER(HW.DW),
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         SUBSTR(HW.SPHFWSSFLHBBM,1,5),TO_NUMBER(HW.FPSPSL)
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.KPRQ >= LD_FXRQQ AND FP.KPRQ < LD_FXRQZ
     AND (FP.XSFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_FZPCKQY) OR
         FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_FZPCKQY));
  COMMIT;
*/

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_JXMX';
  COMMIT;

  -- 进项发票（采购原材料）按商品大类、名称分组
  INSERT INTO FXGL_DATA_FZPCKQY_JXMX
         (DJXH,SPBM5,XMMC,DW,SL,JE,SE)
  SELECT FP.GMFDJXH,FP.SPBM5,FP.XMMC,FP.DW,SUM(TO_NUMBER(FP.FPSPSL)),SUM(FP.JE),SUM(FP.SE)
    FROM FXGL_DATA_FZPCKQY_FPXX FP
   WHERE FP.GMFDJXH IS NOT NULL
     AND FP.SPBM5 IN ('10401', '10704')
     AND FP.SE <> 0 --出口单证不算
     AND (FP.DW NOT IN ('T', '吨', 'KM', '千米') OR
         (FP.DW IN ('T', '吨', 'KM', '千米') AND TO_NUMBER(FP.FPSPDJ)>100))  --单价过低的吨和千米，应该是发票开错，应为公斤或米，不参与计算
   GROUP BY FP.GMFDJXH,FP.SPBM5,FP.XMMC,FP.DW;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_JXXX';
  COMMIT;

  -- 进项发票（采购原材料）按商品大类、名称分组统计
  INSERT INTO FXGL_DATA_FZPCKQY_JXXX
         (DJXH,SPBM5,JH_SL_KG,JH_JE_KG,JH_DJ_KG,JH_DJ_KG_PJ,JH_SL_M,JH_JE_M,JH_DJ_M,JH_DJ_M_PJ,JH_JE_NOTKG,JH_GJ_M)
  WITH
  MD AS (
  SELECT DJXH, NVL(CK_GJ_M,CK_GJ_M_PJ) AS JH_GJ_M, '10401' AS SPBM5
    FROM FXGL_DATA_FZPCKQY
   UNION
  SELECT DJXH, NVL(CK_GJ_M,CK_GJ_M_PJ) AS JH_GJ_M, '10704' AS SPBM5
    FROM FXGL_DATA_FZPCKQY
  ),
  JX_KG AS ( --重量单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('T', '吨') THEN SL * 1000
               WHEN DW IN ('KG', '公斤', '千克') THEN SL
               ELSE 0
             END) AS JX_SL_KG,
         SUM(JE) AS JX_JE_KG,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)
         END  AS JX_DJ_KG
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH,SPBM5
  ),
  DJALL_KG AS (
  SELECT SPBM5,
         SUM(ABS(JX_JE_KG)) / SUM(ABS(JX_SL_KG)) AS JX_DJ_KG_PJ
    FROM JX_KG
   GROUP BY SPBM5
  ),
  JX_M AS ( --长度单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('KM', '千米') THEN SL*1000
               WHEN DW IN ('百米') THEN SL*100
               WHEN DW IN ('M', '米') THEN SL
               WHEN DW IN ('码') THEN SL*0.9144
               ELSE 0
             END) AS JX_SL_M,
         SUM(JE) AS JX_JE_M,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('KM', '千米') THEN ABS(SL)*1000
                      WHEN DW IN ('百米') THEN ABS(SL)*100
                      WHEN DW IN ('M', '米') THEN ABS(SL)
                      WHEN DW IN ('码') THEN ABS(SL)*0.9144
                      ELSE 0
                    END)
         END AS JX_DJ_M
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW IN ('KM', '千米', '百米', 'M', '米', '码')
     AND XMMC NOT LIKE '%带'
     AND XMMC NOT LIKE '%线'
   GROUP BY DJXH, SPBM5
  ),
  DJALL_M AS (
  SELECT SPBM5,
         SUM(ABS(JX_JE_M)) / SUM(ABS(JX_SL_M)) AS JX_DJ_M_PJ
    FROM JX_M
   GROUP BY SPBM5
  ),
  JX_NOTKG AS ( --非重量计，非长度计部分采购，从金额算重量
  SELECT DJXH, SPBM5, SUM(JE) AS JX_JE_NOTKG
    FROM FXGL_DATA_FZPCKQY_JXMX
   WHERE DW NOT IN ('T', '吨', 'KG', '公斤', '千克', 'KM', '千米', '百米', 'M', '米', '码')
   GROUP BY DJXH, SPBM5
  )
  SELECT MD.DJXH,
         MD.SPBM5,
         NVL(JX_KG.JX_SL_KG,0),
         NVL(JX_KG.JX_JE_KG,0),
         NVL(JX_KG.JX_DJ_KG,DJALL_KG.JX_DJ_KG_PJ),
         DJALL_KG.JX_DJ_KG_PJ,
         NVL(JX_M.JX_SL_M,0),
         NVL(JX_M.JX_JE_M,0),
         NVL(JX_M.JX_DJ_M,DJALL_M.JX_DJ_M_PJ),
         DJALL_M.JX_DJ_M_PJ,
         NVL(JX_NOTKG.JX_JE_NOTKG,0),
         MD.JH_GJ_M
    FROM MD
    LEFT JOIN JX_KG ON JX_KG.DJXH=MD.DJXH AND JX_KG.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_KG ON DJALL_KG.SPBM5=MD.SPBM5
    LEFT JOIN JX_M ON JX_M.DJXH=MD.DJXH AND JX_M.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_M ON DJALL_M.SPBM5=MD.SPBM5
    LEFT JOIN JX_NOTKG ON JX_NOTKG.DJXH=MD.DJXH AND JX_NOTKG.SPBM5=MD.SPBM5;
  COMMIT;

  -- 更新原材料采购指标
  UPDATE FXGL_DATA_FZPCKQY T
     SET (T.JH_ZZL,T.JH_ZJE,T.JH_DJ_GJ,T.JH_DJ_GJ_PJ,T.JH_DJ_M,T.JH_DJ_M_PJ) = (
  SELECT SUM(S.JH_SL_KG + S.JH_SL_M * S.JH_GJ_M + S.JH_JE_NOTKG / S.JH_DJ_KG),
         SUM(S.JH_JE_KG + S.JH_JE_M + S.JH_JE_NOTKG),
         AVG(S.JH_DJ_KG),
         AVG(S.JH_DJ_KG_PJ),
         AVG(S.JH_DJ_M),
         AVG(S.JH_DJ_M_PJ)
    FROM FXGL_DATA_FZPCKQY_JXXX S
   WHERE S.DJXH=T.DJXH);
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_NXMX';
  COMMIT;

  -- 内销发票按商品大类、名称分组
  INSERT INTO FXGL_DATA_FZPCKQY_NXMX
         (DJXH,SPBM5,XMMC,DW,SL,JE,SE)
  SELECT FP.XHFDJXH,FP.SPBM5,FP.XMMC,FP.DW,SUM(TO_NUMBER(FP.FPSPSL)),SUM(FP.JE),SUM(FP.SE)
    FROM FXGL_DATA_FZPCKQY_FPXX FP
   WHERE FP.XHFDJXH IS NOT NULL
     AND FP.SPBM5 IN ('10401', '10402', '10704')
     AND FP.SE <> 0 --出口单证不算
     AND (FP.DW NOT IN ('T', '吨', 'KM', '千米') OR
         (FP.DW IN ('T', '吨', 'KM', '千米') AND TO_NUMBER(FP.FPSPDJ)>100))  --单价过低的吨和千米，应该是发票开错，应为公斤或米，不参与计算
   GROUP BY FP.XHFDJXH,FP.SPBM5,FP.XMMC,FP.DW;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_FZPCKQY_NXXX';
  COMMIT;

  -- 内销发票按商品大类、名称分组统计
  INSERT INTO FXGL_DATA_FZPCKQY_NXXX
         (DJXH,SPBM5,NX_SL_KG,NX_JE_KG,NX_DJ_KG,NX_DJ_KG_PJ,NX_JE_NOTKG)
  WITH
  MD AS (
  SELECT DJXH, SPBM5
    FROM FXGL_DATA_FZPCKQY_NXMX
   GROUP BY DJXH, SPBM5
  ),
  NX_KG AS ( --重量单位计算
  SELECT DJXH,
         SPBM5,
         SUM(CASE
               WHEN DW IN ('T', '吨') THEN SL * 1000
               WHEN DW IN ('KG', '公斤', '千克') THEN SL
               ELSE 0
             END) AS NX_SL_KG,
         SUM(JE) AS NX_JE_KG,
         CASE
           WHEN SUM(ABS(JE)) =0
             OR SUM(ABS(JE)) IS NULL
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)=0
             OR SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END) IS NULL
           THEN NULL
           ELSE SUM(ABS(JE)) /
                SUM(CASE
                      WHEN DW IN ('T', '吨') THEN
                        ABS(SL) * 1000
                      WHEN DW IN ('KG', '公斤', '千克') THEN
                        ABS(SL)
                      ELSE
                        0
                    END)
         END  AS NX_DJ_KG
    FROM FXGL_DATA_FZPCKQY_NXMX
   WHERE DW IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH,SPBM5
  ),
  DJALL_KG AS (
  SELECT SPBM5,
         SUM(ABS(NX_JE_KG)) / SUM(ABS(NX_SL_KG)) AS NX_DJ_KG_PJ
    FROM NX_KG
   GROUP BY SPBM5
  ),
  NX_NOTKG AS ( --非重量计，从金额算重量
  SELECT DJXH, SPBM5, SUM(JE) AS NX_JE_NOTKG
    FROM FXGL_DATA_FZPCKQY_NXMX
   WHERE DW NOT IN ('T', '吨', 'KG', '公斤', '千克')
   GROUP BY DJXH, SPBM5
  )
  SELECT MD.DJXH,
         MD.SPBM5,
         NVL(NX_KG.NX_SL_KG,0),
         NVL(NX_KG.NX_JE_KG,0),
         NVL(NX_KG.NX_DJ_KG,DJALL_KG.NX_DJ_KG_PJ),
         DJALL_KG.NX_DJ_KG_PJ,
         NVL(NX_NOTKG.NX_JE_NOTKG,0)
    FROM MD
    LEFT JOIN NX_KG ON NX_KG.DJXH=MD.DJXH AND NX_KG.SPBM5=MD.SPBM5
    LEFT JOIN DJALL_KG ON DJALL_KG.SPBM5=MD.SPBM5
    LEFT JOIN NX_NOTKG ON NX_NOTKG.DJXH=MD.DJXH AND NX_NOTKG.SPBM5=MD.SPBM5;
  COMMIT;

  -- 更新内销指标
  UPDATE FXGL_DATA_FZPCKQY T
     SET (T.NX_ZZL,T.NX_ZJE) = (
  SELECT SUM(S.NX_SL_KG + S.NX_JE_NOTKG / S.NX_DJ_KG_PJ),
         SUM(S.NX_JE_KG + S.NX_JE_NOTKG)
    FROM FXGL_DATA_FZPCKQY_NXXX S
   WHERE S.DJXH=T.DJXH);
  COMMIT;

  -- 更新耗电指标
  UPDATE FXGL_DATA_FZPCKQY T
     SET T.DL_JE = (
  SELECT SUM(S.JE)
    FROM FXGL_DATA_FZPCKQY_FPXX S
   WHERE (S.XHFDJXH = T.DJXH OR
          S.GMFDJXH = T.DJXH)
     AND ((REGEXP_LIKE(S.SPHFWSSFLHBBM,'^110010102') AND REGEXP_LIKE(S.XMMC,'电')) OR
          REGEXP_LIKE(S.XMMC,'电能耗|电( )*[费量价补能谷峰购]|[水风售份耗谷峰]电|([水风用月季年份发供耗]电|能耗|空调费|力)(费|收入)?[0-9A-Z [:punct:]]*$|电.*月'))
     AND S.SPFWJC = '供电' );
  COMMIT;

END;
/

prompt
prompt Creating procedure PRO_FXGL_DATA_STZCANDGJSB
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_DATA_STZCANDGJSB
/*
 * 生产企业出口外购货物风险模型、购进设备开1%3%普票风险模型
 */
AS
BEGIN
  -- 1、先运行zj_bjts用户下的PRO_DEAL_FXGL_STZCANDGJSB存储过程，获取FXGL_DATA_STZC企业信息
  -- 2、提取sbtscke>100000的数据到本地，目前有29961户
  -- 3、调用ETL抽取进销项发票数据到FXGL_DATA_STZC_FPXX表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_STZC_FPXX
         (FPHM,XH,KPRQ,XSFNSRSBH,XHFDJXH,GMFNSRSBH,GMFDJXH,SPHFWSSFLHBBM,XMMC,FPSPDJ,FPSPSL,JE,SL_1,SE,BZ)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.XMMC,
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         FP.BZ
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.KPRQ >= DATE'2024-01-01' AND FP.KPRQ < DATE'2026-01-01'
     --AND FP.FPZT_DM<>'2'
     AND NOT REGEXP_LIKE(HW.XMMC, '原价合计|折扣额合计'
     AND (FP.XSFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC) OR
         FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC));
  COMMIT;
*/
  -- 4、调用ETL抽取采购设备的进项发票（包括数电、专票、普票）数据到FXGL_DATA_STZC_FPXX_GJ表中
  -- 数据抽取逻辑如下
/*
  INSERT INTO FXGL_DATA_STZC_FPXX_GJ
         (FPHM,XH,KPRQ,XSFNSRSBH,XHFDJXH,GMFNSRSBH,GMFDJXH,SPHFWSSFLHBBM,XMMC,FPSPDJ,FPSPSL,JE,SL_1,SE,BZ,FPLB)
  SELECT HW.FPHM,HW.XH,HW.KPRQ,
         FP.XSFNSRSBH,FP.XHFDJXH,
         FP.GMFNSRSBH,FP.GMFDJXH,
         HW.SPHFWSSFLHBBM,HW.XMMC,
         HW.FPSPDJ,HW.FPSPSL,HW.JE,HW.SL_1,HW.SE,
         FP.BZ,FPLB -- 底帐库根据专票、普票的对应表设置，数电票需要根据发票的某个字段区分，分别设置为“专票、普票”
    FROM DZFP_KPYW_FPJCXXB FP
   INNER JOIN DZFP_KPYW_FPMXXXB HW
      ON HW.FPHM=FP.FPHM
   WHERE FP.GMFNSRSBH IN (SELECT NSRSBH FROM FXGL_DATA_STZC)
     --AND FP.FPZT_DM<>'2'
     AND FP.SPHFWSSFLHBBM LIKE '109%' -- 购进设备
     AND (CASE WHEN NVL(HW.FPSPDJ,'0')='0' OR UPPER(HW.FPSPDJ)='NULL' THEN HW.JE ELSE TO_NUMBER(HW.FPSPDJ) END)>5000; -- 单价5000以上
  COMMIT;
*/

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_CKMX';
  COMMIT;

  -- 出口发票按商品编码、名称分组
  INSERT INTO FXGL_DATA_STZC_CKMX(DJXH,SPHFWSSFLHBBM,XMMC,JE)
  SELECT FP.XHFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC,SUM(FP.JE)
    FROM FXGL_DATA_STZC_FPXX FP
   WHERE FP.XHFDJXH IS NOT NULL
     AND FP.SE = 0 --出口业务，全省除绍兴，其他大部分开免税，因此用税额判断
     AND REGEXP_LIKE(FP.BZ,'出口业务')
   GROUP BY FP.XHFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_JXMX';
  COMMIT;

  -- 进货发票按商品编码、名称分组
  INSERT INTO FXGL_DATA_STZC_CKMX(DJXH,SPHFWSSFLHBBM,XMMC,JE)
  SELECT FP.GMFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC,SUM(FP.JE)
    FROM FXGL_DATA_STZC_FPXX FP
   WHERE FP.GMFDJXH IS NOT NULL
   GROUP BY FP.GMFDJXH,FP.SPHFWSSFLHBBM,FP.XMMC;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_YSWG_BM';
  COMMIT;

  -- 按商品编码分组疑似外购比较
  INSERT INTO FXGL_DATA_STZC_YSWG_BM(DJXH,SPHFWSSFLHBBM,CKJE,JHJE,YSWG_BFB,YSWG_CKJE)
  SELECT A.DJXH,A.SPHFWSSFLHBBM,A.CKJE,B.JHJE,
         CASE 
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN 100
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN ROUND(B.JHJE*100/A.CKJE,2)
           ELSE 0
         END AS YSWG_BFB,
         CASE 
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN A.CKJE
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN B.JHJE
           ELSE 0
         END AS YSWG_CKJE
    FROM (SELECT DJXH,SPHFWSSFLHBBM,SUM(JE) AS CKJE FROM FXGL_DATA_STZC_CKMX GROUP BY DJXH,SPHFWSSFLHBBM) A
   INNER JOIN (SELECT DJXH,SPHFWSSFLHBBM,SUM(JE) AS JHJE FROM FXGL_DATA_STZC_JXMX GROUP BY DJXH,SPHFWSSFLHBBM) B
      ON A.DJXH=B.DJXH AND A.SPHFWSSFLHBBM=B.SPHFWSSFLHBBM;
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_YSWG_MC';
  COMMIT;

  -- 按商品编码、名称分组疑似外购比较
  INSERT INTO FXGL_DATA_STZC_YSWG_MC(DJXH,SPHFWSSFLHBBM,XMMC,CKJE,JHJE,YSWG_BFB,YSWG_CKJE)
  SELECT A.DJXH,A.SPHFWSSFLHBBM,A.XMMC,A.CKJE,B.JHJE,
         CASE 
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN 100
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN ROUND(B.JHJE*100/A.CKJE,2)
           ELSE 0
         END AS YSWG_BFB,
         CASE 
           WHEN A.CKJE>0 AND A.CKJE<B.JHJE THEN A.CKJE
           WHEN A.CKJE>0 AND A.CKJE>=B.JHJE THEN B.JHJE
           ELSE 0
         END AS YSWG_CKJE
    FROM (SELECT DJXH,SPHFWSSFLHBBM,XMMC,SUM(JE) AS CKJE FROM FXGL_DATA_STZC_CKMX GROUP BY DJXH,SPHFWSSFLHBBM,XMMC) A
   INNER JOIN (SELECT DJXH,SPHFWSSFLHBBM,XMMC,SUM(JE) AS JHJE FROM FXGL_DATA_STZC_JXMX GROUP BY DJXH,SPHFWSSFLHBBM,XMMC) B
      ON A.DJXH=B.DJXH AND A.SPHFWSSFLHBBM=B.SPHFWSSFLHBBM AND A.XMMC=B.XMMC;
  COMMIT;

  UPDATE FXGL_DATA_STZC T
     SET T.FP_CKE=(
         SELECT SUM(FP.JE)
           FROM FXGL_DATA_STZC_FPXX FP
          WHERE FP.XHFDJXH=T.DJXH
            AND FP.SE = 0 --出口业务，全省除绍兴，其他大部分开免税，因此用税额判断
            AND REGEXP_LIKE(FP.BZ,'出口业务')),
         T.FP_GJE=(
         SELECT SUM(FP.JE)
           FROM FXGL_DATA_STZC_FPXX FP
          WHERE FP.GMFDJXH=T.DJXH),
         T.YSWG_CKJE_BM=(
         SELECT SUM(YSWG_CKJE)
           FROM FXGL_DATA_STZC_YSWG_BM BM
          WHERE BM.DJXH=T.DJXH),
         T.YSWG_CKJE_MC=(
         SELECT SUM(YSWG_CKJE)
           FROM FXGL_DATA_STZC_YSWG_MC MC
          WHERE MC.DJXH=T.DJXH)
   WHERE T.ETL_BZ='1';
  COMMIT;

  UPDATE FXGL_DATA_STZC T
     SET T.YSWG_CKZB_BM = ROUND(100* T.YSWG_CKJE_BM/T.FP_CKE,2),
         T.YSWG_CKZB_MC = ROUND(100* T.YSWG_CKJE_MC/T.FP_CKE,2)
   WHERE T.ETL_BZ='1'
     AND T.FP_CKE>0;
  COMMIT;

  UPDATE FXGL_DATA_STZC T
     SET (GJSB_MINKPRQ,GJSB_ZJE,GJSB_XGM_PP,GJSB_XGM_ZP)=(
         SELECT MIN(FP.KPRQ),SUM(FP.JE),
                SUM(CASE WHEN FP.SL_1<=0.03 AND FP.FPLB='普票' THEN FP.JE ELSE 0 END),
                SUM(CASE WHEN FP.SL_1<=0.03 AND FP.FPLB='专票' THEN FP.JE ELSE 0 END)
           FROM FXGL_DATA_STZC_FPXX_GJ FP
          WHERE FP.GMFDJXH=T.DJXH)
   WHERE T.ETL_BZ='1';
  COMMIT;

  UPDATE FXGL_DATA_STZC T
     SET T.GJSB_ZB_PP = ROUND(100* T.GJSB_XGM_PP/T.GJSB_ZJE,2)
   WHERE T.ETL_BZ='1'
     AND T.GJSB_ZJE>0;
  COMMIT;

  UPDATE FXGL_DATA_STZC T
     SET T.ETL_BZ='2'
   WHERE T.ETL_BZ='1';
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_FPXX';
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE FXGL_DATA_STZC_FPXX_GJ';
  COMMIT;

  --输出生产企业出口外购货物风险模型企业清单
/*
  SELECT A.DJXH,
         A.NSRSBH  纳税人识别号,
         A.NSRMC  纳税人名称,
         A.ZGSWJ_DM  主管税务机关编码,
         A.ZGSWJ_MC  主管税务机关名称,
         A.HY_DM  行业代码,
         A.HY_MC  行业名称,
         TO_CHAR(A.BARQ,'yyyy-mm-dd')  退税备案日期,
         A.FP_CKE  出口发票总金额,
         A.FP_GJE  购进发票总金额,
         A.SBTS_CKE  申报退税出口额,
         A.SBTS_WGCKE  申报退税外购出口额,
         A.YSWG_CKJE_BM  疑似外购出口金额_编码,
         A.YSWG_CKZB_BM  疑似外购出口占比_编码,
         A.YSWG_CKJE_MC  疑似外购出口金额_品名,
         A.YSWG_CKZB_MC  疑似外购出口占比_品名
    FROM FXGL_DATA_STZC A
   WHERE A.FP_CKE>0
     AND A.YSWG_CKZB_BM>30
     AND A.YSWG_CKJE_MC>100000;
*/
  --输出生产企业购进设备开1%3%普票风险模型企业清单
/*
  SELECT A.DJXH,
         A.NSRSBH  纳税人识别号,
         A.NSRMC  纳税人名称,
         A.ZGSWJ_DM  主管税务机关编码,
         A.ZGSWJ_MC  主管税务机关名称,
         A.HY_DM  行业代码,
         A.HY_MC  行业名称,
         TO_CHAR(A.BARQ,'yyyy-mm-dd')  退税备案日期,
         TO_CHAR(A.GJSB_MINKPRQ,'yyyy-mm-dd')  购进设备统计期起,
         A.GJSB_ZJE  购进设备总金额,
         A.GJSB_XGM_PP  其中开具小规模普票金额,
         A.GJSB_XGM_ZP  其中开具小规模专票金额,
         A.GJSB_ZB_PP  开具小规模普票占比
    FROM FXGL_DATA_STZC A
   WHERE A.GJSB_ZJE>0
     AND A.GJSB_XGM_PP>100000;
*/
END;
/

prompt
prompt Creating procedure PRO_FXGL_SZYJ_CKSPDJ_PERM
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_SZYJ_CKSPDJ_PERM
/*
 * 风险管理——事中预警——出口商品平均单价模型刷新（每月）
 */
AS
BEGIN
  delete from tl_admin.yj_cs_qspjdj_wm;
  commit;

  insert into tl_admin.yj_cs_qspjdj_wm(spdm,qnt,amt,dj,qyhs,ywbs,spmc,sbspmc)
  with
  tj as (
  select a.cksp_dm,
         sum(case when a.sz='V' then a.sl else 0 end) as qnt,
         sum(a.jsje) as amt,
         count(distinct a.djxh) as qyhs,
         count(distinct a.djxh||a.glh) as ywbs
    from ckts_sb_mts_jhmx a
   where a.sbrq>=add_months(trunc(sysdate,'mm'),-12) and a.sbrq<trunc(sysdate,'mm')
     and a.sl>0
   group by a.cksp_dm
  ),
  zymc as (
  select a.cksp_dm,a.sbhgspmc,sum(a.jsje) as amt,
         row_number() over (partition by a.cksp_dm order by sum(a.jsje) desc) as pm
    from ckts_sb_mts_jhmx a
   where a.sbrq>=add_months(trunc(sysdate,'mm'),-12) and a.sbrq<trunc(sysdate,'mm')
   group by a.cksp_dm,a.sbhgspmc
  ),
  wkmc as (
  select tj.cksp_dm,wk.ckspmc,row_number() over (partition by tj.cksp_dm order by wk.yxqq desc) as pm
    from tj
    left join tl_bjts.ckts_dm_tslvwk wk on wk.cksp_dm=tj.cksp_dm
  )
  select tj.cksp_dm,tj.qnt,tj.amt,round(tj.amt/tj.qnt,2),tj.qyhs,tj.ywbs,wkmc.ckspmc,zymc.sbhgspmc
    from tj
   inner join zymc on zymc.cksp_dm=tj.cksp_dm and zymc.pm=1
   inner join wkmc on wkmc.cksp_dm=tj.cksp_dm and wkmc.pm=1
  ;
  commit;

  delete from tl_admin.yj_cs_qspjdj_sc;
  commit;

  insert into tl_admin.yj_cs_qspjdj_sc(spdm,qnt,amt,dj,qyhs,ywbs,spmc,sbspmc)
  with
  tj as (
  select a.cksp_dm,
         sum(a.cksl) as qnt,
         sum(a.mylaj) as amt,
         count(distinct a.djxh) as qyhs,
         count(distinct nvl(a.ckbgdh,a.dlckhwzmhm)) as ywbs
    from ckts_sb_mdt_ckmx a
   where a.sbrq>=add_months(trunc(sysdate,'mm'),-12) and a.sbrq<trunc(sysdate,'mm')
     and a.cksl>0
   group by a.cksp_dm
  ),
  zymc as (
  select a.cksp_dm,a.sbhgspmc,sum(a.mylaj) as amt,
         row_number() over (partition by a.cksp_dm order by sum(a.mylaj) desc) as pm
    from ckts_sb_mdt_ckmx a
   where a.sbrq>=add_months(trunc(sysdate,'mm'),-12) and a.sbrq<trunc(sysdate,'mm')
   group by a.cksp_dm,a.sbhgspmc
  ),
  wkmc as (
  select tj.cksp_dm,wk.ckspmc,row_number() over (partition by tj.cksp_dm order by wk.yxqq desc) as pm
    from tj
    left join tl_bjts.ckts_dm_tslvwk wk on wk.cksp_dm=tj.cksp_dm
  )
  select tj.cksp_dm,tj.qnt,tj.amt,round(tj.amt/tj.qnt,2),tj.qyhs,tj.ywbs,wkmc.ckspmc,zymc.sbhgspmc
    from tj
   inner join zymc on zymc.cksp_dm=tj.cksp_dm and zymc.pm=1
   inner join wkmc on wkmc.cksp_dm=tj.cksp_dm and wkmc.pm=1
  ;
  commit;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_SZYJ_MMYLRL_PERM
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_SZYJ_MMYLRL_PERM
/*
 * 风险管理——事中预警——外贸企业每美元利润率刷新（每月）
 */
AS
BEGIN
  delete from tl_admin.yj_cs_wmqymmylrl;
  delete from tl_admin.yj_cs_wmqymmylrl_fqy;
  commit;

  insert into tl_admin.yj_cs_wmqymmylrl_fqy(swjg_dm,djxh,sbywbs,mmylrl_max,mmylrl_min,mmylrl_mid,mmylrl_avg,mmylrl_std,mylaj,rmblaj,jhcb,mmylrl_yjx)
  with
  jh as (
  select a.djxh,a.glh,sum(a.jsje*(100+a.zssl-a.tsl)/100) as jhcb
    from ckts_sb_mts_jhmx a
   where a.sbrq>=add_months(trunc(sysdate,'mm'),-12) and a.sbrq<trunc(sysdate,'mm')
   group by a.djxh,a.glh
  )
  ,mx as (
  select b.tsswjg_dm,b.djxh,b.ckbgdh,b.mylaj,round(c.rmblaj*b.mylaj/c.mylaj,2) as rmblaj,jh.jhcb,
         round((round(c.rmblaj*b.mylaj/c.mylaj,2)-jh.jhcb)/b.mylaj,2) as mmylrl
    from ckts_sb_mts_ckmx b
   inner join jh on jh.djxh=b.djxh and jh.glh=b.glh
   inner join ckts_wbsj_hg_bgd c on c.ckbgdh=b.ckbgdh and c.djxh=b.djxh
   where b.sbrq>=add_months(trunc(sysdate,'mm'),-12) and b.sbrq<trunc(sysdate,'mm')
     and b.ckbgdh is not null
     and c.mylaj>0 and b.mylaj>0
   union all
  select b.tsswjg_dm,b.djxh,b.dlckhwzmhm as ckbgdh,b.mylaj,round(c.rmblaj*b.mylaj/c.mylaj,2) as rmblaj,jh.jhcb,
         round((round(c.rmblaj*b.mylaj/c.mylaj,2)-jh.jhcb)/b.mylaj,2) as mmylrl
    from ckts_sb_mts_ckmx b
   inner join jh on jh.djxh=b.djxh and jh.glh=b.glh
   inner join ckts_wbsj_zj_dlckhwzm c on c.dlckhwzmhm=b.dlckhwzmhm and c.djxh=b.djxh
   where b.sbrq>=add_months(trunc(sysdate,'mm'),-12) and b.sbrq<trunc(sysdate,'mm')
     and b.ckbgdh is null
     and c.mylaj>0 and b.mylaj>0
  )
  select tsswjg_dm,djxh,
         count(distinct ckbgdh) as sbywbs,max(mmylrl) as mmylrl_max,min(mmylrl) as mmylrl_min,
         median(mmylrl) as mmylrl_mid,avg(mmylrl) as mmylrl_avg,stddev(mmylrl) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from mx
   group by tsswjg_dm,djxh
  ;
  commit;
    
  insert into tl_admin.yj_cs_wmqymmylrl(swjg_dm,sbqyhs,sbywbs,mmylrl_max,mmylrl_min,mmylrl_mid,mmylrl_avg,mmylrl_std,mylaj,rmblaj,jhcb,mmylrl_yjx)
  select swjg_dm,
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         median(mmylrl_yjx) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from tl_admin.yj_cs_wmqymmylrl_fqy
   group by swjg_dm
   union all
  select substr(swjg_dm,1,5)||'000000',
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         median(mmylrl_yjx) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from tl_admin.yj_cs_wmqymmylrl_fqy
   group by substr(swjg_dm,1,5)
   union all
  select '13300000000',
         count(distinct djxh) as sbqyhs,sum(sbywbs) as sbywbs,
         max(mmylrl_yjx) as mmylrl_max,min(mmylrl_yjx) as mmylrl_min,
         median(mmylrl_yjx) as mmylrl_mid,avg(mmylrl_yjx) as mmylrl_avg,stddev(mmylrl_yjx) as mmylrl_std,
         sum(mylaj) as mylaj,sum(rmblaj) as rmblaj,sum(jhcb) as jhcb,
         round((sum(rmblaj)-sum(jhcb))/sum(mylaj),2) as mmylrl_yjx
    from tl_admin.yj_cs_wmqymmylrl_fqy
  ;
  commit;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY
prompt =================================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_SZYJ_WMQYCKLL_DQ_PERY
/*
 * 风险管理——事中预警——外贸企业出口链路统计（每年）
 */
AS
BEGIN
  delete from ckllfx_cs_wmqylsll_dq t;
  commit;

  insert into ckllfx_cs_wmqylsll_dq(
         ysfs_dm,spdl_dm,qycode_hyd,qycode_hg,qycode_mdg,
         qyhs_all,qyzb_all,bgdfs_all,bgdzb_all,mylaj_all,myzb_all,
         qyhs_sx,qyzb_sx,bgdfs_sx,bgdzb_sx,mylaj_sx,myzb_sx)
  with
  zygys as (
  --按关联号统计主要供应地区（供货金额最大）
  select a.djxh,a.glh,
         case
           --进口缴款书货源地按口岸提取2位行政区划
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           --未提取到销售方地市税务机关代码的，从供货方税号提取2位行政区划
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           --提取到销售方地市税务机关代码的，从地市税务机关代码提取2位行政区划
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end as ghdz,
         row_number() over (partition by a.djxh,a.glh order by sum(a.jsje) desc) as pm
    from ckts_sb_mts_jhmx a
    --对进口缴款书，关联口岸代码表提取关区对应行政区划（省级）
    left join tl_admin.dm_hgcode ka on ka.hgcode=substr(a.jhpzh,1,2)||'00'
   where a.sbrq>=add_months(trunc(sysdate,'yy'),-24) and a.sbrq<trunc(sysdate,'yy')
   group by a.djxh,a.glh,
         case
           when a.cktmspzlx_dm='04'
             then substr(ka.xzqh_dm,1,2)
           when length(a.xsfdsswjgdm)=4
             then substr(a.xsfdsswjgdm,1,2)
           when length(a.xsfdsswjgdm)=5
             then substr(a.xsfdsswjgdm,2,2)
         end
  ),
  mx as (
  --按关联号提取出口链路明细
  select s.djxh,
         s.ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from ckts_sb_mts_ckmx t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join ckts_wbsj_hg_bgd s on s.ckbgdh=t.ckbgdh and s.djxh=t.djxh
    left join tl_admin.dm_xzqh_dq hyd on hyd.dm=zygys.ghdz
    --启运港报关单从报关单号提取报关关区，否则取离境关区
    left join tl_admin.dm_hgcode ka on ka.hgcode=(case when s.qygbz='Y' then substr(s.ckbgdh,1,2) else substr(s.hggqka_dm,1,2) end)||'00'
    left join tl_admin.dm_xzqh_dq hg on hg.dm=ka.xzqh_dm
    left join tl_admin.dm_gbcode mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=add_months(trunc(sysdate,'yy'),-24) and t.sbrq<trunc(sysdate,'yy')
     and t.ckbgdh is not null
   union all
  select s.djxh,
         s.dlckhwzmhm as ckbgdh,
         s.mylaj,
         s.ysfs_dm,
         substr(s.cksp_dm,1,2) as spdl_dm,
         hyd.qycode as qycode_hyd,
         hg.qycode as qycode_hg,
         mdg.qycode as qycode_mdg
    from ckts_sb_mts_ckmx t
   inner join zygys on zygys.djxh=t.djxh and zygys.glh=t.glh and pm=1
   inner join ckts_wbsj_zj_dlckhwzm s on s.dlckhwzmhm=t.dlckhwzmhm and s.djxh=t.djxh
    left join tl_admin.dm_xzqh_dq hyd on hyd.dm=zygys.ghdz
    left join tl_admin.dm_hgcode ka on ka.hgcode=substr(s.hggqka_dm,1,2)||'00'
    left join tl_admin.dm_xzqh_dq hg on hg.dm=ka.xzqh_dm
    left join tl_admin.dm_gbcode mdg on mdg.gb_code=s.zzmdgdqsz_dm
   where t.sbrq>=add_months(trunc(sysdate,'yy'),-24) and t.sbrq<trunc(sysdate,'yy')
     and t.ckbgdh is null
  ),
  tj1 as (
  -- 相同运输方式、商品大类、供货区域、目的区域总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj1,
         count(distinct ckbgdh) as bgdfs_tj1,
         sum(mylaj) as mylaj_tj1
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj2 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,
         count(distinct djxh) as qyhs_tj2,
         count(distinct ckbgdh) as bgdfs_tj2,
         sum(mylaj) as mylaj_tj2
    from mx
   where mylaj>=30000
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg
  ),
  tj3 as (
  -- 相同运输方式、商品大类、供货区域、目的区域大额报关单总数
  select ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg,
         count(distinct djxh) as qyhs_all,
         count(distinct ckbgdh) as bgdfs_all,
         sum(mylaj) as mylaj_all,
         count(distinct case when mylaj>=30000 then djxh else null end) as qyhs_sx,
         count(distinct case when mylaj>=30000 then ckbgdh else null end) as bgdfs_sx,
         sum(case when mylaj>=30000 then mylaj else 0 end) as mylaj_sx
    from mx
   group by ysfs_dm,spdl_dm,qycode_hyd,qycode_mdg,qycode_hg
  )
  select tj3.ysfs_dm,tj3.spdl_dm,tj3.qycode_hyd,tj3.qycode_hg,tj3.qycode_mdg,
         tj3.qyhs_all,case when nvl(tj1.qyhs_tj1,0)<=tj3.qyhs_all then 100.00 else round(100*tj3.qyhs_all/tj1.qyhs_tj1,2) end as qyzb_all,
         tj3.bgdfs_all,case when nvl(tj1.bgdfs_tj1,0)<=tj3.bgdfs_all then 100.00 else round(100*tj3.bgdfs_all/tj1.bgdfs_tj1,2) end as bgdzb_all,
         tj3.mylaj_all,case when nvl(tj1.mylaj_tj1,0)<=tj3.mylaj_all then 100.00 else round(100*tj3.mylaj_all/tj1.mylaj_tj1,2) end as myzb_all,
         tj3.qyhs_sx,case when nvl(tj2.qyhs_tj2,0)<=tj3.qyhs_sx then 100.00 else round(100*tj3.qyhs_sx/tj2.qyhs_tj2,2) end as qyzb_sx,
         tj3.bgdfs_sx,case when nvl(tj2.bgdfs_tj2,0)<=tj3.bgdfs_sx then 100.00 else round(100*tj3.bgdfs_sx/tj2.bgdfs_tj2,2) end as bgdzb_sx,
         tj3.mylaj_sx,case when nvl(tj2.mylaj_tj2,0)<=tj3.mylaj_sx then 100.00 else round(100*tj3.mylaj_sx/tj2.mylaj_tj2,2) end as myzb_sx
    from tj3
    left join tj1
      on tj1.ysfs_dm=tj3.ysfs_dm
     and tj1.spdl_dm=tj3.spdl_dm
     and tj1.qycode_hyd=tj3.qycode_hyd
     and tj1.qycode_mdg=tj3.qycode_mdg
    left join tj2
      on tj2.ysfs_dm=tj3.ysfs_dm
     and tj2.spdl_dm=tj3.spdl_dm
     and tj2.qycode_hyd=tj3.qycode_hyd
     and tj2.qycode_mdg=tj3.qycode_mdg
  ;
  commit;

  update ckllfx_cs_wmqylsll_dq t
     set t.fxdj_zhfxzs= t.qyzb_all * 0.1 + t.bgdzb_all * 0.2 + t.myzb_all * 0.2
                      + t.qyzb_sx  * 0.1 + t.bgdzb_sx  * 0.2 + t.myzb_sx  * 0.2;
  commit;
  -- 根据风险指数设置风险等级，对浙沪出口或货源地与出口地区域一致的降一级风险等级
  update ckllfx_cs_wmqylsll_dq t
     set t.fxdj_dm= case when t.fxdj_zhfxzs<=5
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '3' else '4' end)
                         when t.fxdj_zhfxzs<=10
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '2' else '3' end)
                         when t.fxdj_zhfxzs<=20
                         then (case when t.qycode_hg='08' or t.qycode_hyd=t.qycode_hg then '1' else '2' end)
                         else '1'
                    end;
  commit;

  RETURN;
END;
/

