                         then (case when t.qycode_hg in ('31','33') or t.qycode_hyd=t.qycode_hg then '1' else '2' end)
                         else '1'
                    end;
  commit;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_FXGL_SZYJ_XBLQY
prompt ======================================
prompt
CREATE OR REPLACE PROCEDURE PRO_FXGL_SZYJ_XBLQY
/*
 * 风险管理——事中预警——新办类企业
 */
(
  P_SWJGDM  IN  VARCHAR2, --非空，通审核助手获取当前流程的退税机关代码并传入
  P_DJXH    IN  VARCHAR2, --非空，通审核助手获取当前流程的企业登记序号并传入
  P_OUTMSG  OUT VARCHAR2
)
AS
  LN_MONTHS_ZDCK   NUMBER(18,2);
  LN_MONTHS_SCSB   NUMBER(18,2);
  LD_PRE_MAXRQ     DATE;
  LD_NOW_MINRQ     DATE;
  LD_BG_TSJWRQ     DATE;
BEGIN
  --预警参数：新办类企业首次申报以后有效期
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO LN_MONTHS_SCSB
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S
      ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_SCSB';
  --预警参数：中断出口后复出口的企业中断期
  SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
    INTO LN_MONTHS_ZDCK
    FROM FXGL_PZ_ZB_CS T
    LEFT JOIN FXGL_PZ_ZB_CS_SWJG S
      ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
   WHERE T.CSBM='C01001_MONTHS_ZDCK';
  -- LN_MONTHS_SCSB个月前最后一次申报时间
  SELECT TRUNC(MAX(T.QDSJ))
    INTO LD_PRE_MAXRQ
    FROM CKTS_LC_SBXX T
   WHERE T.DJXH = P_DJXH
     AND NVL(T.ZFBZ, 'N') = 'N'
     AND T.QDSJ <= ADD_MONTHS(SYSDATE, (-1) * LN_MONTHS_SCSB);
  -- LN_MONTHS_SCSB个月内最早一次申报时间
  SELECT TRUNC(MIN(T.QDSJ))
    INTO LD_NOW_MINRQ
    FROM CKTS_LC_SBXX T
   WHERE T.DJXH = P_DJXH
     AND NVL(T.ZFBZ, 'N') = 'N'
     AND T.QDSJ > ADD_MONTHS(SYSDATE, (-1) * LN_MONTHS_SCSB);
  -- 外贸企业LN_MONTHS_SCSB个月内最后一次迁移
  SELECT TRUNC(MAX(T.LRRQ))
    INTO LD_BG_TSJWRQ
    FROM CKTS_BA_BABGQK_JGB T
   INNER JOIN GLXT_BB_SHXT_DJXX S
      ON S.DJXH_JS=T.DJXH
     AND S.JSMODE='2'
   WHERE T.DJXH = P_DJXH
     AND BABGZD_DM='TSSWJG_DM_1'
     AND T.LRRQ > ADD_MONTHS(SYSDATE, (-1) * LN_MONTHS_SCSB);
  IF LD_PRE_MAXRQ IS NULL THEN
    P_OUTMSG := '01-新办类企业，出口企业首次申报不足'||LN_MONTHS_SCSB||'个月，请加强审核！';
    RETURN;
  END IF;
  IF NVL(LD_NOW_MINRQ,SYSDATE) >= ADD_MONTHS(LD_PRE_MAXRQ, LN_MONTHS_ZDCK) THEN
    P_OUTMSG := '02-新办类企业，出口企业中断申报'||LN_MONTHS_ZDCK||'个月后复出口申报不足'||LN_MONTHS_SCSB||'个月，请加强审核！';
    RETURN;
  END IF;
  IF LD_BG_TSJWRQ IS NOT NULL THEN
    P_OUTMSG := '03-新办类企业，外贸企业于'||TO_CHAR(LD_BG_TSJWRQ,'YYYY-MM-DD')||'迁移后首次申报不足'||LN_MONTHS_SCSB||'个月，请加强审核！';
    RETURN;
  END IF;
  P_OUTMSG := '00';
  
  RETURN;
END;
/

prompt
prompt Creating procedure PRO_JKGL_COMPUTE_S10101
prompt ==========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_JKGL_COMPUTE_S10101
/*
 * 企业经营稳定性
 * ZB_VAL：最后一次变更法人代表时间（未变更按税务登记时间）至报告期止月数
 */
(
  P_BGQID   IN NUMBER,
  P_DJXH    IN NUMBER,
  P_BGQ_Z   IN DATE
)
AS
  V_ZB_VAL     NUMBER(18,2);
  V_ROWS       NUMBER(10);
  V_BADPOINT   CHAR(1);
  V_PARAMS     VARCHAR(4000);
BEGIN
  BEGIN
    SELECT ROUND(MONTHS_BETWEEN(P_BGQ_Z,MAX(TRUNC(NVL(S.LRRQ,T.SWDJ_DATE),'MM')))),
           '[d]报告期截止日期=' || TO_CHAR(P_BGQ_Z,'YYYYMMDD') || 
           '|税务登记日期=' || TO_CHAR(MAX(T.SWDJ_DATE),'YYYYMMDD') ||
           '|最近变更法人代表日期=' || TO_CHAR(MAX(S.LRRQ),'YYYYMMDD')
      INTO V_ZB_VAL, V_PARAMS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
      LEFT JOIN TL_TSSH.CKTS_DJ_BGDJMX S ON S.DJXH=T.DJXH_JS AND S.BGQNR<>S.BGHNR AND S.LRRQ<=P_BGQ_Z
     WHERE T.DJXH_JS=P_DJXH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ZB_VAL := NULL;
  END;

  IF V_ZB_VAL IS NULL THEN
    V_BADPOINT := 'Y';
  ELSE
    V_BADPOINT := 'N';
  END IF;

  SELECT COUNT(1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10101' AND ROWNUM=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10101',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB T
       SET T.ZB_VAL=V_ZB_VAL, T.BADPOINT=V_BADPOINT, T.PARAMS=V_PARAMS, T.UPTIME=SYSDATE
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10101';
  END IF;
  COMMIT;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_JKGL_COMPUTE_S10102
prompt ==========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_JKGL_COMPUTE_S10102
/*
 * 出口企业法定代表人是否为企业实际控制人
 * ZB_VAL：出口企业填报JKGL_ZLCJ_JGB，以填报结果为准，一致为0，不一致为1
 *         出口企业未填报JKGL_ZLCJ_JGB，查看股东占股比例，小于10%为1，否则为0
 */
(
  P_BGQID   IN NUMBER,
  P_DJXH    IN NUMBER
)
AS
  V_ZB_VAL     NUMBER(18,2);
  V_ROWS       NUMBER(10);
  V_BADPOINT   CHAR(1);
  V_THIS_DATA  NUMBER(18,6);
  V_PARAMS     VARCHAR(1000);
BEGIN
  BEGIN
    SELECT CASE WHEN T.FDDBR_XM=T.SJJYR_XM THEN 0 ELSE 1 END,
           '[d]法定代表人=' || T.FDDBR_XM || '|实际控制人=' || T.SJJYR_XM
      INTO V_ZB_VAL, V_PARAMS
      FROM TL_TSSH.JKGL_ZLCJ_JGB T
     WHERE T.DJXH=P_DJXH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ZB_VAL := NULL;
  END;

  IF V_ZB_VAL IS NULL THEN
    SELECT NVL(T.FDDBR_CGBL,0),
           '[d]法定代表人=' || T.FDDBRMC || '|持股比例=' || NVL(T.FDDBR_CGBL,0) || '%'
      INTO V_THIS_DATA, V_PARAMS
      FROM TL_BJTS.GS_DJ_CKTMSDAB T
     WHERE T.CPCODE=TO_CHAR(P_DJXH);
    IF V_THIS_DATA<10 THEN
      V_ZB_VAL := 1;
    ELSE
      V_ZB_VAL := 0;
    END IF;
  END IF;

  IF V_ZB_VAL IS NULL THEN
    V_BADPOINT := 'Y';
  ELSE
    V_BADPOINT := 'N';
  END IF;

  SELECT COUNT(1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10102' AND ROWNUM=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S10102',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB T
       SET T.ZB_VAL=V_ZB_VAL, T.BADPOINT=V_BADPOINT, T.PARAMS=V_PARAMS, T.UPTIME=SYSDATE
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S10102';
  END IF;
  COMMIT;

  RETURN;
END;
/

