    SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_S30203_SP_CKE_JE';

    V_ZB_VAL := 0;
    FOR CUR_SPDM IN (SELECT T.SP8_DM, DM.CKSP_MC,T.CKEUSD,T.CKDJ,S.CKDJ AS JQDJ
                       FROM TL_TSSH.JKGL_DATA_TJ_ZBU_CKSP T
                      INNER JOIN TL_TSSH.JKGL_DATA_TJ_ZBU_CKSP S ON S.BGQID=P_JQID AND S.SP8_DM=T.SP8_DM
                       LEFT JOIN TL_TSSH.JCFX_DM_CKSPTREE DM ON DM.CKSP_DM=T.SP8_DM AND DM.CKSP_JC='4'
                      WHERE T.BGQID=P_BGQID
                        AND T.CKEUSD>=VAL2
                        AND T.CKDJ>=VAL1 * S.CKDJ)
    LOOP
      V_ZB_VAL := V_ZB_VAL +1;
      IF V_ZB_VAL=1 THEN
        V_PARAMS := '[d]商品代码=' || CUR_SPDM.SP8_DM || '（' || CUR_SPDM.CKSP_MC ||'），报告期出口额=' || CUR_SPDM.CKEUSD || '，出口单价=' || CUR_SPDM.CKDJ || '，基期单价=' || CUR_SPDM.JQDJ;
      ELSIF V_ZB_VAL<=20 THEN
        V_PARAMS := V_PARAMS || '|商品代码=' || CUR_SPDM.SP8_DM  || '（' || CUR_SPDM.CKSP_MC ||'），报告期出口额=' || CUR_SPDM.CKEUSD || '，出口单价=' || CUR_SPDM.CKDJ || '，基期单价=' || CUR_SPDM.JQDJ;
      END IF;
    END LOOP;
    IF V_ZB_VAL>20 THEN
      V_PARAMS := V_PARAMS || '|...';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      V_ZB_VAL := NULL;
  END;

  IF V_ZB_VAL IS NULL THEN
    V_BADPOINT := 'Y';
  ELSE
    V_BADPOINT := 'N';
  END IF;

  SELECT COUNT(1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='S30203' AND ROWNUM=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'S30203',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB T
       SET T.ZB_VAL=V_ZB_VAL, T.BADPOINT=V_BADPOINT, T.PARAMS=V_PARAMS, T.UPTIME=SYSDATE
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='S30203';
  END IF;
  COMMIT;

  RETURN;
END;
