prompt Creating procedure PRO_JKGL_COMPUTE_W20101
prompt ==========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_JKGL_COMPUTE_W20101
/*
 * 跨大类商品退税额
 * ZB_VAL：跨大类商品退税额>XX AND 跨大类商品退税额/报告期_退税额>YY%，返回1
 */
(
  P_BGQID   IN NUMBER,
  P_JQID    IN NUMBER,
  P_SWJGDM  IN VARCHAR
)
AS
  V_ZB_VAL     NUMBER(18,2);
  V_ROWS       NUMBER(10);
  V_BADPOINT   CHAR(1);
  V_THIS_DATA  NUMBER(18,2);
  V_LAST_DATA  NUMBER(18,2);
  VAL1         NUMBER(18,2);    --参数1
  VAL2         NUMBER(18,2);    --参数2
  V_PARAMS     VARCHAR(4000);
  V_PARAM2     VARCHAR(4000);
BEGIN
  BEGIN
    SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
      INTO VAL1
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20101_KDLSP_TSE';
    SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20101_KDLSP_ZB';

    SELECT T.TS_TSE_SB+T.TS_MDE_SB
      INTO V_THIS_DATA
      FROM TL_TSSH.JKGL_DATA_TJ_ZBU T
     WHERE T.BGQID=P_BGQID;

    V_ROWS := 0;
    V_PARAM2 := '';
    V_LAST_DATA :=0;
    FOR CUR_SPDM IN (SELECT T.SP_DL, DM.CKSP_MC, SUM(T.SBTMSE) AS SBTMSE
                       FROM TL_TSSH.JKGL_DATA_TJ_ZBU_TSSP T
                       LEFT JOIN TL_TSSH.JCFX_DM_CKSPTREE DM ON DM.CKSP_DM=T.SP_DL AND DM.CKSP_JC='2'
                      WHERE T.BGQID=P_BGQID
                        AND NOT EXISTS (SELECT 1
                                          FROM TL_TSSH.JKGL_DATA_TJ_ZBU_TSSP S
                                         WHERE S.BGQID=P_JQID
                                           AND S.SP_DL=T.SP_DL)
                      GROUP BY T.SP_DL, DM.CKSP_MC)
    LOOP
      V_ROWS := V_ROWS +1;
      V_LAST_DATA := V_LAST_DATA + CUR_SPDM.SBTMSE;
      IF V_ROWS<=20 THEN
        V_PARAM2 := V_PARAM2 || '|跨大类商品代码=' || CUR_SPDM.SP_DL || '（' || CUR_SPDM.CKSP_MC ||'），申报退免税额=' || CUR_SPDM.SBTMSE;
      END IF;
    END LOOP;
    IF V_ROWS>20 THEN
      V_PARAM2 := V_PARAM2 || '|...';
    END IF;

    V_PARAMS := '[d]报告期申报退(免)税额=' || V_THIS_DATA || '|其中跨大类商品申报退(免)税额=' || V_LAST_DATA;
    IF V_THIS_DATA>0 AND V_LAST_DATA>0 THEN
      IF V_LAST_DATA>=VAL2 AND V_LAST_DATA>=V_THIS_DATA * VAL1 THEN
        V_ZB_VAL := 1;
      ELSE
        V_ZB_VAL := 0;
      END IF;
      V_PARAMS := V_PARAMS || '|占比=' || ROUND(100 * V_LAST_DATA / V_THIS_DATA,2) || '%';
    ELSE
      V_ZB_VAL := 0;
    END IF;
    V_PARAMS := V_PARAMS || V_PARAM2;
  EXCEPTION
    WHEN OTHERS THEN
      V_ZB_VAL := NULL;
  END;

  IF V_ZB_VAL IS NULL THEN
    V_BADPOINT := 'Y';
  ELSE
    V_BADPOINT := 'N';
  END IF;

  SELECT COUNT(1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20101' AND ROWNUM=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W20101',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB T
       SET T.ZB_VAL=V_ZB_VAL, T.BADPOINT=V_BADPOINT, T.PARAMS=V_PARAMS, T.UPTIME=SYSDATE
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20101';
  END IF;
  COMMIT;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_JKGL_COMPUTE_W20103
prompt ==========================================
prompt
CREATE OR REPLACE PROCEDURE PRO_JKGL_COMPUTE_W20103
/*
 * 退税额增长，取统计期往前一季的数据与上一季的比较
 * ZB_VAL：季度环比大于50%且退税额大于50万元，返回1
 */
(
  P_BGQID   IN NUMBER,
  P_JQID    IN NUMBER,
  P_SWJGDM  IN VARCHAR
)
AS
  V_ZB_VAL     NUMBER(18,2);
  V_ROWS       NUMBER(10);
  V_BADPOINT   CHAR(1);
  V_THIS_DATA  NUMBER(18,2);
  V_LAST_DATA  NUMBER(18,2);
  VAL1         NUMBER(18,2);    --参数1
  VAL2         NUMBER(18,2);    --参数2
  V_PARAMS     VARCHAR(4000);
BEGIN
  BEGIN
    SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
      INTO VAL1
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20103_TSE_JE';
    SELECT NVL(S.VAL_DEF,T.VAL_DEF) / DECODE(T.CSTYPE,'百分比',100, 1)
      INTO VAL2
      FROM JKGL_PZ_ZB_CS T
      LEFT JOIN JKGL_PZ_ZB_CS_SWJG S ON S.CSBM=T.CSBM AND S.SWJG_DM=P_SWJGDM AND S.YXBZ='Y'
     WHERE T.CSBM='ZC_W20103_TSE_HB';

    SELECT S.TS_MDE_SB + S.TS_TSE_SB
      INTO V_THIS_DATA
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_BGQID;

    SELECT S.TS_MDE_SB + S.TS_TSE_SB
      INTO V_LAST_DATA
      FROM JKGL_DATA_TJ_ZBU S
     WHERE S.BGQID=P_JQID;

    V_PARAMS := '[d]报告期申报退(免)税额=' || V_THIS_DATA || '|基期申报退(免)税额=' || V_LAST_DATA;
    IF V_THIS_DATA>0 AND V_LAST_DATA>0 THEN
      IF V_THIS_DATA>=VAL1 AND V_THIS_DATA>=VAL2*V_LAST_DATA THEN
        V_ZB_VAL := 1;
      ELSE
        V_ZB_VAL := 0;
      END IF;
    ELSE
      V_ZB_VAL := NULL;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      V_ZB_VAL := NULL;
  END;

  IF V_ZB_VAL IS NULL THEN
    V_BADPOINT := 'Y';
  ELSE
    V_BADPOINT := 'N';
  END IF;

  SELECT COUNT(1)
    INTO V_ROWS
    FROM JKGL_DATA_TJ_ZB T
   WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20103' AND ROWNUM=1;
  IF V_ROWS=0 THEN
    INSERT INTO JKGL_DATA_TJ_ZB(BGQID,ZB_ID,ZB_VAL,BADPOINT,PARAMS)
           VALUES(P_BGQID,'W20103',V_ZB_VAL,V_BADPOINT,V_PARAMS);
  ELSE
    UPDATE JKGL_DATA_TJ_ZB T
       SET T.ZB_VAL=V_ZB_VAL, T.BADPOINT=V_BADPOINT, T.PARAMS=V_PARAMS, T.UPTIME=SYSDATE
     WHERE T.BGQID=P_BGQID AND T.ZB_ID='W20103';
  END IF;
  COMMIT;

  RETURN;
END;
/

