prompt
CREATE OR REPLACE PROCEDURE PRO_JKGL_COMPUTE_W30206
/*
 * 企业本年度出口额相较于上一年度变动情况（首次申报不晚于上月的前一年年初）
 * ZB_VAL：本年出口额大于等于100W，超过上年全年1.5倍返回1，否则返回0
 */
(
  P_BGQID   IN NUMBER,
  P_JQID    IN NUMBER,
  P_SWJGDM  IN VARCHAR
)
AS
  V_ZB_VAL     NUMBER(18,2);
