prompt Creating procedure TEMP_PRO_DEAL_LCTJJC
prompt =======================================
prompt
CREATE OR REPLACE PROCEDURE TEMP_PRO_DEAL_LCTJJC
AS
BEGIN
  --免抵退业务审核信息1
  FOR CUR_SHXX IN (SELECT T.UUID,T.LCSLID_FS
                     FROM TL_TSSH.CKTS_LC_SHXX T
                    WHERE T.LCTJJC IN ('23','22','21','20','10','00') 
                      AND EXISTS (
                          SELECT 1
                            FROM TL_TSSH.CKTS_LC_YWHZXX S
                           WHERE S.LCSLID_FS=T.LCSLID_FS AND S.CKTMSHWYSFWLX_DM='2')
                      AND NOT EXISTS (
                          SELECT 1
                            FROM TL_TSSH.CKTS_LC_SHXX R
                           WHERE R.LCSLID_FS=T.LCSLID_FS AND R.LCTJJC IN ('63','62','61','53','52','51','50','43','42','41','40'))
                  )
  LOOP
    BEGIN
      --LCTJJC
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='00'
       WHERE T.UUID=CUR_SHXX.UUID;
      COMMIT;
      --35号公告代办退税
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='72'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'72' AND T.SBYWB_DM='A0310001';
      COMMIT;
      --17号公告代办退税
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='71'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'71' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.CKTMSYWLXDMJH LIKE 'WMZHFW%');
      COMMIT;
      --综服企业自营业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='70'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'70' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.BAJC_YEAR LIKE '7%');
      COMMIT;
      --国际运输业务
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='63'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'63' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='62'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'62' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='61'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'61' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --研发设计业务
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='53'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'53' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='52'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'52' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='51'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'51' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      --其他服务贸易
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='43'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'43' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='42'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'42' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='41'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'41' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --外贸服务贸易
      --研发设计业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='50'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'50' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      --其他服务贸易
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='40'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'40' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --周边业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='30'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'30' AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
      COMMIT;
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='23'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'23' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='22'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'22' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='21'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'21' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' ';
      COMMIT;
      --外贸企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='10'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'10' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' ';
      COMMIT;

      FOR CUR_HZXX IN (SELECT T.YWHZBUUID,T.CKTMSHWYSFWLX_DM,MAX(S.LCTJJC) AS LCTJJC
                         FROM CKTS_LC_YWHZXX T
                        INNER JOIN CKTS_LC_SHXX S ON S.LCSLID_FS=T.LCSLID_FS
                        WHERE T.LCSLID_FS=CUR_SHXX.LCSLID_FS
                        GROUP BY T.YWHZBUUID,T.CKTMSHWYSFWLX_DM)
      LOOP
        UPDATE CKTS_LC_YWHZXX A
           SET A.LCTJJC=(CASE WHEN (CUR_HZXX.LCTJJC IN ('72','71','70','30','23','22','21','10')) OR (CUR_HZXX.CKTMSHWYSFWLX_DM='2') THEN CUR_HZXX.LCTJJC
                              ELSE (CASE WHEN CUR_HZXX.LCTJJC IN ('63','53','43') THEN '23'
                                         WHEN CUR_HZXX.LCTJJC IN ('62','52','42') THEN '22'
                                         WHEN CUR_HZXX.LCTJJC IN ('61','51','41') THEN '21'
                                         WHEN CUR_HZXX.LCTJJC IN ('50','40') THEN '10'
                                         ELSE '00'
                                   END)
                        END)
         WHERE A.YWHZBUUID=CUR_HZXX.YWHZBUUID;
        COMMIT;
        UPDATE CKTS_LC_SEHZXX B
           SET B.LCTJJC =(SELECT A.LCTJJC FROM CKTS_LC_YWHZXX A WHERE A.YWHZBUUID=B.YWHZBUUID AND ROWNUM=1)
         WHERE B.YWHZBUUID=CUR_HZXX.YWHZBUUID;
        COMMIT;
      END LOOP;
    END;
  END LOOP;

  --免抵退业务审核信息1
  FOR CUR_SHXX IN (SELECT T.UUID,T.LCSLID_FS
                     FROM TL_TSSH.CKTS_LC_SHXX T
                    WHERE T.LCTJJC IN ('23','22','21','20','10','00') 
                      AND T.DJXH IN (
                          SELECT A.DJXH
                            FROM TL_TSSH.CKTS_LC_SHXX A
                           WHERE A.LCTJJC IN ('21','22','23') AND A.LCJSRQ>=DATE'2026-01-01'
                            GROUP BY A.DJXH HAVING COUNT(DISTINCT A.LCTJJC)>1)
                  )
  LOOP
    BEGIN
      --LCTJJC
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='00'
       WHERE T.UUID=CUR_SHXX.UUID;
      COMMIT;
      --35号公告代办退税
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='72'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'72' AND T.SBYWB_DM='A0310001';
      COMMIT;
      --17号公告代办退税
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='71'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'71' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_CKMX A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.CKTMSYWLXDMJH LIKE 'WMZHFW%');
      COMMIT;
      --综服企业自营业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='70'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'70' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND A.BAJC_YEAR LIKE '7%');
      COMMIT;
      --国际运输业务
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='63'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'63' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='62'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'62' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='61'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'61' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_GJYS A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --研发设计业务
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='53'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'53' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='52'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'52' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'))
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='51'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'51' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      --其他服务贸易
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='43'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'43' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='42'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'42' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB)
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='41'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'41' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MDT_YFSJ A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --外贸服务贸易
      --研发设计业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='50'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'50' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB AND A.YSFW_DM IN ('9902000000','9903000000'));
      COMMIT;
      --其他服务贸易
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='40'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'40' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM CKTS_SB_MTS_YSFW A WHERE A.LCSLID_SB=T.LCSLID_SB);
      COMMIT;
      --周边业务
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='30'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'30' AND T.SBYWB_DM IN ('A0302001','A0303001','A0304001');
      COMMIT;
      --外商投资企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='23'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'23' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND SUBSTR(A.DJZCLX_JS,0,1) IN ('2','3'));
      COMMIT;
      --委托出口企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='22'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'22' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' '
         AND EXISTS (SELECT 1 FROM GLXT_BB_SHXT_DJXX A WHERE A.DJXH_JS=T.DJXH AND LENGTH(A.QYHGDM)=10 AND A.QYHGDM LIKE '9%');
      COMMIT;
      --内资生产企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='21'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'21' AND T.SBYWB_DM='A0305001' AND T.LCSLID_SB<>' ';
      COMMIT;
      --外贸企业
      UPDATE CKTS_LC_SHXX T
         SET T.LCTJJC='10'
       WHERE T.UUID=CUR_SHXX.UUID AND T.LCTJJC<'10' AND T.SBYWB_DM='A0301001' AND T.LCSLID_SB<>' ';
      COMMIT;

      FOR CUR_HZXX IN (SELECT T.YWHZBUUID,T.CKTMSHWYSFWLX_DM,MAX(S.LCTJJC) AS LCTJJC
                         FROM CKTS_LC_YWHZXX T
                        INNER JOIN CKTS_LC_SHXX S ON S.LCSLID_FS=T.LCSLID_FS
                        WHERE T.LCSLID_FS=CUR_SHXX.LCSLID_FS
                        GROUP BY T.YWHZBUUID,T.CKTMSHWYSFWLX_DM)
      LOOP
        UPDATE CKTS_LC_YWHZXX A
           SET A.LCTJJC=(CASE WHEN (CUR_HZXX.LCTJJC IN ('72','71','70','30','23','22','21','10')) OR (CUR_HZXX.CKTMSHWYSFWLX_DM='2') THEN CUR_HZXX.LCTJJC
                              ELSE (CASE WHEN CUR_HZXX.LCTJJC IN ('63','53','43') THEN '23'
                                         WHEN CUR_HZXX.LCTJJC IN ('62','52','42') THEN '22'
                                         WHEN CUR_HZXX.LCTJJC IN ('61','51','41') THEN '21'
                                         WHEN CUR_HZXX.LCTJJC IN ('50','40') THEN '10'
                                         ELSE '00'
                                   END)
                        END)
         WHERE A.YWHZBUUID=CUR_HZXX.YWHZBUUID;
        COMMIT;
        UPDATE CKTS_LC_SEHZXX B
           SET B.LCTJJC =(SELECT A.LCTJJC FROM CKTS_LC_YWHZXX A WHERE A.YWHZBUUID=B.YWHZBUUID AND ROWNUM=1)
         WHERE B.YWHZBUUID=CUR_HZXX.YWHZBUUID;
        COMMIT;
      END LOOP;
    END;
  END LOOP;
  RETURN;
END;
