    IF V_ROWS>0 THEN
      UPDATE JKGL_DATA_BGQ T
         SET T.DZSP_ZT='N'
       WHERE T.SXZT='3' AND T.DZSP_ZT='Y'
         AND EXISTS (SELECT 1 FROM JKGL_DATA_TJ_ZBU S WHERE S.BGQID=T.BGQID AND S.DZ_WTJG IS NULL);
      COMMIT;
    END IF;

    SELECT COUNT(1)
      INTO V_ROWS
      FROM TL_TSSH.JKGL_DATA_BGQ T
     INNER JOIN JKGL_DATA_TJ_ZBU S ON S.BGQID=T.BGQID
     WHERE T.SXZT='3' AND T.DZSP_ZT='Y' AND S.DZ_YFJE IS NULL;
    IF V_ROWS>0 THEN
      UPDATE JKGL_DATA_BGQ T
         SET T.DZSP_ZT='N'
       WHERE T.SXZT='3' AND T.DZSP_ZT='Y'
         AND EXISTS (SELECT 1 FROM JKGL_DATA_TJ_ZBU S WHERE S.BGQID=T.BGQID AND S.DZ_YFJE IS NULL);
      COMMIT;
    END IF;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure TEMP_PRO_JKGL_COMPUTE_ZBANDJKM
prompt =================================================
prompt
CREATE OR REPLACE PROCEDURE TEMP_PRO_JKGL_COMPUTE_ZBANDJKM
AS
BEGIN
  INSERT INTO JKGL_LOG_DEALDATA(CZJL) VALUES ('TEMP_PRO_JKGL_COMPUTE_ZBANDJKM开始处理！');
  COMMIT;
/*
  INSERT INTO JKGL_DATA_QYJKM_LSB(ID,DJXH,JKM_LEVEL,SCORE_10,SCORE_20,SCORE_30,SCORE_40,SCORE_50,SCORE_60,SCORE_ZH,
              UPTIME,TSJSFS_DM,NOTE,RGFM_LEVEL,RGFMSJ,FMYXQ,CZYDM,CZYMC,RGBZMS)
       SELECT SEQ_JKGL_DATA_QYJKM_LSB.NEXTVAL,DJXH,JKM_LEVEL,SCORE_10,SCORE_20,SCORE_30,SCORE_40,SCORE_50,SCORE_60,SCORE_ZH,
              T.UPTIME,T.TSJSFS_DM,'2024',T.RGFM_LEVEL,T.RGFMSJ,T.FMYXQ,T.CZYDM,T.CZYMC,T.RGBZMS
         FROM JKGL_DATA_QYJKM_JGB T;
  COMMIT;
  INSERT INTO JKGL_LOG_DEALDATA(CZJL) VALUES ('INSERT INTO JKGL_DATA_QYJKM_LSB 2024 结束！');
  COMMIT;
*/
  EXECUTE IMMEDIATE 'TRUNCATE TABLE JKGL_DATA_ZB_JGB';
  COMMIT;
  INSERT INTO TL_TSSH.JKGL_DATA_ZB_JGB(DJXH,ZB_ID,ZB_VAL,BADPOINT,SCORE,JS_STATUS,FF_STATUS,UPTIME,PARAMS)
       SELECT B.DJXH,Z.ZB_ID,Z.ZB_VAL,Z.BADPOINT, 0,'1','0',SYSDATE, Z.PARAMS 
                FROM TL_TSSH.GLXT_BB_SHXT_DJXX D, TL_TSSH.JKGL_DATA_BGQ B, TL_TSSH.JKGL_DATA_TJ_ZB Z
               WHERE B.BGQID=Z.BGQID AND D.DJXH_JS=B.DJXH
                 AND B.BGQ_Q=DATE'2025-01-01' AND B.BGQ_Z=DATE'2025-12-31';
  INSERT INTO JKGL_LOG_DEALDATA(CZJL) VALUES ('MERGE INTO TL_TSSH.JKGL_DATA_ZB_JGB 2025结束！');
  COMMIT;

  EXECUTE IMMEDIATE 'TRUNCATE TABLE JKGL_DATA_QYJKM_JGB';
  COMMIT;
  INSERT INTO JKGL_DATA_QYJKM_JGB(DJXH,TSJSFS_DM,CRTIME)
       SELECT T.DJXH_JS,T.JSMODE,SYSDATE 
         FROM GLXT_BB_SHXT_DJXX T 
        WHERE EXISTS (SELECT 1 
                        FROM JKGL_DATA_ZB_JGB Z 
                       WHERE T.DJXH_JS=Z.DJXH AND Z.FF_STATUS='0' AND Z.ZB_ID IN ('W10101','S10101')) 
          AND NOT EXISTS (SELECT 1 
                            FROM JKGL_DATA_QYJKM_JGB U 
                           WHERE U.DJXH=T.DJXH_JS);
  INSERT INTO JKGL_LOG_DEALDATA(CZJL) VALUES ('MERGE INTO TL_TSSH.JKGL_DATA_QYJKM_JGB 2025 结束！');
  COMMIT;

  PRO_JKGL_JKM_MAIN(NULL,NULL);
  INSERT INTO JKGL_LOG_DEALDATA(CZJL) VALUES ('PRO_JKGL_JKM_MAIN 2025 结束！');
  COMMIT;

  RETURN;
END;
/

