prompt Creating trigger TRU_YWY_BAXX_GCB
prompt =================================
prompt
create or replace trigger tru_ywy_baxx_gcb before update or insert
on YWY_BAXX_GCB for each row
declare
   v_cnt integer;
begin
  -- 当备案状态变为已备案时，更新结果表
  if :new.bazt ='2' then
    select count(*) into v_cnt from tl_tssh.ywy_baxx_JGB
           where id = :new.id;
    if v_cnt = 0 then
        insert into tl_tssh.ywy_baxx_JGB(
          ID    ,DJXH  ,ZJLX  ,ZJHM  ,XM  ,
          SEX ,PHONE ,STATUS  ,GZRQ_Q  ,GZRQ_Z  ,
          CKCPFW  ,SFQDLDHT  ,SFDJSB  ,YWYLY ,QTLYMS  ,
          ZJ_HASH ,ZFBZ  ,ZFSJ  ,CR_TIME ,UP_TIME ,
          QRBZ  ,BAZT  ,TJSJ  ,BASJ  ,THSJ  ,THYY ,QRR_DM  ,QRSJ
        )
        values(
          :new.ID,:new.DJXH,:new.ZJLX,:new.ZJHM,:new.XM,
          :new.SEX,:new.PHONE,:new.STATUS,:new.GZRQ_Q,:new.GZRQ_Z,
          :new.CKCPFW,:new.SFQDLDHT,:new.SFDJSB,:new.YWYLY,:new.QTLYMS,
          :new.ZJ_HASH,:new.ZFBZ,:new.ZFSJ,:new.CR_TIME,:new.UP_TIME,
          :new.QRBZ,:new.BAZT,:new.TJSJ,:new.BASJ,:new.THSJ,:new.THYY,:new.QRR_DM,:new.QRSJ
        );
    else
        update tl_tssh.ywy_baxx_JGB
          set
          DJXH=:new.DJXH  ,ZJLX=:new.ZJLX  ,ZJHM=:new.ZJHM  ,XM=:new.XM  ,
          SEX=:new.SEX ,PHONE=:new.PHONE ,STATUS=:new.STATUS  ,GZRQ_Q=:new.GZRQ_Q  ,GZRQ_Z=:new.GZRQ_Z  ,
          CKCPFW=:new.CKCPFW  ,SFQDLDHT=:new.SFQDLDHT  ,SFDJSB=:new.SFDJSB  ,YWYLY=:new.YWYLY ,QTLYMS=:new.QTLYMS  ,
          ZJ_HASH=:new.ZJ_HASH ,ZFBZ=:new.ZFBZ  ,ZFSJ=:new.ZFSJ  ,CR_TIME=:new.CR_TIME ,UP_TIME=:new.UP_TIME ,
          QRBZ=:new.QRBZ  ,BAZT=:new.BAZT  ,TJSJ=:new.TJSJ  ,BASJ=:new.BASJ  ,THSJ=:new.THSJ  ,THYY=:new.THYY ,
          QRR_DM=:new.QRR_DM  ,QRSJ=:new.QRSJ
          where id=:new.id;
    end if;
  end if;
end;
/

